import * as os from 'os';
import * as fs from 'fs';

const BUFSIZE = 8192;

class FastIO {
    private _fd: number;
    private buffer: Buffer;
    private writable: boolean;

    constructor(file: any) {
        this._fd = file.fd;
        this.buffer = Buffer.alloc(BUFSIZE);
        this.writable = "x" in file.flags || "r" not in file.flags;
    }

    read(): string {
        let b = fs.readSync(this._fd, this.buffer, 0, BUFSIZE, null);
        if (b === 0) return '';
        return this.buffer.toString('ascii', 0, b);
    }

    readline(): string {
        let data = '';
        while (!data.includes('\n')) {
            data += this.read();
        }
        return data.split('\n')[0];
    }

    flush() {
        if (this.writable) {
            fs.writeSync(this._fd, this.buffer.toString('ascii'));
            this.buffer.fill(0);
        }
    }
}

class IOWrapper {
    private buffer: FastIO;

    constructor(file: any) {
        this.buffer = new FastIO(file);
    }

    read(): string {
        return this.buffer.read();
    }

    readline(): string {
        return this.buffer.readline();
    }

    write(s: string) {
        this.buffer.write(s);
    }

    flush() {
        this.buffer.flush();
    }
}

