const BUFSIZE = 8192;

class FastIO {
    private _fd: number;
    private buffer: Buffer;
    private writable: boolean;

    constructor(file: NodeJS.ReadStream | NodeJS.WriteStream) {
        this._fd = (file as any).fd;
        this.buffer = Buffer.alloc(0);
        this.writable = file.writable;
    }

    read(): string {
        while (true) {
            const b = fs.readSync(this._fd, BUFSIZE);
            if (b === 0) break;
            this.buffer = Buffer.concat([this.buffer, Buffer.from(b)]);
        }
        return this.buffer.toString();
    }

    readline(): string {
        let data = '';
        while (!data.includes('\n')) {
            const b = fs.readSync(this._fd, BUFSIZE);
            if (b === 0) break;
            data += Buffer.from(b).toString();
        }
        return data.split('\n')[0];
    }

    flush() {
        if (this.writable) {
            process.stdout.write(this.buffer.toString());
            this.buffer = Buffer.alloc(0);
        }
    }
}

class IOWrapper {
