// Educational Codeforces Round 119 (Rated for Div. 2)
// C. BA-String

function solve(): void {
    const input = require('fs').readFileSync(0, 'utf8').trim().split('\n');
    let line = 0;

    function readLine(): string[] {
        return input[line++].split(' ');
    }

    const [n, k, x] = readLine().map(Number);
    const s = input[line++];

    if (!s.includes('*')) {
        console.log(s);
        return;
    }

    const stars = s.split('a').filter(Boolean);

    // A string of q stars can expand to 0, 1, 2, ..., q * k b's, which is
    // 1 + k * q possibilities
    const expand = stars.map(star => 1 + k * star.length);

    // Cumulative product of number of stars
    const prods: number[] = [expand[expand.length - 1]];
    for (let i = 1; i < stars.length; i++) {
        prods.push(prods[i - 1] * expand[stars.length - i - 1]);
    }

    let xCopy = x - 1;

    // Count how many b's to replace each * by
    const counts: number[] = [];
    for (const prod of [...prods].reverse()) {
        counts.push(Math.floor(xCopy / prod));
        xCopy -= prod * Math.floor(xCopy / prod);
    }
    counts.push(xCopy % prods[0]);

    // Construct the string
    let answer = '';
    let i = 1;
    let j = 0;
    while (j < s.length) {
        if (s[j] === 'a') {
            answer += 'a';
            j++;
        } else {
            answer += 'b'.repeat(counts[i]);
            i++;
            while (j < s.length && s[j] === '*') {
                j++;
            }
        }
    }

    console.log(answer);
}

