rl.on('line', (line) => {
    const t = parseInt(line);
    let count = 0;

    const readNextCase = () => {
        if (count >= t) {
            rl.close();
            return;
        }
        count++;

        rl.once('line', (_) => {
            rl.once('line', (dimensions) => {
                const [n, m] = dimensions.split(' ').map(Number);
                const d: number[][] = [];

                let readLines = 0;
                const readMatrixLine = () => {
                    if (readLines >= n) {
                        solve(n, m, d);
                        return;
                    }
                    rl.once('line', (matrixLine) => {
                        d.push(matrixLine.split('').map(j => {
                            switch (j) {
                                case 'R': return -1;
                                case 'U': return -2;
                                case 'L': return -3;
                                default: return -4;
                            }
                        }));
                        readLines++;
                        readMatrixLine();
                    });
                };
                readMatrixLine();
            });
        });
    };

    readNextCase();
});

function solve(n: number, m: number, d: number[][]) {
    let r = 0;
    let pos: [number, number] = [0, 0];

    for (let i = 0; i < n; i++) {
        for (let j = 0; j < m; j++) {
            let a = i, b = j, p = d[i][j], c = 0;
            const st: [number, number][] = [];

            while (p < 0) {
                d[a][b] = 0;
                st.push([a, b]);
                if (p === -1) b++;
                else if (p === -2) a--;
                else if (p === -3) b--;
                else a++;

                c++;
                if (0 <= a && a < n && 0 <= b && b < m) {
                    p = d[a][b];
                } else {
                    for (let ii = 0; ii < st.length; ii++) {
                        const [x, y] = st[ii];
                        d[x][y] = c - ii;
                    }
                    p = -1;
                    break;
                }
            }

            if (p === 0) {
                let jj = 0, flag = 0;
                for (let ii = 0; ii < st.length; ii++) {
                    const [x, y] = st[ii];
                    d[x][y] = flag ? c - jj : c - ii;
                    if (x === a && y === b) {
                        flag = 1;
                        jj = ii;
                    }
                }
            }

            if (p > 0) {
                for (let ii = 0; ii < st.length; ii++) {
                    const [x, y] = st[ii];
                    d[x][y] = p + c - ii;
                }
            }

            if (d[i][j] > r) {
                r = d[i][j];
                pos = [i, j];
            }
        }
    }

    console.log(pos[0] + 1, pos[1] + 1, r);
}

