const BUFSIZE = 8192;

class FastIO {
    private _fd: number;
    private buffer: Buffer;
    private writable: boolean;

    constructor(file: NodeJS.ReadStream | NodeJS.WriteStream) {
        this._fd = file.fd!;
        this.buffer = Buffer.alloc(0);
        this.writable = "x" in (file as any).mode || "r" not in (file as any).mode;
    }

    public read(): string {
        while (true) {
            const b = Buffer.from(fs.readSync(this._fd, BUFSIZE));
            if (b.length === 0) break;
            this.buffer = Buffer.concat([this.buffer, b]);
        }
        return this.buffer.toString();
    }

    public readline(): string {
        let result = "";
        while (!result.includes("\n")) {
            const b = Buffer.from(fs.readSync(this._fd, BUFSIZE));
            if (b.length === 0) break;
            this.buffer = Buffer.concat([this.buffer, b]);
            result += this.buffer.toString();
        }
        return result.split("\n").shift()!;
    }

    public flush(): void {
        if (this.writable) {
            fs.writeSync(this._fd, this.buffer);
            this.buffer = Buffer.alloc(0);
        }
    }
}

class IOWrapper {
    private buffer: FastIO;

    constructor(file: NodeJS.ReadStream | NodeJS.WriteStream) {
        this.buffer = new FastIO(file);
    }

    public read(): string {
        return this.buffer.read().toString();
    }

    public readline(): string {
        return this.buffer.readline().trim();
    }

    public write(s: string): void {
        this.buffer.write(Buffer.from(s));
    }

    public flush(): void {
        this.buffer.flush();
    }
}

