func nextLargerElement(arr []int, n int, f bool) []int {
	var s []int
	ans := make([]int, n)
	for i := 0; i < n; i++ {
		for len(s) > 0 && arr[s[len(s)-1]] < arr[i] {
			s = s[:len(s)-1]
		}
		if len(s) > 0 {
			ans[i] = s[len(s)-1]
		}
		s = append(s, i)
	}
	if f {
		for i := 0; i < n; i++ {
			if ans[i] != -1 {
				ans[i] = n - 1 - ans[i]
			}
		}
	}
	return ans
}

func dfs(i int, adj [][]int, p int, ans int) int {
	f := true
	a1 := 0
	for _, j := range adj[i] {
		if j != p {
			a1 += dfs(j, adj, i, ans+1)
			f = false
		}
	}
	if f {
		a1 += ans * (ans - 1) / 2
	}
	return a1
}

