	nStr, _ := reader.ReadString('\n')
	n, _ := strconv.Atoi(strings.TrimSpace(nStr))

	for i := 0; i < n; i++ {
		runCase(reader)
	}
}

func runCase(reader *bufio.Reader) {
	nStr, _ := reader.ReadString('\n')
	n, _ := strconv.Atoi(strings.TrimSpace(nStr))
	alstStr, _ := reader.ReadString('\n')
	alst := make([]int, n)
	pos := make([]int, n)

	for i := range pos {
		pos[i] = -1
	}

	split := strings.Fields(alstStr)
	for i := 0; i < n; i++ {
		a, _ := strconv.Atoi(split[i])
		a--
		alst[i] = a
		if (a-i)%2 == 1 {
			fmt.Println(-1)
			return
		}
		pos[a] = i
	}

	ans := []int{}
	for i := n - 1; i > 0; i -= 2 {
		p := pos[i]
		ans = append(ans, p+1)
		reverseAndSwap(alst, pos, p/2)
		p = pos[i-1]
		ans = append(ans, p)
		p--
		reverseAndSwap(alst, pos, p/2)
		ans = append(ans, p+3)
		p += 2
		reverseAndSwap(alst, pos, p/2)
		p = 2
		ans = append(ans, 3)
		reverseAndSwap(alst, pos, p/2)
		p = i
		ans = append(ans, p+1)
		reverseAndSwap(alst, pos, p/2)
	}

	fmt.Println(len(ans))
	for _, v := range ans {
		fmt.Print(v, " ")
	}
	fmt.Println()
}

func reverseAndSwap(alst []int, pos []int, steps int) {
	for j := 0; j < steps; j++ {
		alst[j], alst[len(alst)-1-j] = alst[len(alst)-1-j], alst[j]
		pos[alst[j]], pos[alst[len(alst)-1-j]] = pos[alst[len(alst)-1-j]], pos[alst[j]]
	}
}

