func solve() {
	reader := bufio.NewReader(os.Stdin)
	var n, k, x int
	fmt.Fscanf(reader, "%d %d %d\n", &n, &k, &x)
	s, _ := reader.ReadString('\n')
	s = strings.TrimSpace(s)

	if !strings.ContainsRune(s, '*') {
		fmt.Println(s)
		return
	}

	stars := strings.Split(strings.ReplaceAll(s, "a", ""), "*")
	var expand []int
	for _, star := range stars {
		if len(star) > 0 {
			expand = append(expand, 1+k*len(star))
		}
	}

	prods := make([]int, len(expand))
	prods[len(prods)-1] = expand[len(expand)-1]
	for i := 1; i < len(expand); i++ {
		prods[len(prods)-i-1] = prods[len(prods)-i] * expand[len(expand)-i-1]
	}

	x--

	counts := []int{}
	for _, prod := range prods {
		counts = append(counts, x/prod)
		x -= prod * (x / prod)
	}
	counts = append(counts, x%prods[0])

	answer := ""
	i := 1
	j := 0
	for j < len(s) {
		if s[j] == 'a' {
			answer += "a"
			j++
		} else {
			answer += strings.Repeat("b", counts[i])
			i++
			for j < len(s) && s[j] == '*' {
				j++
			}
		}
	}

	fmt.Println(answer)
}

