import (
	"bufio"
	"fmt"
	"math"
	"os"
	"strconv"
	"strings"
)

func process(A []int, B []int, Q [][]int) []int {
	S := []int{0}
	n := len(A)
	for i := 0; i < n; i++ {
		ai := A[i]
		bi := B[i]
		di := bi - ai
		S = append(S, S[len(S)-1]+di)
	}
	n = len(S)
	p := math.Ceil(math.Log(float64(n)) / math.Log(2))
	p = int(math.Pow(2, p))
	minTree := make([]int, 2*p-1)
	maxTree := make([]int, 2*p-1)
	for i := 0; i < p; i++ {
		if i < n {
			minTree[i] = S[i]
			maxTree[i] = S[i]
		} else {
			minTree[i] = math.MaxInt32
			maxTree[i] = math.MinInt32
		}
	}
	for i := p; i < 2*p-1; i++ {
		i1 := (2*p - 2) - i
		j1 := 2*i1 + 1
		j2 := 2*i1 + 2
		iLeft := (2*p - 2) - j1
		iRight := (2*p - 2) - j2
		minTree[i] = min(minTree[iLeft], minTree[iRight])
		maxTree[i] = max(maxTree[iLeft], maxTree[iRight])
	}

	var findMax func(l, r, startL, startR, startIndex int) int
	findMax = func(l, r, startL, startR, startIndex int) int {
		if startIndex < 0 {
			return math.MinInt32
		}
		if l == r {
			return maxTree[l]
		}
		if l == startL && r == startR {
			return maxTree[startIndex]
		}
		i1 := (2*p - 2) - startIndex
		iL := (2*p - 2) - (2*i1 + 2)
		iR := (2*p - 2) - (2*i1 + 1)
		m1 := (startL + startR) / 2
		if l > m1 {
			return findMax(l, r, m1+1, startR, iR)
		} else if r <= m1 {
			return findMax(l, r, startL, m1, iL)
		} else {
			max1 := findMax(l, m1, startL, m1, iL)
			max2 := findMax(m1+1, r, m1+1, startR, iR)
			return max(max1, max2)
		}
	}

	var findMin func(l, r, startL, startR, startIndex int) int
	findMin = func(l, r, startL, startR, startIndex int) int {
		if startIndex < 0 {
			return math.MaxInt32
		}
		if l == r {
			return minTree[l]
		}
		if l == startL && r == startR {
			return minTree[startIndex]
		}
		i1 := (2*p - 2) - startIndex
		iL := (2*p - 2) - (2*i1 + 2)
		iR := (2*p - 2) - (2*i1 + 1)
		m1 := (startL + startR) / 2
		if l > m1 {
			return findMin(l, r, m1+1, startR, iR)
		} else if r <= m1 {
			return findMin(l, r, startL, m1, iL)
		} else {
			min1 := findMin(l, m1, startL, m1, iL)
			min2 := findMin(m1+1, r, m1+1, startR, iR)
			return min(min1, min2)
		}
	}

	answer := []int{}
	for _, qr := range Q {
		l, r := qr[0], qr[1]
		s1 := S[l-1]
		s2 := S[r]
		if s1 != s2 {
			answer = append(answer, -1)
		} else {
			myMin := findMin(l, r, 0, p-1, 2*p-2)
			myMax := findMax(l, r, 0, p-1, 2*p-2)
			if myMin-s1 < 0 {
				answer = append(answer, -1)
			} else {
				answer = append(answer, myMax-s1)
			}
		}
	}
	return answer
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	nkLine, _ := reader.ReadString('\n')
	nk := strings.Fields(nkLine)
	n, _ := strconv.Atoi(nk[0])
	k, _ := strconv.Atoi(nk[1])

	Aline, _ := reader.ReadString('\n')
	Astr := strings.Fields(Aline)
	A := make([]int, n)
	for i := 0; i < n; i++ {
		A[i], _ = strconv.Atoi(Astr[i])
	}

	Bline, _ := reader.ReadString('\n')
	Bstr := strings.Fields(Bline)
	B := make([]int, n)
	for i := 0; i < n; i++ {
		B[i], _ = strconv.Atoi(Bstr[i])
	}

	Q := make([][]int, k)
	for i := 0; i < k; i++ {
		qLine, _ := reader.ReadString('\n')
		qStr := strings.Fields(qLine)
		l, _ := strconv.Atoi(qStr[0])
		r, _ := strconv.Atoi(qStr[1])
