				case "R":
					d[i][j] = -1
				case "U":
					d[i][j] = -2
				case "L":
					d[i][j] = -3
				default:
					d[i][j] = -4
				}
			}
		}
		r := 0
		var pos [2]int
		for i := 0; i < n; i++ {
			for j := 0; j < m; j++ {
				a, b, p, c := i, j, d[i][j], 0
				st := make([][2]int, 0)
				for p < 0 {
					d[a][b] = 0
					st = append(st, [2]int{a, b})
					switch p {
					case -1:
						b++
					case -2:
						a--
					case -3:
						b--
					default:
						a++
					}
					c++
					if a >= 0 && a < n && b >= 0 && b < m {
						p = d[a][b]
					} else {
						for ii, coord := range st {
							d[coord[0]][coord[1]] = c - ii
						}
						p = -1
						break
					}
				}
				if p == 0 {
					jj, flag := 0, false
					for ii, coord := range st {
						if flag {
							d[coord[0]][coord[1]] = c - jj
						} else {
							d[coord[0]][coord[1]] = c - ii
						}
						if coord[0] == a && coord[1] == b {
							flag = true
							jj = ii
						}
					}
				}
				if p > 0 {
					for ii, coord := range st {
						d[coord[0]][coord[1]] = p + c - ii
					}
				}
				if d[i][j] > r {
					r = d[i][j]
					pos = [2]int{i, j}
				}
			}
		}
		fmt.Println(pos[0]+1, pos[1]+1, r)
	}
