const (
	mod = 1000000007
	inf = 1 << 60
)

type Dsu struct {
	parent []int
}

func NewDsu(n int) *Dsu {
	d := &Dsu{parent: make([]int, n+1)}
	for i := 1; i <= n; i++ {
		d.parent[i] = i
	}
	return d
}

func (d *Dsu) findParent(node int) int {
	if node == d.parent[node] {
		return node
	}
	d.parent[node] = d.findParent(d.parent[node])
	return d.parent[node]
}

func (d *Dsu) union(u, v int) bool {
	uParent := d.findParent(u)
	vParent := d.findParent(v)

	if uParent != vParent {
		d.parent[vParent] = uParent
		return true
	}
	return false
}

func mp(scanner *bufio.Scanner) []int {
	scanner.Scan()
	input := strings.Fields(scanner.Text())
	result := make([]int, len(input))
	for i, s := range input {
		result[i], _ = strconv.Atoi(s)
	}
	return result
}

func it(scanner *bufio.Scanner) int {
	scanner.Scan()
	input := scanner.Text()
	result, _ := strconv.Atoi(strings.TrimSpace(input))
	return result
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	scanner := bufio.NewScanner(reader)
	n, m1, m2 := mp(scanner)[0], mp(scanner)[0], mp(scanner)[0]

	d1 := NewDsu(n)
	d2 := NewDsu(n)

	flag := false
	for i := 0; i < m1; i++ {
		u, v := mp(scanner)[0], mp(scanner)[0]
		if !d1.union(u, v) {
			flag = true
		}
	}

	for i := 0; i < m2; i++ {
		u, v := mp(scanner)[0], mp(scanner)[0]
		if !d2.union(u, v) {
			flag = true
		}
	}

	if flag {
		fmt.Println(0)
		return
	}

	var v [][]int
	for i := 1; i <= n; i++ {
		for j := i + 1; j <= n; j++ {
			y := d1.findParent(j)
			y1 := d1.findParent(y)
			x := d2.findParent(j)
			x1 := d2.findParent(x)

			if !d1.union(i, j) {
				d1.parent[y] = y1
			} else if !d2.union(i, j) {
				d2.parent[x] = x1
				d1.parent[y] = y1
			} else {
				d1.union(i, j)
				d2.union(i, j)
				v = append(v, []int{i, j})
			}
		}
	}

	fmt.Println(len(v))
	for _, pair := range v {
		fmt.Println(pair[0], pair[1])
	}
}

