func (fio *FastIO) ReadLine() (string, error) {
	var (
		result []byte
		isPrefix bool
		err error
	)
	for {
		var buf [BUFSIZE]byte
		n, err := fio.reader.Read(buf[:])
		if err != nil && err != io.EOF {
			return "", err
		}
		result = append(result, buf[:n]...)
		if !isPrefix {
			break
		}
	}
	return string(result), err
}

