const mod = 998244353

func egcd(a, b int) (int, int, int) {
	if a == 0 {
		return b, 0, 1
	}
	g, y, x := egcd(b%a, a)
	return g, x - (b/a)*y, y
}

func modinv(a, m int) int {
	g, x, _ := egcd(a, m)
	if g != 1 {
		panic("modular inverse does not exist")
	}
	return (x % m + m) % m
}

func choose(n, k, p int) int {
	if k == 0 {
		return 1
	}
	x := n
	for y := n - 1; y > n-k; y-- {
		x = x * y % p
	}
	d := 1
	for i := 2; i <= k; i++ {
		d = d * i % p
	}
	return x * modinv(d, p) % p
}

func solve() {
	scanner := bufio.NewScanner(os.Stdin)
	var n int
	fmt.Fscanf(scanner, "%d\n", &n)

	wb_poss := n > 1
	bw_poss := n > 1
	w := 0
	b := 0
	q := 0
	free := 0
	any_bad_poss := n > 1

	for i := 0; i < n; i++ {
		scanner.Scan()
		s := strings.TrimSpace(scanner.Text())
		if s[0] == 'B' {
			b++
			wb_poss = false
		} else if s[0] == 'W' {
			w++
			bw_poss = false
		} else if s[0] == '?' {
			q++
		}
		if s[1] == 'B' {
			b++
			bw_poss = false
		} else if s[1] == 'W' {
			w++
			wb_poss = false
		} else if s[1] == '?' {
			q++
		}
		if s == "???" {
			free++
		} else if s[0] == s[1] {
			any_bad_poss = false
		}
	}

	w_needed := n - w
	if w_needed > q || w_needed < 0 {
		fmt.Println(0)
		return
	}

	var num_bad_poss int
	if any_bad_poss {
		num_bad_poss = pow(2, free, mod)
		num_bad_poss -= (wb_poss + bw_poss)
	} else {
		num_bad_poss = 0
	}

	fmt.Println((choose(q, w_needed, mod)-num_bad_poss+mod)%mod)
}

func pow(base, exp, mod int) int {
	result := 1
	for exp > 0 {
		if exp%2 == 1 {
			result = result * base % mod
		}
		exp = exp >> 1
		base = base * base % mod
	}
	return result
}

