	buffer   []byte
	writable bool
}

func NewFastIO(file *os.File) *FastIO {
	return &FastIO{
		fd:       file,
		buffer:   make([]byte, 0),
		writable: file != os.Stdin,
	}
}

func (f *FastIO) Read() string {
	var b []byte
	for {
		buf := make([]byte, BUFSIZE)
		n, err := f.fd.Read(buf)
		if n == 0 || err != nil {
			break
		}
		b = append(b, buf[:n]...)
	}
	return string(b)
}

func (f *FastIO) ReadLine() string {
	var b []byte
	for {
		buf := make([]byte, BUFSIZE)
		n, err := f.fd.Read(buf)
		if n == 0 || err != nil {
			break
		}
		b = append(b, buf[:n]...)
		if strings.ContainsRune(string(buf), '\n') {
			break
		}
	}
	return string(b)
}

func (f *FastIO) Flush() {
	if f.writable {
		os.Stdout.Write(f.buffer)
		f.buffer = nil
	}
}

