public class Main {
    private static final int MOD = 998244353;
    private static final long N = (long) 1e9 + 7;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));

        int t = Integer.parseInt(br.readLine());
        while (t-- > 0) {
            int n = Integer.parseInt(br.readLine());
            long[] dp1 = new long[n + 2];
            long[] dp2 = new long[n + 2];
            dp1[0] = 1;

            String[] input = br.readLine().split(" ");
            for (String s : input) {
                int i = Integer.parseInt(s);
                dp1[i + 1] = (dp1[i + 1] << 1) % MOD;
                dp1[i + 1] = (dp1[i + 1] + dp1[i]) % MOD;
                if (i > 0) {
                    dp2[i - 1] = (dp2[i - 1] << 1) % MOD;
                    dp2[i - 1] = (dp2[i - 1] + dp1[i - 1]) % MOD;
                }
                dp2[i + 1] = (dp2[i + 1] << 1) % MOD;
            }

            long ans = 0;
            for (int i = 0; i < n + 2; i++) {
                ans = (ans + dp1[i] + dp2[i]) % MOD;
            }
            bw.write((ans - 1) % MOD + "\n");
        }

        br.close();
        bw.flush();
        bw.close();
    }
}

