public class Main {
    public static void nextLargerElement(int[] arr, int n, boolean f) {
        Stack<Integer> s = new Stack<>();
        int[] ans = new int[n];
        Arrays.fill(ans, -1);
        for (int i = 0; i < n; i++) {
            while (!s.isEmpty() && arr[s.peek()] < arr[i]) {
                s.pop();
            }
            if (!s.isEmpty()) {
                ans[i] = s.peek();
            }
            s.push(i);
        }
        if (f) {
            for (int i = 0; i < n; i++) {
                if (ans[i] != -1) {
                    ans[i] = n - 1 - ans[i];
                }
            }
        }
    }

    public static int dfs(int i, List<List<Integer>> adj, int p, int ans) {
        boolean f = true;
        int a1 = 0;
        for (int j : adj.get(i)) {
            if (j != p) {
                a1 += dfs(j, adj, i, ans + 1);
                f = false;
            }
        }
        if (f) {
            a1 += ans * (ans - 1) / 2;
        }
        return a1;
    }

    public static void main(String[] args) throws IOException {
        FastIO io = new FastIO(System.in, System.out);
        int t = Integer.parseInt(io.readLine());
        while (t-- > 0) {
            String[] input = io.readLine().split(" ");
            int n = Integer.parseInt(input[0]);
            int s = Integer.parseInt(input[1]);
            io.println(s / ((n + 2) / 2));
        }
    }

    static class FastIO extends PrintWriter {
        BufferedReader br;

        public FastIO(InputStream i, OutputStream o) {
            super(o);
            br = new BufferedReader(new InputStreamReader(i), 8192);
        }

        public String readLine() throws IOException {
            return br.readLine();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        public String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = br.read()) != -1 && Character.isWhitespace(c));
            if (c == -1) throw new IOException("EOF");
            while (!Character.isWhitespace(c)) {
                sb.append((char) c);
                c = br.read();
            }
            return sb.toString();
        }

        public void close() throws IOException {
            super.close();
            br.close();
        }
    }
}

