import java.util.Scanner;
import java.util.ArrayList;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = Integer.parseInt(scanner.nextLine());
        for (int i = 0; i < t; i++) {
            solve(scanner);
        }
        scanner.close();
    }

    private static void solve(Scanner scanner) {
        int n = Integer.parseInt(scanner.nextLine());
        String[] inputArray = scanner.nextLine().split(" ");
        int[] alst = new int[n];
        for (int i = 0; i < n; i++) {
            alst[i] = Integer.parseInt(inputArray[i]) - 1;
        }
        int[] pos = new int[n];
        for (int i = 0; i < n; i++) {
            pos[i] = -1;
        }
        for (int i = 0; i < n; i++) {
            int a = alst[i];
            if ((a - i) % 2 == 1) {
                System.out.println(-1);
                return;
            }
            pos[a] = i;
        }
        ArrayList<Integer> ans = new ArrayList<>();
        for (int i = n - 1; i > 0; i -= 2) {
            int p = pos[i];
            ans.add(p + 1);
            for (int j = 0; j < p / 2; j++) {
                swap(alst, j, p - j);
                swap(pos, alst[j], alst[p - j]);
            }
            p = pos[i - 1];
            ans.add(p);
            p -= 1;
            for (int j = 0; j < p / 2; j++) {
                swap(alst, j, p - j);
                swap(pos, alst[j], alst[p - j]);
            }
            ans.add(p + 3);
            p += 2;
            for (int j = 0; j < p / 2; j++) {
                swap(alst, j, p - j);
                swap(pos, alst[j], alst[p - j]);
            }
            p = 2;
            ans.add(3);
            for (int j = 0; j < p / 2; j++) {
                swap(alst, j, p - j);
                swap(pos, alst[j], alst[p - j]);
            }
            p = i;
            ans.add(p + 1);
            for (int j = 0; j < p / 2; j++) {
                swap(alst, j, p - j);
                swap(pos, alst[j], alst[p - j]);
            }
        }
        System.out.println(ans.size());
        for (int num : ans) {
            System.out.print(num + " ");
        }
        System.out.println();
    }

    private static void swap(int[] array, int i, int j) {
        int temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }
}

