import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] input = br.readLine().split(" ");
        int n = Integer.parseInt(input[0]);
        int k = Integer.parseInt(input[1]);

        int[] A = new int[n];
        input = br.readLine().split(" ");
        for (int i = 0; i < n; i++) {
            A[i] = Integer.parseInt(input[i]);
        }

        int[] B = new int[n];
        input = br.readLine().split(" ");
        for (int i = 0; i < n; i++) {
            B[i] = Integer.parseInt(input[i]);
        }

        List<int[]> Q = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            input = br.readLine().split(" ");
            int l = Integer.parseInt(input[0]);
            int r = Integer.parseInt(input[1]);
            Q.add(new int[]{l, r});
        }

        List<Integer> answer = process(A, B, Q);
        for (int x : answer) {
            System.out.println(x);
        }
    }

    public static List<Integer> process(int[] A, int[] B, List<int[]> Q) {
        List<Integer> S = new ArrayList<>();
        S.add(0);
        int n = A.length;
        for (int i = 0; i < n; i++) {
            int ai = A[i];
            int bi = B[i];
            int di = bi - ai;
            S.add(S.get(S.size() - 1) + di);
        }
        n = S.size();
        double p = Math.log(n) / Math.log(2);
        p = Math.ceil(p);
        p = Math.pow(2, p);

        Double[] min_tree = new Double[(int) (2 * p - 1)];
        Double[] max_tree = new Double[(int) (2 * p - 1)];
        for (int i = 0; i < p; i++) {
            if (i < n) {
                min_tree[i] = S.get(i);
                max_tree[i] = S.get(i);
            } else {
                min_tree[i] = Double.POSITIVE_INFINITY;
                max_tree[i] = Double.NEGATIVE_INFINITY;
            }
        }
        for (int i = (int) p; i < 2 * p - 1; i++) {
            int i1 = (int) ((2 * p - 2) - i);
            int j1 = 2 * i1 + 1;
            int j2 = 2 * i1 + 2;
            int i_left = (int) ((2 * p - 2) - j1);
            int i_right = (int) ((2 * p - 2) - j2);
            min_tree[i] = Math.min(min_tree[i_left], min_tree[i_right]);
            max_tree[i] = Math.max(max_tree[i_left], max_tree[i_right]);
        }

        List<Integer> answer = new ArrayList<>();
        for (int[] qr : Q) {
            int l = qr[0];
            int r = qr[1];
            int s1 = S.get(l - 1);
            int s2 = S.get(r);
            if (s1 != s2) {
                answer.add(-1);
            } else {
                double my_min = findMin(l, r, 0, (int) p - 1, (int) (2 * p - 2), min_tree);
                double my_max = findMax(l, r, 0, (int) p - 1, (int) (2 * p - 2), max_tree);
                if (my_min - s1 < 0) {
                    answer.add(-1);
                } else {
                    answer.add((int) (my_max - s1));
                }
            }
        }
        return answer;
    }

    private static double findMin(int l, int r, int start_l, int start_r, int start_i, Double[] min_tree) {
        if (start_i < 0) {
            return Double.POSITIVE_INFINITY;
        }
        if (l == r) {
            return min_tree[l];
        }
        if (l == start_l && r == start_r) {
            return min_tree[start_i];
        }
        int i1 = (int) ((2 * min_tree.length - 2) - start_i);
        int i_l = (int) ((2 * min_tree.length - 2) - (2 * i1 + 2));
        int i_r = (int) ((2 * min_tree.length - 2) - (2 * i1 + 1));
        int m1 = (start_l + start_r) / 2;
        if (l > m1) {
            return findMin(l, r, m1 + 1, start_r, i_r, min_tree);
        } else if (r <= m1) {
            return findMin(l, r, start_l, m1, i_l, min_tree);
        } else {
            double min1 = findMin(l, m1, start_l, m1, i_l, min_tree);
            double min2 = findMin(m1 + 1, r, m1 + 1, start_r, i_r, min_tree);
            return Math.min(min1, min2);
        }
    }

    private static double findMax(int l, int r, int start_l, int start_r, int start_i, Double[] max_tree) {
        if (start_i < 0) {
            return Double.NEGATIVE_INFINITY;
        }
        if (l == r) {
            return max_tree[l];
        }
        if (l == start_l && r == start_r) {
            return max_tree[start_i];
        }
        int i1 = (int) ((2 * max_tree.length - 2) - start_i);
        int i_l = (int) ((2 * max_tree.length - 2) - (2 * i1 + 2));
        int i_r = (int) ((2 * max_tree.length - 2) - (2 * i1 + 1));
        int m1 = (start_l + start_r) / 2;
        if (l > m1) {
            return findMax(l, r, m1 + 1, start_r, i_r, max_tree);
        } else if (r <= m1) {
            return findMax(l, r, start_l, m1, i_l, max_tree);
        } else {
            double max1 = findMax(l, m1, start_l, m1, i_l, max_tree);
            double max2 = findMax(m1 + 1, r, m1 + 1, start_r, i_r, max_tree);
            return Math.max(max1, max2);
        }
    }
}

