import java.util.Scanner;

public class Main {
    private static final int MOD = 998244353;

    public static void main(String[] args) {
        solve();
    }

    private static void solve() {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        boolean wb_poss = n > 1;
        boolean bw_poss = n > 1;
        int w = 0;
        int b = 0;
        int q = 0;
        int free = 0;
        boolean any_bad_poss = n > 1;

        for (int i = 0; i < n; i++) {
            String s = scanner.next().trim();
            if (s.charAt(0) == 'B') {
                b++;
                wb_poss = false;
            } else if (s.charAt(0) == 'W') {
                w++;
                bw_poss = false;
            } else if (s.charAt(0) == '?') {
                q++;
            }
            if (s.charAt(1) == 'B') {
                b++;
                bw_poss = false;
            } else if (s.charAt(1) == 'W') {
                w++;
                bw_poss = false;
            } else if (s.charAt(1) == '?') {
                q++;
            }
            if (s.equals("??")) {
                free++;
            } else if (s.charAt(0) == s.charAt(1)) {
                any_bad_poss = false;
            }
        }

        int w_needed = n - w;
        if (w_needed > q || w_needed < 0) {
            System.out.println(0);
            return;
        }

        long num_bad_poss;
        if (any_bad_poss) {
            num_bad_poss = pow(2, free, MOD);
            num_bad_poss -= (bw_poss ? 1 : 0) + (wb_poss ? 1 : 0);
        } else {
            num_bad_poss = 0;
        }

        System.out.println((choose(q, w_needed, MOD) - num_bad_poss + MOD) % MOD);
    }

    private static long egcd(long a, long b, long[] x, long[] y) {
        if (a == 0) {
            x[0] = 0;
            y[0] = 1;
            return b;
        }
        long[] x1 = new long[1];
        long[] y1 = new long[1];
        long gcd = egcd(b % a, a, x1, y1);
        x[0] = y1[0] - (b / a) * x1[0];
        y[0] = x1[0];
        return gcd;
    }

    private static long modinv(long a, long m) {
        long[] x = new long[1];
        long[] y = new long[1];
        long g = egcd(a, m, x, y);
        if (g != 1) {
            throw new IllegalArgumentException("modular inverse does not exist");
        } else {
            return (x[0] % m + m) % m;
        }
    }

    private static long choose(int n, int k, int p) {
        if (k == 0) {
            return 1;
        }
        long x = n;
        for (int y = n - 1; y > n - k; y--) {
            x = x * y % p;
        }
        long d = 1;
        for (int i = 2; i <= k; i++) {
            d = d * i % p;
        }
        return x * modinv(d, p) % p;
    }

    private static long pow(long base, int exp, int mod) {
        long result = 1;
        base = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            exp >>= 1;
            base = (base * base) % mod;
        }
        return result;
    }
}

