    static List<int> NextLargerElement(int[] arr, int n, bool f)
    {
        Stack<int> s = new Stack<int>();
        List<int> ans = new List<int>(new int[n]);
        for (int i = 0; i < n; i++)
        {
            while (s.Count > 0 && arr[s.Peek()] < arr[i])
            {
                s.Pop();
            }
            if (s.Count > 0)
            {
                ans[i] = s.Peek();
            }
            s.Push(i);
        }
        if (f)
        {
            for (int i = 0; i < n; i++)
            {
                if (ans[i] != -1)
                {
                    ans[i] = n - 1 - ans[i];
                }
            }
        }
        return ans;
    }

    static int Dfs(int i, List<int>[] adj, int p, int ans)
    {
        bool f = true;
        int a1 = 0;
        foreach (int j in adj[i])
        {
            if (j != p)
            {
                a1 += Dfs(j, adj, i, ans + 1);
                f = false;
            }
        }
        if (f)
        {
            a1 += ans * (ans - 1) / 2;
        }
        return a1;
    }

    // FastIO region

    const int BUFSIZE = 8192;

    class FastIO : TextReader
    {
        private readonly Stream _stream;
        private readonly MemoryStream _buffer;
        private bool _writable;

        public FastIO(Stream file)
        {
            _stream = file;
            _buffer = new MemoryStream();
            _writable = "x".Contains(file.CanWrite.ToString()) || !file.CanRead;
        }

        public override string ReadToEnd()
        {
            while (true)
            {
                byte[] b = new byte[Math.Max(_stream.Length, BUFSIZE)];
                int bytesRead = _stream.Read(b, 0, b.Length);
                if (bytesRead == 0)
                    break;
                long ptr = _buffer.Position;
                _buffer.Seek(0, SeekOrigin.End);
                _buffer.Write(b, 0, bytesRead);
                _buffer.Seek(ptr, SeekOrigin.Begin);
            }
            return System.Text.Encoding.ASCII.GetString(_buffer.ToArray());
        }

        public override string ReadLine()
        {
            while (true)
            {
                byte[] b = new byte[Math.Max(_stream.Length, BUFSIZE)];
                int bytesRead = _stream.Read(b, 0, b.Length);
                if (bytesRead == 0)
                    break;
                long ptr = _buffer.Position;
                _buffer.Seek(0, SeekOrigin.End);
                _buffer.Write(b, 0, bytesRead);
                _buffer.Seek(ptr, SeekOrigin.Begin);
            }
            return System.Text.Encoding.ASCII.GetString(_buffer.ToArray()).Split('\n')[0];
        }

        public override void Flush()
        {
            if (_writable)
            {
                _stream.Write(_buffer.ToArray(), 0, (int)_buffer.Length);
                _buffer.SetLength(0);
                _buffer.Seek(0, SeekOrigin.Begin);
            }
        }
    }

    class IOWrapper : TextReader
    {
        private readonly FastIO _buffer;

        public IOWrapper(Stream file)
        {
            _buffer = new FastIO(file);
        }

        public override string ReadToEnd()
        {
            return _buffer.ReadToEnd();
        }

        public override string ReadLine()
        {
            return _buffer.ReadLine();
        }

        public override void Flush()
        {
            _buffer.Flush();
        }
    }

    static void Print(params object[] args)
    {
        string sep = " ";
        TextWriter file = Console.Out;
        bool atStart = true;
        foreach (var x in args)
        {
            if (!atStart)
                file.Write(sep);
            file.Write(x.ToString());
            atStart = false;
        }
        file.WriteLine();
        file.Flush();
    }

    static void MainFastIO(string[] args)
    {
        Console.SetIn(new IOWrapper(Console.OpenStandardInput()));
        Console.SetOut(new IOWrapper(Console.OpenStandardOutput()));

        int t = int.Parse(Console.ReadLine());
        for (int i = 0; i < t; i++)
        {
            var input = Console.ReadLine().Split();
            int n = int.Parse(input[0]);
            int s = int.Parse(input[1]);
            Print(s / ((n + 2) / 2));
        }
    }

    // endregion
}

