using System;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        int t = int.Parse(Console.ReadLine());
        for (int i = 0; i < t; i++)
        {
            Solve();
        }
    }

    static void Solve()
    {
        string[] input = Console.ReadLine().Split(' ');
        int n = int.Parse(input[0]);
        int k = int.Parse(input[1]);
        int x = int.Parse(input[2]);
        string s = Console.ReadLine();

        if (!s.Contains("*"))
        {
            Console.WriteLine(s);
            return;
        }

        List<string> stars = new List<string>();
        foreach (var part in s.Split('a'))
        {
            if (!string.IsNullOrEmpty(part))
            {
                stars.Add(part);
            }
        }

        List<int> expand = new List<int>();
        foreach (var star in stars)
        {
            expand.Add(1 + k * star.Length);
        }

        List<int> prods = new List<int>();
        prods.Add(expand[expand.Count - 1]);
        for (int i = 1; i < stars.Count; i++)
        {
            prods.Add(prods[prods.Count - 1] * expand[stars.Count - i - 1]);
        }

        x -= 1;

        List<int> counts = new List<int>();
        foreach (var prod in prods.AsEnumerable().Reverse())
        {
            counts.Add(x / prod);
            x -= prod * (x / prod);
        }
        counts.Add(x % prods[0]);

        string answer = "";
        int i = 1;
        int j = 0;
        while (j < s.Length)
        {
            if (s[j] == 'a')
            {
                answer += "a";
                j += 1;
            }
            else
            {
                answer += new string('b', counts[i]);
                i += 1;
                while (j < s.Length && s[j] == '*')
                {
                    j += 1;
                }
            }
        }

        Console.WriteLine(answer);
    }
}

