            A.Add(int.Parse(input[i]));
        }

        input = Console.ReadLine().Split();
        List<int> B = new List<int>();
        for (int i = 0; i < n; i++)
        {
            B.Add(int.Parse(input[i]));
        }

        List<List<int>> Q = new List<List<int>>();
        for (int i = 0; i < k; i++)
        {
            input = Console.ReadLine().Split();
            Q.Add(new List<int> { int.Parse(input[0]), int.Parse(input[1]) });
        }

        List<int> answer = Process(A, B, Q);
        foreach (int x in answer)
        {
            Console.WriteLine(x);
        }
    }

    static List<int> Process(List<int> A, List<int> B, List<List<int>> Q)
    {
        List<int> S = new List<int> { 0 };
        int n = A.Count;
        for (int i = 0; i < n; i++)
        {
            int ai = A[i];
            int bi = B[i];
            int di = bi - ai;
            S.Add(S[S.Count - 1] + di);
        }

        n = S.Count;
        double p = Math.Log(n) / Math.Log(2);
        p = Math.Ceiling(p);
        p = Math.Pow(2, p);

        List<double?> minTree = new List<double?>(new double?[2 * (int)p - 1]);
        List<double?> maxTree = new List<double?>(new double?[2 * (int)p - 1]);

        for (int i = 0; i < p; i++)
        {
            if (i < n)
            {
                minTree[i] = S[i];
                maxTree[i] = S[i];
            }
            else
            {
                minTree[i] = double.PositiveInfinity;
                maxTree[i] = double.NegativeInfinity;
            }
        }

        for (int i = (int)p; i < 2 * (int)p - 1; i++)
        {
            int i1 = (2 * (int)p - 2) - i;
            int j1 = 2 * i1 + 1;
            int j2 = 2 * i1 + 2;
            int iLeft = (2 * (int)p - 2) - j1;
            int iRight = (2 * (int)p - 2) - j2;

            minTree[i] = Math.Min(minTree[iLeft], minTree[iRight]);
            maxTree[i] = Math.Max(maxTree[iLeft], maxTree[iRight]);
        }

        double? FindMax(int l, int r, int startL = 0, int startR = -1, int startIndex = -1)
        {
            if (startIndex < 0) return null;
            if (l == r) return maxTree[l];
            if (startL == l && startR == r) return maxTree[startIndex];

            int i1 = (2 * (int)p - 2) - startIndex;
            int iLeft = (2 * (int)p - 2) - (2 * i1 + 2);
            int iRight = (2 * (int)p - 2) - (2 * i1 + 1);
            int m1 = (startL + startR) / 2;

            if (l > m1)
                return FindMax(l, r, startL: m1 + 1, startR: startR, startIndex: iRight);
            else if (r <= m1)
                return FindMax(l, r, startL: startL, startR: m1, startIndex: iLeft);
            else
            {
                double? max1 = FindMax(l, m1, startL: startL, startR: m1, startIndex: iLeft);
                double? max2 = FindMax(m1 + 1, r, startL: m1 + 1, startR: startR, startIndex: iRight);
                return Math.Max(max1 ?? double.NegativeInfinity, max2 ?? double.NegativeInfinity);
            }
        }

        double? FindMin(int l, int r, int startL = 0, int startR = -1, int startIndex = -1)
        {
            if (startIndex < 0) return null;
            if (l == r) return minTree[l];
            if (startL == l && startR == r) return minTree[startIndex];

            int i1 = (2 * (int)p - 2) - startIndex;
            int iLeft = (2 * (int)p - 2) - (2 * i1 + 2);
            int iRight = (2 * (int)p - 2) - (2 * i1 + 1);
            int m1 = (startL + startR) / 2;

            if (l > m1)
                return FindMin(l, r, startL: m1 + 1, startR: startR, startIndex: iRight);
            else if (r <= m1)
                return FindMin(l, r, startL: startL, startR: m1, startIndex: iLeft);
            else
            {
                double? min1 = FindMin(l, m1, startL: startL, startR: m1, startIndex: iLeft);
                double? min2 = FindMin(m1 + 1, r, startL: m1 + 1, startR: startR, startIndex: iRight);
                return Math.Min(min1 ?? double.PositiveInfinity, min2 ?? double.PositiveInfinity);
            }
        }

        List<int> answer = new List<int>();
        foreach (var qr in Q)
        {
            int l = qr[0] - 1;
            int r = qr[1];
            int s1 = S[l];
            int s2 = S[r];

            if (s1 != s2)
                answer.Add(-1);
            else
            {
                double? myMin = FindMin(l, r);
                double? myMax = FindMax(l, r);

                if (myMin - s1 < 0)
                    answer.Add(-1);
                else
                    answer.Add((int)(myMax - s1));
            }
        }

        return answer;
    }
}

