            for (int i = 0; i < n; i++)
            {
                for (int j = 0; j < m; j++)
                {
                    int a = i, b = j, p = d[i, j], c = 0;
                    List<Tuple<int, int>> st = new List<Tuple<int, int>>();
                    while (p < 0)
                    {
                        d[a, b] = 0;
                        st.Add(new Tuple<int, int>(a, b));
