                        else
                        {
                            for (int ii = 0; ii < st.Count; ii++)
                            {
                                Tuple<int, int> tuple = st[ii];
                                d[tuple.Item1, tuple.Item2] = c - ii;
                            }
                            p = -1;
                            break;
                        }
                    }

