                    {
                        int jj = 0, flag = 0;
                        for (int ii = 0; ii < st.Count; ii++)
                        {
                            Tuple<int, int> tuple = st[ii];
                            d[tuple.Item1, tuple.Item2] = flag == 1 ? c - jj : c - ii;
                            if (tuple.Item1 == a && tuple.Item2 == b)
                            {
