class FastIO
{
    private const int BUFSIZE = 8192;
    private readonly Stream _inputStream;
    private readonly Stream _outputStream;
    private readonly byte[] _buffer;
    private int _bufferSize;
    private int _bufferIndex;

    public FastIO(Stream inputStream, Stream outputStream)
    {
        _inputStream = inputStream;
        _outputStream = outputStream;
        _buffer = new byte[BUFSIZE];
        _bufferSize = 0;
        _bufferIndex = 0;
    }

    public string ReadLine()
    {
        using (var ms = new MemoryStream())
        {
            while (true)
            {
                if (_bufferIndex >= _bufferSize)
                {
                    _bufferSize = _inputStream.Read(_buffer, 0, BUFSIZE);
                    _bufferIndex = 0;
                }
                if (_bufferSize == 0) break;

                int newlineIndex = Array.IndexOf(_buffer, (byte)'\n', _bufferIndex);
                if (newlineIndex >= 0)
                {
                    ms.Write(_buffer, _bufferIndex, newlineIndex - _bufferIndex + 1);
                    _bufferIndex = newlineIndex + 1;
                    break;
                }
                else
                {
                    ms.Write(_buffer, _bufferIndex, _bufferSize - _bufferIndex);
                    _bufferIndex = _bufferSize;
                }
            }
            return System.Text.Encoding.ASCII.GetString(ms.ToArray()).TrimEnd('\r', '\n');
        }
    }

    public void WriteLine(object value)
    {
        byte[] bytes = System.Text.Encoding.ASCII.GetBytes(value.ToString() + "\n");
        _outputStream.Write(bytes, 0, bytes.Length);
    }
}

using System;
using System.Numerics;

class Program
{
    const int Mod = 998244353;

    static (int, int, int) Egcd(int a, int b)
    {
        if (a == 0)
            return (b, 0, 1);
        else
        {
            var (g, y, x) = Egcd(b % a, a);
            return (g, x - (b / a) * y, y);
        }
    }

    static int Modinv(int a, int m)
    {
        var (g, x, _) = Egcd(a, m);
        if (g != 1)
            throw new Exception("modular inverse does not exist");
        else
            return (x % m + m) % m;
    }

    static int Choose(int n, int k, int p)
    {
        if (k == 0)
            return 1;
        BigInteger x = n;
        for (int y = n - 1; y > n - k; y--)
            x = (x * y) % p;
        BigInteger d = 1;
        for (int i = 2; i <= k; i++)
            d = (d * i) % p;
        return (int)((x * Modinv((int)d, p)) % p);
    }

    static void Solve()
    {
        int n = int.Parse(Console.ReadLine());
        bool wb_poss = n > 1;
        bool bw_poss = n > 1;
        int w = 0;
        int b = 0;
        int q = 0;
        int free = 0;
        bool any_bad_poss = n > 1;

        for (int i = 0; i < n; i++)
        {
            string s = Console.ReadLine().Trim();
            if (s[0] == 'B')
            {
                b++;
                wb_poss = false;
            }
            else if (s[0] == 'W')
            {
                w++;
                bw_poss = false;
            }
            else if (s[0] == '?')
            {
                q++;
            }

            if (s[1] == 'B')
            {
                b++;
                bw_poss = false;
            }
            else if (s[1] == 'W')
            {
                w++;
                wb_poss = false;
            }
            else if (s[1] == '?')
            {
                q++;
            }

            if (s == "??")
            {
                free++;
            }
            else if (s[0] == s[1])
            {
                any_bad_poss = false;
            }
        }

        int w_needed = n - w;
        if (w_needed > q || w_needed < 0)
        {
            Console.WriteLine(0);
            return;
        }

        int num_bad_poss;
        if (any_bad_poss)
        {
            num_bad_poss = (int)(BigInteger.ModPow(2, free, Mod) - (bw_poss ? 1 : 0) - (wb_poss ? 1 : 0));
        }
        else
        {
            num_bad_poss = 0;
        }

        Console.WriteLine((Choose(q, w_needed, Mod) - num_bad_poss + Mod) % Mod);
    }

    static void Main(string[] args)
    {
        Solve();
    }
}

using System;
using System.IO;
using System.Text;

class FastIO : TextReader, TextWriter
{
    private readonly Stream _stream;
    private readonly MemoryStream _buffer;
    private readonly bool _writable;

    public FastIO(Stream stream)
    {
        _stream = stream;
        _buffer = new MemoryStream();
        _writable = stream.CanWrite;
    }

    public override string ReadLine()
    {
        StringBuilder sb = new StringBuilder();
        while (true)
        {
            byte[] b = new byte[Math.Max(_stream.Length, 8192)];
            int bytesRead = _stream.Read(b, 0, b.Length);
            if (bytesRead == 0) break;
            string line = Encoding.ASCII.GetString(b, 0, bytesRead);
            sb.Append(line);
            if (line.Contains("\n")) break;
        }
        return sb.ToString().TrimEnd('\r', '\n');
    }

    public override int Read()
    {
        byte[] b = new byte[1];
        _stream.Read(b, 0, 1);
        return b[0];
    }

    public override void Write(string value)
    {
        if (_writable) _buffer.Write(Encoding.ASCII.GetBytes(value));
    }

    public override void WriteLine(string value)
    {
        Write(value + "\n");
    }

    public override void Flush()
    {
        if (_writable) _stream.Write(_buffer.ToArray(), 0, (int)_buffer.Length);
        _buffer.SetLength(0);
    }
}

