class Program
{
    static void Main()
    {
        int n = int.Parse(Console.ReadLine());
        List<int[]> p = new List<int[]>();
        for (int i = 0; i < n; i++)
        {
            string[] input = Console.ReadLine().Split();
            p.Add(new int[] { int.Parse(input[0]), int.Parse(input[1]) });
        }

        int ans = 0;
        int cnt = 0;
        int[,] r = new int[n, n];
        int[] q = new int[n];

        for (int i = 0; i < n; i++)
        {
            for (int j = i + 1; j < n; j++)
            {
                if (Gcd(Math.Abs(p[i][0] - p[j][0]), Math.Abs(p[i][1] - p[j][1])) % 4 == 0)
                {
                    cnt++;
                    r[i, j] = 1;
                    q[i]++;
                    ans += n - 2;
                }
            }
        }

        for (int i = 0; i < n; i++)
        {
            for (int j = 1; j < n; j++)
            {
                if (r[i, j] == 1)
                {
                    ans -= q[j] * 2;
                }
            }
        }

        Console.WriteLine(ans);
    }

    static int Gcd(int a, int b)
    {
        while (b != 0)
        {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}

