    for i in 0..n {
        while !s.is_empty() && arr[s[s.len() - 1]] < arr[i] {
            s.pop();
        }
        if !s.is_empty() {
            ans[i] = s[s.len() - 1] as i32;
        }
        s.push(i);
    }
    if f {
        for i in 0..n {
            if ans[i] != -1 {
                ans[i] = (n - 1) as i32 - ans[i];
            }
        }
    }
    ans
}

fn dfs(i: usize, adj: &[Vec<usize>], p: Option<usize>, mut ans: usize) -> usize {
    let mut f = true;
    let mut a1 = 0;
    for &j in &adj[i] {
        if Some(j) != p {
            a1 += dfs(j, adj, Some(i), ans + 1);
            f = false;
        }
    }
    if f {
        a1 += ans * (ans - 1) / 2;
    }
    a1
}

