use std::io::{self, Read, Write};
use std::str;

const BUFSIZE: usize = 8192;

struct FastIO {
    buffer: Vec<u8>,
    pos: usize,
    end: usize,
}

impl FastIO {
    fn new() -> Self {
        FastIO {
            buffer: vec![0; BUFSIZE],
            pos: 0,
            end: 0,
        }
    }

    fn read(&mut self) -> io::Result<()> {
        let mut bytes_read = 0;
        while bytes_read < BUFSIZE {
            match io::stdin().read(&mut self.buffer[bytes_read..BUFSIZE])? {
                0 => break,
                n => bytes_read += n,
            }
        }
        self.pos = 0;
        self.end = bytes_read;
        Ok(())
    }

    fn read_line(&mut self) -> io::Result<String> {
        let mut result = String::new();
        loop {
            if self.pos == self.end {
                self.read()?;
            }
            while self.pos < self.end && self.buffer[self.pos] != b'\n' {
                result.push(self.buffer[self.pos] as char);
                self.pos += 1;
            }
            if self.pos < self.end || io::stdin().read(&mut self.buffer)? > 0 {
                result.push('\n');
                self.pos += 1;
            } else {
                break;
            }
        }
        Ok(result)
    }

    fn read_int(&mut self) -> io::Result<i32> {
        let mut num = 0;
        let mut sign = 1;
        while self.pos < self.end || io::stdin().read(&mut self.buffer)? > 0 {
            if self.buffer[self.pos] == b'-' {
                sign = -1;
                self.pos += 1;
            }
            while self.pos < self.end && self.buffer[self.pos].is_ascii_digit() {
                num = num * 10 + (self.buffer[self.pos] - b'0') as i32;
                self.pos += 1;
            }
            if self.pos == self.end || !self.buffer[self.pos].is_ascii_digit() {
                break;
            }
        }
        Ok(num * sign)
    }

    fn read_ints(&mut self) -> io::Result<Vec<i32>> {
        let mut result = Vec::new();
        while self.pos < self.end || io::stdin().read(&mut self.buffer)? > 0 {
            if self.buffer[self.pos].is_ascii_digit() || self.buffer[self.pos] == b'-' {
                result.push(self.read_int()?);
            }
            self.pos += 1;
        }
        Ok(result)
    }
}

fn main() -> io::Result<()> {
    let mut fast_io = FastIO::new();
    let t = fast_io.read_int()?;
    for _ in 0..t {
        let n = fast_io.read_int()?;
        let l = fast_io.read_ints()?;
        if n % 2 == 0 {
            writeln!(io::stdout(), "YES")?;
        } else {
            let mut flag = false;
            for i in 0..n - 1 {
                if l[i] >= l[i + 1] {
                    flag = true;
                    break;
                }
            }
            if flag {
                writeln!(io::stdout(), "YES")?;
            } else {
                writeln!(io::stdout(), "NO")?;
            }
        }
    }
    Ok(())
}

