use std::io::{self, Read};

fn process(a: Vec<i32>, b: Vec<i32>, q: Vec<(usize, usize)>) -> Vec<i32> {
    let mut s = vec![0];
    for i in 0..a.len() {
        let ai = a[i];
        let bi = b[i];
        let di = bi - ai;
        s.push(s[s.len() - 1] + di);
    }
    let n = s.len();
    let p = (n as f64).log2().ceil() as usize;
    let p = 2usize.pow(p as u32);
    let mut min_tree = vec![None; 2 * p - 1];
    let mut max_tree = vec![None; 2 * p - 1];

    for i in 0..p {
        if i < n {
            min_tree[i] = Some(s[i]);
            max_tree[i] = Some(s[i]);
        } else {
            min_tree[i] = Some(i32::MAX);
            max_tree[i] = Some(i32::MIN);
        }
    }

    for i in p..(2 * p - 1) {
        let i1 = (2 * p - 2) - i;
        let j1 = 2 * i1 + 1;
        let j2 = 2 * i1 + 2;
        let i_left = (2 * p - 2) - j1;
        let i_right = (2 * p - 2) - j2;
        min_tree[i] = Some(min_tree[i_left].unwrap().min(min_tree[i_right].unwrap()));
        max_tree[i] = Some(max_tree[i_left].unwrap().max(max_tree[i_right].unwrap()));
    }

    fn find_max(
        l: usize,
        r: usize,
        start_l: usize,
        start_r: usize,
        start_i: usize,
        max_tree: &Vec<Option<i32>>,
    ) -> Option<i32> {
        if start_i >= max_tree.len() || start_i < 0 {
            return None;
        }
        if l == r {
            return max_tree[l];
        }
        if l == start_l && r == start_r {
            return max_tree[start_i];
        }
        let i1 = (2 * max_tree.len() - 2) - start_i;
        let i_l = (2 * max_tree.len() - 2) - (2 * i1 + 2);
        let i_r = (2 * max_tree.len() - 2) - (2 * i1 + 1);
        let m1 = (start_l + start_r) / 2;
        if l > m1 {
            return find_max(l, r, m1 + 1, start_r, i_r, max_tree);
        } else if r <= m1 {
            return find_max(l, r, start_l, m1, i_l, max_tree);
        } else {
            let max1 = find_max(l, m1, start_l, m1, i_l, max_tree).unwrap();
            let max2 = find_max(m1 + 1, r, m1 + 1, start_r, i_r, max_tree).unwrap();
            return Some(max1.max(max2));
        }
    }

    fn find_min(
        l: usize,
        r: usize,
        start_l: usize,
        start_r: usize,
        start_i: usize,
        min_tree: &Vec<Option<i32>>,
    ) -> Option<i32> {
        if start_i >= min_tree.len() || start_i < 0 {
            return None;
        }
        if l == r {
            return min_tree[l];
        }
        if l == start_l && r == start_r {
            return min_tree[start_i];
        }
        let i1 = (2 * min_tree.len() - 2) - start_i;
        let i_l = (2 * min_tree.len() - 2) - (2 * i1 + 2);
        let i_r = (2 * min_tree.len() - 2) - (2 * i1 + 1);
        let m1 = (start_l + start_r) / 2;
        if l > m1 {
            return find_min(l, r, m1 + 1, start_r, i_r, min_tree);
        } else if r <= m1 {
            return find_min(l, r, start_l, m1, i_l, min_tree);
        } else {
            let min1 = find_min(l, m1, start_l, m1, i_l, min_tree).unwrap();
            let min2 = find_min(m1 + 1, r, m1 + 1, start_r, i_r, min_tree).unwrap();
            return Some(min1.min(min2));
        }
    }

    let mut answer = Vec::new();
    for (l, r) in q {
        let s1 = s[l - 1];
        let s2 = s[r];
        if s1 != s2 {
            answer.push(-1);
        } else {
            let my_min = find_min(l, r, 0, p - 1, 2 * p - 2, &min_tree).unwrap();
            let my_max = find_max(l, r, 0, p - 1, 2 * p - 2, &max_tree).unwrap();
            if my_min - s1 < 0 {
                answer.push(-1);
            } else {
                answer.push(my_max - s1);
            }
        }
    }
    answer
}

