            .split_whitespace()
            .map(|s| s.parse().unwrap())
            .collect();
        let n = nm[0];
        let m = nm[1];

        let mut d = vec![vec![-1; m]; n];
        for i in 0..n {
            let line = lines.next().unwrap().expect("Failed to read line").trim();
            for (j, c) in line.chars().enumerate() {
                d[i][j] = match c {
                    'R' => -1,
                    'U' => -2,
                    'L' => -3,
                    _ => -4,
                };
            }
        }

        let mut r = 0;
        let mut pos = (0, 0);

        for i in 0..n {
            for j in 0..m {
                let (mut a, mut b) = (i, j);
                let mut p = d[i][j];
                let mut c = 0;
                let mut st = Vec::new();

                while p < 0 {
                    d[a][b] = 0;
                    st.push((a, b));
                    if p == -1 { b += 1; }
                    else if p == -2 { a -= 1; }
                    else if p == -3 { b -= 1; }
                    else { a += 1; }
                    c += 1;
                    if a < n && b < m {
                        p = d[a][b];
                    } else {
                        for (ii, &(x, y)) in st.iter().enumerate() {
                            d[x][y] = c - ii;
                        }
                        p = -1;
                        break;
                    }
