const BUFSIZE: usize = 8192;

struct FastIO {
    buffer: Vec<u8>,
    pos: usize,
    end: usize,
}

impl FastIO {
    fn new() -> Self {
        let mut buffer = vec![0; BUFSIZE];
        let (pos, end) = (0, 0);
        FastIO { buffer, pos, end }
    }

    fn read(&mut self) -> io::Result<()> {
        while self.pos >= self.end {
            self.end = io::stdin().read(&mut self.buffer)?;
            self.pos = 0;
        }
        Ok(())
    }

    fn read_line(&mut self) -> io::Result<String> {
        let mut result = String::new();
        loop {
            if self.pos >= self.end {
                self.read()?;
            }
            while self.pos < self.end && self.buffer[self.pos] != b'\n' {
                result.push(self.buffer[self.pos] as char);
                self.pos += 1;
            }
            if self.pos < self.end && self.buffer[self.pos] == b'\n' {
                result.push('\n');
                self.pos += 1;
                break;
            }
        }
        Ok(result)
    }

    fn read_int(&mut self) -> io::Result<i32> {
        let mut num = 0;
        let mut sign = 1;
        loop {
            if self.pos >= self.end {
                self.read()?;
            }
            if self.buffer[self.pos] == b'-' {
                sign = -1;
                self.pos += 1;
            } else if self.buffer[self.pos].is_ascii_digit() {
                num = num * 10 + (self.buffer[self.pos] - b'0') as i32;
                self.pos += 1;
            } else {
                break;
            }
        }
        Ok(num * sign)
    }

    fn read_ints(&mut self, n: usize) -> io::Result<Vec<i32>> {
        let mut result = Vec::with_capacity(n);
        for _ in 0..n {
            result.push(self.read_int()?);
        }
        Ok(result)
    }
}

