    Ok(())
}

const MOD: i64 = 998244353;

fn egcd(a: i64, b: i64) -> (i64, i64, i64) {
    if a == 0 {
        (b, 0, 1)
    } else {
        let (g, y, x) = egcd(b % a, a);
        (g, x - (b / a) * y, y)
    }
}

fn modinv(a: i64, m: i64) -> i64 {
    let (g, x, _) = egcd(a, m);
    if g != 1 {
        panic!("modular inverse does not exist");
    } else {
        ((x % m) + m) % m
    }
}

fn choose(n: i64, k: i64, p: i64) -> i64 {
    if k == 0 {
        return 1;
    }
    let mut x = n;
    for y in (n - 1)..(n - k - 1).min(-1) {
        x = x * y % p;
    }
    let mut d = 1;
    for i in 2..=k {
        d = d * i % p;
    }
    x * modinv(d, p) % p
}

fn solve() {
    use std::io::{self, BufRead};
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    let n: i64 = lines.next().unwrap().expect("Failed to read input").trim().parse().unwrap();
    let mut wb_poss = n > 1;
    let mut bw_poss = n > 1;
    let mut w = 0;
    let mut b = 0;
    let mut q = 0;
    let mut free = 0;
    let mut any_bad_poss = n > 1;

    for _ in 0..n {
        let s = lines.next().unwrap().expect("Failed to read input").trim();
        if s.chars().nth(0) == Some('B') {
            b += 1;
            wb_poss = false;
        } else if s.chars().nth(0) == Some('W') {
            w += 1;
            bw_poss = false;
        } else if s.chars().nth(0) == Some('?') {
            q += 1;
        }
        if s.chars().nth(1) == Some('B') {
            b += 1;
            bw_poss = false;
        } else if s.chars().nth(1) == Some('W') {
            w += 1;
            bw_poss = false;
        } else if s.chars().nth(1) == Some('?') {
            q += 1;
        }
        if s == "??".to_string() {
            free += 1;
        } else if s.chars().nth(0) == s.chars().nth(1) {
            any_bad_poss = false;
        }
    }

    let w_needed = n - w;
    if w_needed > q || w_needed < 0 {
        println!("0");
        return;
    }

    let num_bad_poss: i64;
    if any_bad_poss {
        num_bad_poss = (2_i64.pow(free as u32) % MOD) - (bw_poss as i64 + wb_poss as i64);
    } else {
        num_bad_poss = 0;
    }

    println!("{}", ((choose(q, w_needed, MOD) - num_bad_poss + MOD) % MOD));
}

