            dp2[i + 1] = (dp2[i + 1] << 1) % mod;
        }
        ll ans = 0;
        for (int i = 0; i <= n + 1; ++i) {
            ans = (ans + dp1[i] + dp2[i]) % mod;
        }
        cout << (ans - 1 + mod) % mod << '\n';
    }

    return 0;
}

