void solve() {
    int n, k, x;
    std::cin >> n >> k >> x;
    std::string s;
    std::cin.ignore(); // To ignore the newline left in the buffer
    std::getline(std::cin, s);

    if (s.find('*') == std::string::npos) {
        std::cout << s << std::endl;
        return;
    }

    std::vector<std::string> stars;
    std::stringstream ss(s);
    std::string temp;
    while (std::getline(ss, temp, 'a')) {
        if (!temp.empty()) {
            stars.push_back(temp);
        }
    }

    std::vector<int> expand;
    for (const auto& star : stars) {
        expand.push_back(1 + k * star.length());
    }

    std::vector<int> prods{expand.back()};
    for (size_t i = 1; i < stars.size(); ++i) {
        prods.push_back(prods.back() * expand[stars.size() - i - 1]);
    }

    x -= 1;

    std::vector<int> counts;
    for (auto it = prods.rbegin(); it != prods.rend(); ++it) {
        counts.push_back(x / *it);
        x -= *it * (x / *it);
    }
    counts.push_back(x % prods[0]);

    std::string answer;
    size_t i = 1;
    size_t j = 0;
    while (j < s.length()) {
        if (s[j] == 'a') {
            answer += "a";
            ++j;
        } else {
            answer.append(counts[i], 'b');
            ++i;
            while (j < s.length() && s[j] == '*') {
                ++j;
            }
        }
    }

    std::cout << answer << std::endl;
}

