using namespace std;

vector<int> process(const vector<int>& A, const vector<int>& B, const vector<vector<int>>& Q) {
    vector<long long> S = {0};
    int n = A.size();
    for (int i = 0; i < n; ++i) {
        long long ai = A[i];
        long long bi = B[i];
        long long di = bi - ai;
        S.push_back(S.back() + di);
    }
    n = S.size();
    double p = log(n) / log(2);
    p = ceil(p);
    int tree_size = 1 << static_cast<int>(p);
    vector<long long> min_tree(2 * tree_size - 1, numeric_limits<long long>::max());
    vector<long long> max_tree(2 * tree_size - 1, numeric_limits<long long>::min());

    for (int i = 0; i < n; ++i) {
        min_tree[i] = S[i];
        max_tree[i] = S[i];
    }
    for (int i = n; i < tree_size; ++i) {
        min_tree[i] = numeric_limits<long long>::max();
        max_tree[i] = numeric_limits<long long>::min();
    }

    for (int i = tree_size - 1; i > 0; --i) {
        int left_child = 2 * i;
        int right_child = 2 * i + 1;
        min_tree[i - 1] = min(min_tree[left_child - 1], min_tree[right_child - 1]);
        max_tree[i - 1] = max(max_tree[left_child - 1], max_tree[right_child - 1]);
    }

    function<long long(int, int, int, int, int)> find_max = [&](int l, int r, int start_l, int start_r, int start_i) {
        if (start_i < 0) return numeric_limits<long long>::min();
        if (l == r) return max_tree[l];
        if (l == start_l && r == start_r) return max_tree[start_i - 1];
        int mid = (start_l + start_r) / 2;
        if (r <= mid) return find_max(l, r, start_l, mid, start_i * 2);
        else if (l > mid) return find_max(l, r, mid + 1, start_r, start_i * 2 + 1);
        else {
            long long max1 = find_max(l, mid, start_l, mid, start_i * 2);
            long long max2 = find_max(mid + 1, r, mid + 1, start_r, start_i * 2 + 1);
            return max(max1, max2);
        }
    };

    function<long long(int, int, int, int, int)> find_min = [&](int l, int r, int start_l, int start_r, int start_i) {
        if (start_i < 0) return numeric_limits<long long>::max();
        if (l == r) return min_tree[l];
        if (l == start_l && r == start_r) return min_tree[start_i - 1];
        int mid = (start_l + start_r) / 2;
        if (r <= mid) return find_min(l, r, start_l, mid, start_i * 2);
        else if (l > mid) return find_min(l, r, mid + 1, start_r, start_i * 2 + 1);
        else {
            long long min1 = find_min(l, mid, start_l, mid, start_i * 2);
            long long min2 = find_min(mid + 1, r, mid + 1, start_r, start_i * 2 + 1);
            return min(min1, min2);
        }
    };

    vector<int> answer;
    for (const auto& query : Q) {
        int l = query[0] - 1;
        int r = query[1];
        long long s1 = S[l];
        long long s2 = S[r];
        if (s1 != s2) {
            answer.push_back(-1);
        } else {
            long long my_min = find_min(l, r, 0, tree_size - 1, 1);
            long long my_max = find_max(l, r, 0, tree_size - 1, 1);
            if (my_min - s1 < 0) {
                answer.push_back(-1);
            } else {
                answer.push_back(static_cast<int>(my_max - s1));
            }
        }
    }
    return answer;
}

