const int BUFSIZE = 8192;

class FastIO {
public:
    FastIO() : buffer(BUFSIZE), pos(0), len(0) {}

    std::string read() {
        std::string result;
        while (true) {
            if (pos >= len) {
                len = fread(buffer, 1, BUFSIZE, stdin);
                pos = 0;
                if (len == 0) break;
            }
            size_t end = buffer + len - buffer;
            result.append(buffer + pos, end);
            pos = end;
        }
        return result;
    }

    std::string readline() {
        std::string result;
        while (true) {
            if (pos >= len) {
                len = fread(buffer, 1, BUFSIZE, stdin);
                pos = 0;
                if (len == 0) break;
            }
            size_t end = buffer + len - buffer;
            for (; pos < end; ++pos) {
                if (buffer[pos] == '\n') {
                    result.append(buffer + pos - (pos > 0 && buffer[pos - 1] == '\r'), pos);
                    ++pos;
                    return result;
                }
            }
            result.append(buffer, end);
        }
        return result;
    }

private:
    char buffer[BUFSIZE];
    size_t pos, len;
};

