using namespace std;

const int BUFSIZE = 8192;

class FastIO {
public:
    int _fd;
    char buffer[BUFSIZE];
    bool writable;
    int readPos, writePos;

    FastIO(FILE* file) : _fd(fileno(file)), writable(isatty(_fd)), readPos(0), writePos(0) {}

    void flush() {
        if (writable && writePos > 0) {
            fwrite(buffer, 1, writePos, stdout);
            writePos = 0;
        }
    }

    string read() {
        string result;
        while (true) {
            int bytesRead = fread(buffer + writePos, 1, BUFSIZE - writePos, stdin);
            if (bytesRead == 0) break;
            writePos += bytesRead;
            for (int i = 0; i < writePos; ++i) {
                if (buffer[i] == '\n') result.push_back('\n');
            }
        }
        return result;
    }

    string readline() {
        string line;
        while (true) {
            int bytesRead = fread(buffer + writePos, 1, BUFSIZE - writePos, stdin);
            if (bytesRead == 0) break;
            writePos += bytesRead;
            for (int i = 0; i < writePos; ++i) {
                if (buffer[i] == '\n') {
                    line.append(buffer + readPos, buffer + i);
                    readPos = i + 1;
                    return line;
                }
            }
        }
        if (readPos < writePos) {
            line.append(buffer + readPos, buffer + writePos);
            readPos = writePos;
        }
        return line;
    }
};

