let BUFSIZE = 8192

class FastIO {
    private var fd: Int32
    private var buffer: Data
    private var writable: Bool

    init(file: FileHandle) {
        self.fd = file.fileDescriptor
        self.buffer = Data()
        self.writable = file.writeabilityHandler != nil
    }

    func read() -> String {
        while true {
            let b = FileHandle(fileDescriptor: fd).readDataToEndOfFile()
            if b.count == 0 {
                break
            }
            buffer.append(b)
        }
        return String(data: buffer, encoding: .ascii) ?? ""
    }

    func readline() -> String? {
        var newlines = 0
        while newlines == 0 {
            let b = FileHandle(fileDescriptor: fd).readDataToEndOfFile()
            newlines = b.filter { $0 == 10 }.count + (b.count > 0 ? 1 : 0)
            buffer.append(b)
        }
        if let index = buffer.firstIndex(of: 10) {
            let line = String(data: buffer[..<index], encoding: .ascii)
            buffer.removeSubrange(..<index.advanced(by: 1))
            return line
        }
        return nil
    }

    func flush() {
        if writable {
            FileHandle(fileDescriptor: fd).write(buffer)
            buffer.removeAll()
        }
    }
}

class IOWrapper {
    private var buffer: FastIO

    init(file: FileHandle) {
        self.buffer = FastIO(file: file)
    }

    func read() -> String {
        return buffer.read()
    }

    func readline() -> String? {
        return buffer.readline()
    }

    func flush() {
