// Educational Codeforces Round 119 (Rated for Div. 2)
// C. BA-String

func solve() {
    let input = readLine()!.split(separator: " ").compactMap { Int($0) }
    let n = input[0]
    let k = input[1]
    let x = input[2]
    guard let s = readLine() else { return }

    if !s.contains("*") {
        print(s)
        return
    }

    let stars = s.split(separator: "a").filter { !$0.isEmpty }

    // A string of q stars can expand to 0, 1, 2, ..., q * k b's, which is
    // 1 + k * q possibilities
    let expand = stars.map { 1 + k * $0.count }

    // Cumulative product of number of stars
    var prods: [Int] = []
    for i in stride(from: expand.count - 1, through: 0, by: -1) {
        if prods.isEmpty {
            prods.append(expand[i])
        } else {
            prods.append(prods.last! * expand[i])
        }
    }

    var x = x - 1

    // Count how many b's to replace each * by
    var counts: [Int] = []
    for prod in stride(from: prods.count - 1, through: 0, by: -1) {
        counts.append(x / prod)
        x -= prod * (x / prod)
    }
    counts.append(x % prods[0])

    // Construct the string
    var answer = ""
    var i = 1
    var j = 0
    while j < s.count {
        let index = s.index(s.startIndex, offsetBy: j)
        if s[index] == "a" {
            answer.append("a")
            j += 1
        } else {
            answer.append(String(repeating: "b", count: counts[i]))
            i += 1
            while j < s.count && s[s.index(s.startIndex, offsetBy: j)] == "*" {
                j += 1
            }
        }
    }

    print(answer)
}

