import Foundation

func process(_ A: [Int], _ B: [Int], _ Q: [[Int]]) -> [Int] {
    var S = [0]
    let n = A.count
    for i in 0..<n {
        let ai = A[i]
        let bi = B[i]
        let di = bi - ai
        S.append(S.last! + di)
    }
    let nS = S.count
    let p = Int(ceil(log2(Double(nS))))
    let size = 2 * Int(pow(2.0, Double(p))) - 1
    var minTree = Array(repeating: Int.max, count: size)
    var maxTree = Array(repeating: Int.min, count: size)

    for i in 0..<nS {
        minTree[i] = S[i]
        maxTree[i] = S[i]
    }

    for i in nS..<size {
        let i1 = (2 * size - 2) - i
        let j1 = 2 * i1 + 1
        let j2 = 2 * i1 + 2
        let iLeft = (2 * size - 2) - j1
        let iRight = (2 * size - 2) - j2
        minTree[i] = min(minTree[iLeft], minTree[iRight])
        maxTree[i] = max(maxTree[iLeft], maxTree[iRight])
    }

    func findMax(_ l: Int, _ r: Int, start_l: Int = 0, start_r: Int = nS - 1, start_i: Int = size - 1) -> Int {
        if start_i < 0 {
            return Int.min
        }
        if l == r {
            return maxTree[l]
        }
        if l == start_l && r == start_r {
            return maxTree[start_i]
        }
        let i1 = (2 * size - 2) - start_i
        let iL = (2 * size - 2) - (2 * i1 + 2)
        let iR = (2 * size - 2) - (2 * i1 + 1)
        let m1 = (start_l + start_r) / 2
        if l > m1 {
            return findMax(l, r, start_l: m1 + 1, start_r: start_r, start_i: iR)
        } else if r <= m1 {
            return findMax(l, r, start_l: start_l, start_r: m1, start_i: iL)
        } else {
            let max1 = findMax(l, m1, start_l: start_l, start_r: m1, start_i: iL)
            let max2 = findMax(m1 + 1, r, start_l: m1 + 1, start_r: start_r, start_i: iR)
            return max(max1, max2)
        }
    }

    func findMin(_ l: Int, _ r: Int, start_l: Int = 0, start_r: Int = nS - 1, start_i: Int = size - 1) -> Int {
        if start_i < 0 {
            return Int.max
        }
        if l == r {
            return minTree[l]
        }
        if l == start_l && r == start_r {
            return minTree[start_i]
        }
        let i1 = (2 * size - 2) - start_i
        let iL = (2 * size - 2) - (2 * i1 + 2)
        let iR = (2 * size - 2) - (2 * i1 + 1)
        let m1 = (start_l + start_r) / 2
        if l > m1 {
            return findMin(l, r, start_l: m1 + 1, start_r: start_r, start_i: iR)
        } else if r <= m1 {
            return findMin(l, r, start_l: start_l, start_r: m1, start_i: iL)
        } else {
            let min1 = findMin(l, m1, start_l: start_l, start_r: m1, start_i: iL)
            let min2 = findMin(m1 + 1, r, start_l: m1 + 1, start_r: start_r, start_i: iR)
            return min(min1, min2)
        }
    }

    var answer: [Int] = []
    for query in Q {
        let l = query[0]
        let r = query[1]
        let s1 = S[l - 1]
        let s2 = S[r]
        if s1 != s2 {
            answer.append(-1)
        } else {
            let myMin = findMin(l, r)
            let myMax = findMax(l, r)
            if myMin - s1 < 0 {
                answer.append(-1)
            } else {
                answer.append(myMax - s1)
            }
        }
    }
    return answer
}

