        guard let secondLine = String(data: input.availableData, encoding: .utf8)?.trimmingCharacters(in: .whitespacesAndNewlines) else { continue }
        let dimensions = secondLine.split(separator: " ").compactMap { Int($0) }
        let n = dimensions[0]
        let m = dimensions[1]

        var d = Array(repeating: Array(repeating: 0, count: m), count: n)

        for i in 0..<n {
            guard let line = String(data: input.availableData, encoding: .utf8)?.trimmingCharacters(in: .whitespacesAndNewlines) else { continue }
            d[i] = line.map { char -> Int in
                switch char {
                case "R": return -1
                case "U": return -2
                case "L": return -3
                default: return -4
                }
            }
        }

        var r = 0
        var pos = (0, 0)

        for i in 0..<n {
            for j in 0..<m {
                var a = i
                var b = j
                var p = d[i][j]
                var c = 0
                var st: [(Int, Int)] = []

                while p < 0 {
                    d[a][b] = 0
                    st.append((a, b))

                    switch p {
                    case -1: b += 1
                    case -2: a -= 1
                    case -3: b -= 1
                    default: a += 1
                    }

                    c += 1

                    if a >= 0 && a < n && b >= 0 && b < m {
                        p = d[a][b]
                    } else {
                        for (ii, (x, y)) in st.enumerated() {
                            d[x][y] = c - ii
                        }
                        p = -1
                        break
                    }
                }

                if p == 0 {
                    var jj = 0
                    var flag = false
                    for (ii, (x, y)) in st.enumerated() {
                        d[x][y] = flag ? (c - jj) : (c - ii)
                        if x == a && y == b {
                            flag = true
                            jj = ii
                        }
                    }
                }

                if p > 0 {
                    for (ii, (x, y)) in st.enumerated() {
                        d[x][y] = p + c - ii
                    }
                }

                if d[i][j] > r {
                    r = d[i][j]
                    pos = (i, j)
                }
            }
        }

        print("\(pos.0 + 1) \(pos.1 + 1) \(r)")
    }
}

