// ------------------- fast io --------------------

class FastIO {
    private let fd: Int32
    private var buffer = Data()
    private let writable: Bool

    init(file: FileHandle) {
        self.fd = file.fileDescriptor
        self.writable = file.writeabilityHandler != nil
    }

    func read() -> String {
        while true {
            let data = FileHandle(fileDescriptor: fd).readDataToEndOfFile()
            if data.count == 0 {
                break
            }
            buffer.append(data)
        }
        return String(data: buffer, encoding: .ascii) ?? ""
    }

    func readline() -> String? {
        while !buffer.contains(where: { $0 == 10 }) {
            let data = FileHandle(fileDescriptor: fd).readDataToEndOfFile()
            if data.count == 0 {
                break
            }
            buffer.append(data)
        }
        guard let newlineIndex = buffer.firstIndex(of: 10) else { return nil }
        let line = String(data: buffer.prefix(upTo: newlineIndex), encoding: .ascii)
        buffer.removeSubrange(buffer.startIndex...newlineIndex)
        return line
    }

    func flush() {
        if writable {
            FileHandle(fileDescriptor: fd).write(buffer)
            buffer.removeAll()
        }
    }
}

