function pw(x: number, k: number): number {
  let res = 1;
  while (k) {
    if (k & 1) {
      res *= x;
      res %= mod;
    }
    k >>= 1;
    x *= x;
    x %= mod;
  }
  return res;
}

function c(n: number, k: number): number {
  if (k < 0) return 0;
  let res = 1;
  for (let i = n - k + 1; i <= n; ++i) {
    res *= i;
    res %= mod;
  }
  for (let i = 2; i <= k; ++i) {
    res *= pw(i, mod - 2);
    res %= mod;
  }
  return res;
}

