const mod: number = 998244353;
const sz: number = 2e6 + 5;
let fac: number[] = new Array(sz).fill(1);
let ifac: number[] = new Array(sz);
let prime: number[] = new Array(sz);

function mpow(a: number, b: number = mod - 2, m: number = mod): number {
    let res: number = 1;
    a %= m;
    assert(b >= 0);
    for (; b; b >>= 1) {
        if (b & 1) res = (res * a) % m;
        a = (a * a) % m;
    }
    return res;
}

function init(): void {
    fac.resize(sz, 1);
    ifac.resize(sz);
    for (let i: number = 2; i < sz; i++) fac[i] = (fac[i - 1] * i) % mod;
    ifac[sz - 1] = mpow(fac[sz - 1]);
    for (let i: number = sz - 2; i >= 0; i--)
        ifac[i] = (ifac[i + 1] * (i + 1)) % mod;
    prime.resize(sz);
    for (let i: number = 2; i < sz; i++) prime[i] = i;
    for (let i: number = 2; i * i < sz; i++) {
        if (prime[i] !== i) continue;
        for (let j: number = i * i; j < sz; j += i)
            if (prime[j] === j) prime[j] = i;
    }
}

function nCr(n: number, r: number): number {
    if (n <= 0 || r < 0) return 0;
    if (n < r) return 0;
    return (fac[n] * (ifac[r] * ifac[n - r] % mod)) % mod;
}

function gcd(a: number, b: number): number { return b ? gcd(b, a % b) : a; }
function lcm(a: number, b: number): number { return Math.floor((a / gcd(a, b)) * b); }

