                process.stdout.write(`${indx} `);
                players.push(indx);
            }
            process.stdout.write("\n");
        }
        for (table_no = 1; table_no <= rem_tables; ++table_no) {
            process.stdout.write(`${less_people} `);
            for (let peep: number = 1; peep <= less_people; peep++) {
                let indx: number = players.shift()!;
                process.stdout.write(`${indx} `);
                players.push(indx);
