func take[T any](a []T, scanner *bufio.Scanner) {
	for i := range a {
		scanner.Scan()
		var v T
		switch any(v).(type) {
		case int:
			v = T(strconv.Atoi(scanner.Text())[0])
		case int64:
			v = T(strconv.ParseInt(scanner.Text(), 10, 64)[0])
		case string:
			v = T(scanner.Text())
		}
		a[i] = v
	}
}

func digits(n int64) int {
	k := 0
	for n != 0 {
		k++
		n /= 10
	}
	return k
}

func isprime(n int64) bool {
	if n == 1 {
		return false
	}
	if n == 2 {
		return true
	}
	if n%2 == 0 {
		return false
	}
	for i := int64(3); i*i <= n; i += 2 {
		if n%i == 0 {
			return false
		}
	}
	return true
}

func power(x, y, MOD int64) int64 {
	ans := int64(1)
	x %= MOD
	for y > 0 {
		if y%2 == 1 {
			ans = (ans * x) % MOD
		}
		y /= 2
		x = (x * x) % MOD
	}
	return ans
}

func sieve(a []bool, n int64) {
	a[1] = false
	a[0] = false
	h := int64(math.Sqrt(float64(n + 1)))
	for i := int64(2); i < h; i++ {
		if !a[i] {
			continue
		}
		for j := 2 * i; j < n+1; j += i {
			a[j] = false
		}
	}
}

func bits(n int64) []int64 {
	var a []int64
	for i := int64(0); i < 33; i++ {
		a = append(a, n%2)
		n /= 2
	}
	reverse(a)
	return a
}

func reverse[T any](a []T) {
	for i, j := 0, len(a)-1; i < j; i, j = i+1, j-1 {
		a[i], a[j] = a[j], a[i]
	}
}

