	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var n, q int
	fmt.Fscanf(reader, "%d %d\n", &n, &q)

	a := make([]int64, n)
	for i := 0; i < n; i++ {
		fmt.Fscanf(reader, "%d", &a[i])
	}

	for i := 0; i < n; i++ {
		var b int
		fmt.Fscanf(reader, "%d", &b)
		a[i] = int64(b) - a[i]
		if i > 0 {
			a[i] += a[i-1]
		}
	}

	const maxK = 20
	mn := make([][]int64, maxK)
	mx := make([][]int64, maxK)
	for k := range mn {
		mn[k] = make([]int64, n)
		mx[k] = make([]int64, n)
	}

	copy(mn[0], a)
	copy(mx[0], a)

	for k := 1; k < maxK; k++ {
		for i := 0; i+(1<<(k-1)) < n; i++ {
			mn[k][i] = min(mn[k-1][i], mn[k-1][i+(1<<(k-1))])
			mx[k][i] = max(mx[k-1][i], mx[k-1][i+(1<<(k-1))])
		}
	}

	for q > 0 {
		var l, r int
		fmt.Fscanf(reader, "%d %d\n", &l, &r)
		l--
		k := log2(r - l)
		_min := min(mn[k][l], mn[k][r-(1<<k)])
		_max := max(mx[k][l], mx[k][r-(1<<k)])
