	"os"
)

const (
	maxN = 2020
)

var (
	str    [maxN][maxN]byte
	fusnfe [maxN][maxN]int
	vis    [maxN][maxN]int
	ret    [maxN][maxN]int
	ans    [maxN][maxN]int
	cur    int
	n, m   int
	cyc    bool
	beg    struct{ x, y int }
)

func dfs(x, y, t int) int {
	if x < 0 || x == n || y < 0 || y == m {
		return 0
	}
	if vis[x][y] == cur && ret[x][y] < cur {
		cyc = true
		beg = struct{ x, y int }{x, y}
		ans[x][y] = t - fusnfe[x][y]
		return ans[x][y]
	}
	if vis[x][y] == cur {
		return ans[x][y]
	}
	vis[x][y] = cur
	fusnfe[x][y] = t
	var gox, goy int
	switch str[x][y] {
	case 'R':
		goy++
	case 'L':
		goy--
	case 'U':
		gox--
	case 'D':
		gox++
	}
	r := dfs(gox, goy, t+1)
	if cyc {
		if beg.x == x && beg.y == y {
			cyc = false
		}
		ans[x][y] = r
	} else {
		ans[x][y] = r + 1
	}
	ret[x][y] = cur
	return ans[x][y]
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	fmt.Scanf("%d", &cur)
	for cur > 0 {
		cur--
		fmt.Scanf("%d%d", &n, &m)
		for i := 0; i < n; i++ {
			for j := 0; j < m; j++ {
				vis[i][j] = 0
			}
		}
		for i := 0; i < n; i++ {
			scanner.Scan()
			copy(str[i][:], scanner.Bytes())
		}
		var mx, ansx, ansy int
		for i := 0; i < n; i++ {
			for j := 0; j < m; j++ {
				if vis[i][j] != 0 {
					continue
				}
				t := dfs(i, j)
				if t > mx {
					mx = t
					ansx = i + 1
					ansy = j + 1
				}
			}
		}
		fmt.Printf("%d %d %d\n", ansx, ansy, mx)
	}
}

