func pw(x int64, k int) int64 {
	res := big.NewInt(1)
	bx := big.NewInt(x)
	bk := big.NewInt(int64(k))
	bmod := big.NewInt(mod)
	for bk.Sign() > 0 {
		if bk.Bit(0) == 1 {
			res.Mul(res, bx).Mod(res, bmod)
		}
		bk.Rsh(bk, 1)
		bx.Mul(bx, bx).Mod(bx, bmod)
	}
	return res.Int64()
}

func c(n, k int) int64 {
	if k < 0 {
		return 0
	}
	res := big.NewInt(1)
	for i := n - k + 1; i <= n; i++ {
		res.Mul(res, big.NewInt(int64(i))).Mod(res, big.NewInt(mod))
	}
	for i := 2; i <= k; i++ {
		res.Mul(res, big.NewInt(pw(int64(i), mod-2))).Mod(res, big.NewInt(mod))
	}
	return res.Int64()
}

func is(c [2]byte) bool {
	a := [2]byte{'?', '?'}
	return a[0] == c[0] && a[1] == c[1]
}

func solve() {
	var n int
	fmt.Scanf("%d", &n)
	_b, b_, _w, w_, __, e, tw, tb := 0, false, 0, false, 0, 0, 0, 0
	same := false
	for i := 0; i < n; i++ {
		var a [2]byte
		fmt.Scanf("%s", &a)
		for _, ch := range a {
			if ch == 'B' {
				tb++
			} else if ch == 'W' {
				tw++
			}
		}
		if is(a) {
			__++
		}
		if string(a[:]) == "BB" || string(a[:]) == "WW" {
			same = true
		}
		switch a[0] {
		case 'B':
			b_ = true
		case 'W':
			w_ = true
		case '?':
			e++
		}
		switch a[1] {
		case 'B':
			_b = true
		case 'W':
			_w = true
		case '?':
			e++
		}
	}
	d := abs(tb - tw)
	res := c(e, (e-d)/2)
	if !same {
		res -= pw(2, __)
		if !_w && !b_ {
			res++
		}
		if !w_ && !_b {
			res++
		}
		if res < 0 {
			res += mod
		}
	}
	fmt.Printf("%d", res)
}

