func solve(u int) int64 {
	var cnt [4]int64
	for i := 1; i <= n; i++ {
		if i == u {
			continue
		}
		_x := int(math.Abs(float64(x[i] - x[u])))
		_y := int(math.Abs(float64(y[i] - y[u])))
		id := 0
		if _x&1 != 0 {
			id += 2
		}
		if _y&1 != 0 {
			id += 1
		}
		cnt[id]++
	}
	var sum int64
	sum += cnt[0]*cnt[1] + cnt[0]*cnt[2] + cnt[0]*cnt[3]
	for i := 0; i < 4; i++ {
		sum += (cnt[i] * (cnt[i] - 1)) / 2
	}
	return sum
}

