const mod int64 = 998244353
const sz int64 = 2e6 + 5

var fac []int64
var ifac []int64
var prime []int

func mpow(a, b, m int64) int64 {
	res := int64(1)
	a %= m
	for ; b > 0; b >>= 1 {
		if b&1 == 1 {
			res = res * a % m
		}
		a = a * a % m
	}
	return res
}

func init() {
	fac = make([]int64, sz)
	ifac = make([]int64, sz)
	for i := int64(2); i < sz; i++ {
		fac[i] = (fac[i-1] * i) % mod
	}
	ifac[sz-1] = mpow(fac[sz-1])
	for i := sz - 2; i >= 0; i-- {
		ifac[i] = (ifac[i+1] * (i + 1)) % mod
	}
	prime = make([]int, sz)
	for i := 2; i < int(sz); i++ {
		prime[i] = i
	}
	for i := int64(2); i*i < sz; i++ {
		if prime[i] != int(i) {
			continue
		}
		for j := i * i; j < sz; j += i {
			if prime[j] == int(j) {
				prime[j] = int(i)
			}
		}
	}
}

func nCr(n, r int64) int64 {
	if n <= 0 || r < 0 {
		return 0
	}
	if n < r {
		return 0
	}
	return (fac[n] * (ifac[r] * ifac[n-r] % mod)) % mod
}

func gcd(a, b int64) int64 {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

func lcm(a, b int64) int64 {
	return (a / gcd(a, b)) * b
}

func solve() {
	var n, m, k int64
	fmt.Scan(&n, &m, &k)
	highTables := n % m
	remTables := m - highTables
	highPeople := (n + m - 1) / m
	lessPeople := n / m
	players := make([]int64, n)
	for i := int64(0); i < n; i++ {
		players[i] = i + 1
	}
	for game := int64(0); game < k; game++ {
		tableNo := int64(1)
		for tableNo <= highTables {
			fmt.Printf("%d ", highPeople)
			for peep := int64(1); peep <= highPeople; peep++ {
				indx := players[0]
				fmt.Printf("%d ", indx)
				players = append(players[1:], indx)
			}
			fmt.Println()
			tableNo++
		}
		for tableNo <= remTables {
			fmt.Printf("%d ", lessPeople)
			for peep := int64(1); peep <= lessPeople; peep++ {
				indx := players[0]
				fmt.Printf("%d ", indx)
				players = append(players[1:], indx)
			}
			fmt.Println()
			tableNo++
		}
		shiftBack := highTables * highPeople
		for i := int64(0); i < shiftBack; i++ {
			indx := players[0]
			players = append(players[1:], indx)
		}
	}
	fmt.Println()
}

