    }

    public static <T> void take(List<T> a, BufferedReader br) throws IOException {
        String[] input = br.readLine().split(" ");
        for (int i = 0; i < a.size(); i++) {
            if (a.get(0) instanceof Integer) {
                a.set(i, (T) Integer.valueOf(input[i]));
            } else if (a.get(0) instanceof Long) {
                a.set(i, (T) Long.valueOf(input[i]));
            }
        }
    }

    public static long digits(long n) {
        long k = 0;
        while (n != 0) {
            k++;
            n /= 10;
        }
        return k;
    }

    public static boolean isprime(long n) {
        if (n == 1) return false;
        if (n == 2) return true;
        if (n % 2 == 0) return false;
        for (long i = 3; i * i <= n; i += 2) {
            if (n % i == 0) return false;
        }
        return true;
    }

    public static long power(long x, long y, long MOD) {
        long ans = 1;
        x %= MOD;
        while (y > 0) {
            if ((y & 1) == 1) ans = (ans * x) % MOD;
            y >>= 1;
            x = (x * x) % MOD;
        }
        return ans;
    }

    public static void sieve(List<Boolean> a, long n) {
        for (int i = 2; i < Math.sqrt(n + 1); i++) {
            if (!a.get(i)) continue;
            for (int j = 2 * i; j < n + 1; j += i) a.set(j, false);
        }
    }

    public static void load(Map<Long, Long> g) {
        g.loadFactor(0.25f);
    }

    public static List<Long> bits(long n) {
        List<Long> a = new ArrayList<>();
        for (int i = 0; i < 33; i++) {
            a.add(n % 2);
            n /= 2;
        }
        Collections.reverse(a);
        return a;
    }

    public static void sub() {}

    private static final long N = 1_000_000_007L;
    private static final long M = 998_244_353L;

    public static void solve(BufferedReader br, PrintWriter out) throws IOException {
        int n = Integer.parseInt(br.readLine());
        List<Long> a = new ArrayList<>(Collections.nCopies(n, 0L));
        take(a, br);
        long ans = 0;
        for (long i : a) {
            if (i == 1) ans++;
        }
        ans = (power(2, ans, M) - 1 + M) % M;
        List<Long> b = new ArrayList<>(Collections.nCopies(n + 3, 0L));
        List<Long> c = new ArrayList<>(Collections.nCopies(n + 3, 0L));
        for (int i = 0; i < n; i++) {
            if (a.get(i) == 0) b.set(0, (2 * b.get(0) + 1) % M);
            if (a.get(i) == 1) b.set(1, (2 * b.get(1) + b.get(0)) % M);
            if (a.get(i) > 1) b.set((int) a.get(i), (2 * b.get((int) a.get(i)) + b.get((int) a.get(i) - 1)) % M);
            if (a.get(i) > 1) c.set((int) a.get(i) - 1, (2 * c.get((int) a.get(i) - 1) + b.get((int) a.get(i) - 2)) % M);
            c.set((int) a.get(i) + 1, (2 * c.get((int) a.get(i) + 1)) % M);
        }
        for (int i = 0; i < n + 1; i++) {
            ans = (ans + b.get(i) + c.get(i)) % M;
        }
        out.println(ans);
    }

    static class Pair<T, U> {
        T first;
        U second;

        public Pair(T first, U second) {
            this.first = first;
            this.second = second;
        }
    }
}

