public class Main {
    static long[] a = new long[2022];
    static long pos;
    static List<Long> ans = new ArrayList<>();

    public static void go() {
        ans.add(pos);
        for (int i = 1; i <= pos / 2; i++) {
            long temp = a[i];
            a[i] = a[pos - i + 1];
            a[pos - i + 1] = temp;
        }
    }

    public static void solve() {
        Scanner scanner = new Scanner(System.in);
        long n = scanner.nextLong();
        for (long i = 1; i <= n; i++) a[(int) i] = scanner.nextLong();
        ans.clear();
        for (long i = 1; i <= n; i++) {
            if (i % 2 != a[(int) i] % 2) {
                System.out.println("-1");
                return;
            }
        }
        for (long i = n; i > 1; i -= 2) {
            for (long j = 1; j <= n; j++) {
                if (a[(int) j] == i) {
                    pos = j;
                    break;
                }
            }
            go();
            for (long j = 1; j <= n; j++) {
                if (a[(int) j] == i - 1) {
                    pos = j - 1;
                    break;
                }
            }
            go();
            for (long j = 1; j <= n; j++) {
                if (a[(int) j] == i - 1) {
                    pos = j + 1;
                    break;
                }
            }
            go();
            pos = 3;
            go();
            pos = i;
            go();
        }
        System.out.println(ans.size());
        for (long i : ans) System.out.print(i + " ");
        System.out.println();
    }

