public class Main {
    static final long MOD = 998244353;
    static final int SZ = (int) 2e6 + 5;
    static List<Long> fac, ifac;
    static List<Integer> prime;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));
        init();
        int t = Integer.parseInt(br.readLine());
        for (int i = 0; i < t; i++) {
            solve(br, bw);
        }
        bw.flush();
    }

    static long mpow(long a, long b, long m) {
        long res = 1;
        a %= m;
        assert b >= 0;
        while (b > 0) {
            if ((b & 1) == 1) res = res * a % m;
            a = a * a % m;
            b >>= 1;
        }
        return res;
    }

    static void init() {
        fac = new ArrayList<>(Collections.nCopies(SZ, 1L));
        ifac = new ArrayList<>(SZ);
        for (int i = 2; i < SZ; i++) {
            fac.set(i, (fac.get(i - 1) * i) % MOD);
        }
        ifac.set(SZ - 1, mpow(fac.get(SZ - 1), MOD - 2, MOD));
        for (int i = SZ - 2; i >= 0; i--) {
            ifac.set(i, (ifac.get(i + 1) * (i + 1)) % MOD);
        }
        prime = new ArrayList<>(Collections.nCopies(SZ, 0));
        for (int i = 2; i < SZ; i++) {
            prime.set(i, i);
        }
        for (int i = 2; i * i < SZ; i++) {
            if (!prime.get(i).equals(i)) continue;
            for (int j = i * i; j < SZ; j += i) {
                if (prime.get(j).equals(j)) prime.set(j, i);
            }
        }
    }

    static long nCr(long n, long r) {
        if (n <= 0 || r < 0) return 0;
        if (n < r) return 0;
        return (fac.get((int) n) * (ifac.get((int) r) * ifac.get((int) (n - r)) % MOD)) % MOD;
    }

    static long gcd(long a, long b) {
        return b == 0 ? a : gcd(b, a % b);
    }

    static long lcm(long a, long b) {
        return (a / gcd(a, b)) * b;
    }

    static void solve(BufferedReader br, BufferedWriter bw) throws IOException {
        String[] input = br.readLine().split(" ");
        long n = Long.parseLong(input[0]);
        long m = Long.parseLong(input[1]);
        long k = Long.parseLong(input[2]);
        long highTables = n % m;
        long remTables = m - highTables;
        long highPeople = (n + m - 1) / m;
        long lessPeople = n / m;
        Queue<Long> players = new LinkedList<>();
        for (int i = 1; i <= n; i++) {
            players.add((long) i);
        }
        for (long game = 0; game < k; game++) {
            long tableNo;
            for (tableNo = 1; tableNo <= highTables; ++tableNo) {
                bw.write(highPeople + " ");
                for (int peep = 1; peep <= highPeople; peep++) {
                    long indx = players.peek();
                    bw.write(indx + " ");
                    players.poll();
                    players.add(indx);
                }
                bw.newLine();
            }
            for (tableNo = 1; tableNo <= remTables; ++tableNo) {
                bw.write(lessPeople + " ");
                for (int peep = 1; peep <= lessPeople; peep++) {
                    long indx = players.peek();
                    bw.write(indx + " ");
                    players.poll();
                    players.add(indx);
                }
                bw.newLine();
            }
            long shiftBack = highTables * highPeople;
            for (int i = 0; i < shiftBack; i++) {
                long indx = players.peek();
                players.poll();
                players.add(indx);
            }
        }
        bw.newLine();
    }
}

