    static void Sub() { }

    const long N = 1_000_000_007;
    const long M = 998_244_353;

    static void Solve()
    {
        long n = long.Parse(Console.ReadLine());
        List<long> a = Console.ReadLine().Split(' ').Select(long.Parse).ToList();
        long ans = 0;
        foreach (var x in a)
        {
            if (x == 1) ans++;
        }
        ans = (Power(2, ans, M) - 1 + M) % M;
        List<long> b = new List<long>(new long[n + 3]);
        List<long> c = new List<long>(new long[n + 3]);
        for (long i = 0; i < n; i++)
        {
            if (a[(int)i] == 0) b[0] = (2 * b[0] + 1) % M;
            if (a[(int)i] == 1) b[1] = (2 * b[1] + b[0]) % M;
            if (a[(int)i] > 1) b[a[(int)i]] = (2 * b[a[(int)i]] + b[a[(int)i] - 1]) % M;
            if (a[(int)i] > 1) c[a[(int)i] - 1] = (2 * c[a[(int)i] - 1] + b[a[(int)i] - 2]) % M;
            c[a[(int)i] + 1] = (2 * c[a[(int)i] + 1]) % M;
        }
        for (long i = 0; i < n + 1; i++)
        {
            ans = (ans + b[(int)i] + c[(int)i]) % M;
        }
        Console.WriteLine(ans);
    }

    static long Power(long x, long y, long MOD)
    {
        long ans = 1;
        x %= MOD;
        while (y > 0)
        {
            if (y % 2 == 1) ans = (ans * x) % MOD;
            y /= 2;
            x = (x * x) % MOD;
        }
        return ans;
    }

