    }

    static bool IsPrime(long n)
    {
        if (n == 1) return false;
        if (n == 2) return true;
        if (n % 2 == 0) return false;
        for (long i = 3; i * i <= n; i += 2)
        {
            if (n % i == 0) return false;
        }
        return true;
    }

    static void Sieve(List<bool> a, long n)
    {
        a[1] = false;
        a[0] = false;
        long h = (long)Math.Sqrt(n + 1);
        for (long i = 2; i < h; i++)
        {
            if (!a[(int)i]) continue;
            for (long j = 2 * i; j < n + 1; j += i)
            {
                a[(int)j] = false;
            }
        }
    }

