class Program
{
    static int Log2(int x)
    {
        return 31 - BitOperations.LeadingZeroCount(x);
    }

    static void Main()
    {
        Console.InputEncoding = System.Text.Encoding.UTF8;
        Console.OutputEncoding = System.Text.Encoding.UTF8;

        var input = Console.In;
        var output = Console.Out;

        int n = int.Parse(input.ReadLine());
        int q = int.Parse(input.ReadLine());

        List<long> a = new List<long>(n);
        for (int i = 0; i < n; i++)
        {
            a.Add(long.Parse(input.ReadLine()));
        }

        for (int i = 0; i < n; i++)
        {
            int b = int.Parse(input.ReadLine());
            a[i] = b - a[i];
            if (i > 0)
            {
                a[i] += a[i - 1];
            }
        }

        List<List<long>> mn = new List<List<long>>(20);
        List<List<long>> mx = new List<List<long>>(20);

        for (int i = 0; i < 20; i++)
        {
            mn.Add(new List<long>(n));
            mx.Add(new List<long>(n));
        }

        a.CopyTo(mn[0]);
        a.CopyTo(mx[0]);

        for (int k = 1; k < 20; k++)
        {
            for (int i = 0; i + (1 << (k - 1)) < n; i++)
            {
                mn[k][i] = Math.Min(mn[k - 1][i], mn[k - 1][i + (1 << (k - 1))]);
                mx[k][i] = Math.Max(mx[k - 1][i], mx[k - 1][i + (1 << (k - 1))]);
            }
        }

        while (q-- > 0)
        {
            var lr = input.ReadLine().Split(' ');
            int l = int.Parse(lr[0]) - 1;
            int r = int.Parse(lr[1]);

            int k = Log2(r - l);
            long _min = Math.Min(mn[k][l], mn[k][r - (1 << k)]);
            long _max = Math.Max(mx[k][l], mx[k][r - (1 << k)]);
            long start = l > 0 ? a[l - 1] : 0;

            if (start != a[r - 1] || _min < start)
            {
                output.WriteLine("-1");
            }
            else
            {
                output.WriteLine(_max - start);
            }
        }
    }
}

