class Program
{
    const long mod = 1000000007;
    const int N = 1005;
    static int[] dsu0 = new int[N];
    static int[] dsu1 = new int[N];

    static int Solve(int id, int u)
    {
        if (id == 0 && dsu0[u] == -1) return u;
        if (id == 1 && dsu1[u] == -1) return u;
        return id == 0 ? dsu0[u] = Solve(0, dsu0[u]) : dsu1[u] = Solve(1, dsu1[u]);
    }

    static void Main()
    {
        Console.SetIn(new System.IO.StreamReader(Console.OpenStandardInput()));
        Console.SetOut(new System.IO.StreamWriter(Console.OpenStandardOutput()) { AutoFlush = true });

        long t = 1;
        while (t-- > 0)
        {
            string[] input = Console.ReadLine().Split();
            int n = int.Parse(input[0]);
            int m1 = int.Parse(input[1]);
            int m2 = int.Parse(input[2]);

            Array.Fill(dsu0, -1);
            Array.Fill(dsu1, -1);

            for (int i = 0; i < m1; ++i)
            {
                input = Console.ReadLine().Split();
                int u = int.Parse(input[0]);
                int v = int.Parse(input[1]);
                int fu = Solve(0, u);
                int fv = Solve(0, v);
                dsu0[fu] = fv;
            }

            for (int i = 0; i < m2; ++i)
            {
                input = Console.ReadLine().Split();
                int u = int.Parse(input[0]);
                int v = int.Parse(input[1]);
                int fu = Solve(1, u);
                int fv = Solve(1, v);
                dsu1[fu] = fv;
            }

            List<(int, int)> ans = new List<(int, int)>();
            for (int i = 1; i <= n; ++i)
            {
                for (int j = i + 1; j <= n; ++j)
                {
                    if (Solve(0, i) != Solve(0, j) && Solve(1, i) != Solve(1, j))
                    {
                        ans.Add((i, j));
                        dsu0[Solve(0, i)] = Solve(0, j);
                        dsu1[Solve(1, i)] = Solve(1, j);
                    }
                }
            }

            Console.WriteLine(ans.Count);
            foreach (var x in ans)
            {
                Console.WriteLine($"{x.Item1} {x.Item2}");
            }
        }
    }
