    static long Pw(long x, int k)
    {
        long res = 1L;
        while (k > 0)
        {
            if ((k & 1) == 1)
            {
                res *= x;
                res %= mod;
            }
            k >>= 1;
            x *= x;
            x %= mod;
        }
        return res;
    }

    static long C(int n, int k)
    {
        if (k < 0) return 0;
        long res = 1;
        for (int i = n - k + 1; i <= n; ++i)
        {
            res *= i;
            res %= mod;
        }
        for (int i = 2; i <= k; ++i)
        {
            res *= Pw(i, mod - 2);
            res %= mod;
        }
        return res;
    }

    static bool Is(char[] c)
    {
        char[] a = new char[2];
        Console.Read(a, 0, 2);
        return a[0] == c[0] && a[1] == c[1];
    }

    static void Solve()
    {
        int n = Convert.ToInt32(Console.ReadLine());
        int _b = 0, b_ = 0, _w = 0, w_ = 0, __ = 0, e = 0, tw = 0, tb = 0;
        bool same = false;

        for (int i = 0; i < n; ++i)
        {
            char[] a = new char[2];
            Console.Read(a, 0, 2);
            for (int j = 0; j < 2; ++j)
            {
                if (a[j] == 'B')
                    tb++;
                else if (a[j] == 'W')
                    tw++;
            }
            if (Is(new char[] { '?', '?' })) __++;
            if (Is(new char[] { 'B', 'B' }) || Is(new char[] { 'W', 'W' })) same = true;
            switch (a[0])
