class Program
{
    const long mod = 998244353;
    const long sz = 2e6 + 5;
    static List<long> fac, ifac;
    static List<int> prime;

    static long Mpow(long a, long b = mod - 2, long m = mod)
    {
        long res = 1;
        a %= m;
        while (b > 0)
        {
            if ((b & 1) == 1) res = res * a % m;
            a = a * a % m;
            b >>= 1;
        }
        return res;
    }

    static void Init()
    {
        fac = new List<long>(new long[sz]);
        ifac = new List<long>(new long[sz]);
        for (long i = 2; i < sz; i++) fac[(int)i] = (fac[(int)(i - 1)] * i) % mod;
        ifac[(int)(sz - 1)] = Mpow(fac[(int)(sz - 1)]);
        for (long i = sz - 2; i >= 0; i--)
            ifac[(int)i] = (ifac[(int)(i + 1)] * (i + 1)) % mod;
        prime = new List<int>(new int[sz]);
        for (int i = 2; i < sz; i++) prime[i] = i;
        for (long i = 2; i * i < sz; i++)
        {
            if (prime[(int)i] != i) continue;
            for (long j = i * i; j < sz; j += i)
                if (prime[(int)j] == j) prime[(int)j] = (int)i;
        }
    }

    static long NCr(long n, long r)
    {
        if (n <= 0 || r < 0) return 0;
        if (n < r) return 0;
        return (fac[(int)n] * (ifac[(int)r] * ifac[(int)(n - r)] % mod)) % mod;
    }

    static long Gcd(long a, long b) { return b != 0 ? Gcd(b, a % b) : a; }
    static long Lcm(long a, long b) { return (a / Gcd(a, b)) * b; }

    static void Solve()
    {
        long n, m, k;
        Console.ReadLine().Split(' ').Select(long.Parse).ToArray();
        long high_tables = n % m;
        long rem_tables = m - high_tables;
        long high_people = (n + m - 1) / m;
        long less_people = n / m;
        Queue<long> players = new Queue<long>();
        for (int i = 1; i <= n; i++) players.Enqueue(i);
        for (long game = 0; game < k; game++)
        {
            long table_no;
            for (table_no = 1; table_no <= high_tables; ++table_no)
            {
                Console.Write(high_people + " ");
                for (int peep = 1; peep <= high_people; peep++)
                {
                    long indx = players.Peek();
                    Console.Write(indx + " ");
                    players.Dequeue();
                    players.Enqueue(indx);
                }
                Console.WriteLine();
            }
            for (table_no = 1; table_no <= rem_tables; ++table_no)
            {
                Console.Write(less_people + " ");
                for (int peep = 1; peep <= less_people; peep++)
                {
                    long indx = players.Peek();
                    Console.Write(indx + " ");
                    players.Dequeue();
                    players.Enqueue(indx);
                }
                Console.WriteLine();
            }
            long shift_back = high_tables * high_people;
            for (int i = 0; i < shift_back; i++)
            {
                long indx = players.Peek();
                players.Dequeue();
                players.Enqueue(indx);
            }
        }
        Console.WriteLine();
    }

    static void Main()
    {
        Init();
        int t = int.Parse(Console.ReadLine());
        for (int i = 1; i <= t; i++)
        {
            Solve();
        }
    }
}

