fn dfs(v: usize, a: &[i32], f: &[usize], color: &mut [i8], dp: &mut [i32], cycle: &mut bool) {
    if *cycle { return; }
    color[v] = 1;
    if a[v] == 0 {
        dp[v] = 0;
        color[v] = 2;
        return;
    }
    let u = f[v];
    if color[u] == 0 {
        dfs(u, a, f, color, dp, cycle);
    }
    if color[u] == 1 {
        *cycle = true;
        return;
    }
    dp[v] = dp[u] + 1;
    color[v] = 2;
}

fn solve(tc: i32) {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    let line = lines.next().unwrap().unwrap();
    let mut parts = line.split_whitespace();
    let n: usize = parts.next().unwrap().parse().unwrap();
    let d: usize = parts.next().unwrap().parse().unwrap();

    let mut a = vec![0; N];
    let mut f = vec![0; N];
    let mut color = vec![0; N];
    let mut dp = vec![INF; N];

    for i in 0..n {
        a[i] = parts.next().unwrap().parse().unwrap();
        f[i] = (i + n - d) % n;
        color[i] = 0;
        dp[i] = INF;
    }

    let mut cycle = false;
    for i in 0..n {
        if color[i] == 0 {
            dfs(i, &a, &f, &mut color, &mut dp, &mut cycle);
        }
        if cycle { break; }
    }
    if cycle {
        println!("-1");
        return;
    }
    let max_dp = *dp.iter().max().unwrap();
    println!("{}", max_dp);
}

