fn solve(n: usize, k: i64, x: &mut i64, s: &str) {
    let mut vec = Vec::new();
    let mut ans = Vec::new();
    let mut cnt = 0;

    for c in s.chars() {
        if c == '*' {
            cnt += 1;
        } else {
            vec.push(cnt * k);
            cnt = 0;
        }
    }
    vec.push(cnt * k);

    for &v in vec.iter().rev() {
        ans.push((x % (v + 1)) as usize);
        *x /= v + 1;
    }

    let sr = ans.len();
    for _ in sr..vec.len() {
        ans.push(0);
    }

    ans.reverse();
    let mut fin = String::new();
    for &a in &ans {
        fin.extend(std::iter::repeat('b').take(a));
        if a != 0 {
            fin.push('a');
        }
    }

    print!("{}", fin.trim_end_matches('a'));
}

