    let q = first_line[1];

    let a: Vec<i64> = lines.next().unwrap()
        .split_whitespace()
        .map(|s| s.parse().unwrap())
        .collect();

    let mut b: Vec<i64> = lines.next().unwrap()
        .split_whitespace()
        .map(|s| s.parse().unwrap())
        .collect();

    for i in 0..n {
        b[i] -= a[i];
        if i > 0 {
            b[i] += b[i - 1];
        }
    }

    let mut mn = vec![vec![0; n]; 20];
    let mut mx = vec![vec![0; n]; 20];

    for i in 0..n {
        mn[0][i] = b[i];
        mx[0][i] = b[i];
    }

    for k in 1..20 {
        for i in 0..(n - (1 << (k - 1))) {
            mn[k][i] = mn[k - 1][i].min(mn[k - 1][i + (1 << (k - 1))]);
            mx[k][i] = mx[k - 1][i].max(mx[k - 1][i + (1 << (k - 1))]);
        }
    }

    let mut output = io::stdout();
    for _ in 0..q {
        let query: Vec<usize> = lines.next().unwrap()
            .split_whitespace()
            .map(|s| s.parse().unwrap())
            .collect();
        let l = query[0] - 1;
        let r = query[1];

        let k = log2(r - l);
        let _min = mn[k][l].min(mn[k][r - (1 << k)]);
        let _max = mx[k][l].max(mx[k][r - (1 << k)]);
        let start = if l > 0 { b[l - 1] } else { 0 };

        if start != b[r - 1] || _min < start {
            writeln!(output, "-1")?;
        } else {
            writeln!(output, "{}", _max - start)?;
        }
    }

    Ok(())
}

