fn dfs(x: isize, y: isize, t: isize, n: isize, m: isize, str: &Vec<Vec<char>>, vis: &mut Vec<Vec<isize>>, fusnfe: &mut Vec<Vec<isize>>, ret: &mut Vec<Vec<isize>>, ans: &mut Vec<Vec<isize>>, cur: isize, beg: &mut (isize, isize), cyc: &mut bool) -> isize {
    if x < 0 || x == n || y < 0 || y == m {
        return 0;
    }
    if vis[x as usize][y as usize] == cur && ret[x as usize][y as usize] < cur {
        *cyc = true;
        *beg = (x, y);
        ans[x as usize][y as usize] = t - fusnfe[x as usize][y as usize];
        return ans[x as usize][y as usize];
    }
    if vis[x as usize][y as usize] == cur {
        return ans[x as usize][y as usize];
    }
    vis[x as usize][y as usize] = cur;
    fusnfe[x as usize][y as usize] = t;
    let mut gox = x;
    let mut goy = y;
    match str[x as usize][y as usize] {
        'R' => goy += 1,
        'L' => goy -= 1,
        'U' => gox -= 1,
        'D' => gox += 1,
        _ => {}
    }
    let r = dfs(gox, goy, t + 1, n, m, str, vis, fusnfe, ret, ans, cur, beg, cyc);
    if *cyc {
        if (x, y) == *beg {
            *cyc = false;
        }
        ans[x as usize][y as usize] = r;
    } else {
        ans[x as usize][y as usize] = r + 1;
    }
    ret[x as usize][y as usize] = cur;
    ans[x as usize][y as usize]
}

