fn pw(mut x: i64, mut k: i32) -> i64 {
    let mut res = 1;
    while k > 0 {
        if k & 1 == 1 {
            res *= x;
            res %= MOD;
        }
        k >>= 1;
        x *= x;
        x %= MOD;
    }
    res
}

fn c(n: i32, k: i32) -> i64 {
    if k < 0 {
        return 0;
    }
    let mut res = 1;
    for i in (n - k + 1)..=n {
        res *= i as i64;
        res %= MOD;
    }
    for i in 2..=k {
        res *= pw(i as i64, (MOD - 2) as i32);
        res %= MOD;
    }
    res
}

