use std::collections::VecDeque;

const MOD: u64 = 998244353;
const SZ: usize = 2_000_006 + 5;

fn mpow(mut a: u64, mut b: u64, m: u64) -> u64 {
    let mut res = 1;
    a %= m;
    while b > 0 {
        if b & 1 == 1 {
            res = res * a % m;
        }
        a = a * a % m;
        b >>= 1;
    }
    res
}

fn init() -> (Vec<u64>, Vec<u64>, Vec<i32>) {
    let mut fac = vec![1; SZ];
    let mut ifac = vec![0; SZ];
    for i in 2..SZ {
        fac[i] = fac[i - 1].wrapping_mul(i as u64) % MOD;
    }
    ifac[SZ - 1] = mpow(fac[SZ - 1], MOD - 2, MOD);
    for i in (0..SZ - 1).rev() {
        ifac[i] = ifac[i + 1].wrapping_mul((i as u64 + 1)) % MOD;
    }
    let mut prime = vec![0; SZ];
    for i in 2..SZ {
        prime[i] = i as i32;
    }
    for i in 2..=((SZ as f64).sqrt() as usize) {
        if prime[i] != i as i32 {
            continue;
        }
        for j in (i * i..SZ).step_by(i) {
            if prime[j] == j as i32 {
                prime[j] = i as i32;
            }
        }
    }
    (fac, ifac, prime)
}

fn ncr(n: usize, r: usize, fac: &Vec<u64>, ifac: &Vec<u64>) -> u64 {
    if n <= 0 || r < 0 {
        return 0;
    }
    if n < r {
        return 0;
    }
    (fac[n] * ifac[r] % MOD) * ifac[n - r] % MOD
}

fn gcd(mut a: u64, mut b: u64) -> u64 {
    while b > 0 {
        let t = b;
        b = a % b;
        a = t;
    }
    a
}

fn lcm(a: u64, b: u64) -> u64 {
    (a / gcd(a, b)) * b
}

