func digits(_ n: Int64) -> Int64 {
    var k: Int64 = 0
    var nn = n
    while nn != 0 {
        k += 1
        nn /= 10
    }
    return k
}

func isprime(_ n: Int64) -> Bool {
    if n == 1 { return false }
    if n == 2 { return true }
    if n % 2 == 0 { return false }
    var i = Int64(3)
    while i * i <= n {
        if n % i == 0 { return false }
        i += 2
    }
    return true
}

func power(_ x: Int64, _ y: Int64, _ MOD: Int64) -> Int64 {
    var ans: Int64 = 1
    var xx = x % MOD
    var yy = y
    while yy > 0 {
        if yy % 2 == 1 {
            ans = (ans * xx) % MOD
        }
        yy /= 2
        xx = (xx * xx) % MOD
    }
    return ans
}

func sieve(_ a: inout [Bool], _ n: Int64) {
    let h = Int(sqrt(Double(n + 1)))
    for i in 2..<h {
        if !a[i] { continue }
        for j in stride(from: 2 * i, through: n, by: i) {
            a[Int(j)] = false
        }
    }
}

