let mod = 998244353

func pw(_ x: Int, _ k: Int) -> Int {
    var res = 1
    var base = x % mod
    var exp = k
    while exp > 0 {
        if exp & 1 == 1 {
            res = (res * base) % mod
        }
        base = (base * base) % mod
        exp >>= 1
    }
    return res
}

func c(_ n: Int, _ k: Int) -> Int {
    if k < 0 { return 0 }
    var res = 1
    for i in (n - k + 1)...n {
        res = (res * i) % mod
    }
    for i in 2...k {
        res = (res * pw(i, mod - 2)) % mod
    }
    return res
}

