let mod: Int64 = 998244353
let sz: Int = 2_000_001
var fac: [Int64] = Array(repeating: 1, count: sz)
var ifac: [Int64] = Array(repeating: 0, count: sz)
var prime: [Int] = Array(repeating: 0, count: sz)

func mpow(_ a: Int64, _ b: Int64 = mod - 2, _ m: Int64 = mod) -> Int64 {
    var res: Int64 = 1
    var a = a % m
    assert(b >= 0)
    var b = b
    while b > 0 {
        if b & 1 == 1 {
            res = (res * a) % m
        }
        a = (a * a) % m
        b >>= 1
    }
    return res
}

func init() {
    for i in 2..<sz {
        fac[i] = (fac[i - 1] * Int64(i)) % mod
    }
    ifac[sz - 1] = mpow(fac[sz - 1])
    for i in stride(from: sz - 2, through: 0, by: -1) {
        ifac[i] = (ifac[i + 1] * Int64(i + 1)) % mod
    }
    for i in 2..<sz {
        prime[i] = i
    }
    for i in stride(from: 2, through: Int(sqrt(Double(sz))), by: 1) {
        if prime[i] != i { continue }
        for j in stride(from: i * i, to: sz, by: i) {
            if prime[j] == j { prime[j] = i }
        }
    }
}

func nCr(_ n: Int64, _ r: Int64) -> Int64 {
    if n <= 0 || r < 0 { return 0 }
    if n < r { return 0 }
    return (fac[Int(n)] * ((ifac[Int(r)] * ifac[Int(n - r)]) % mod)) % mod
}

func gcd(_ a: Int64, _ b: Int64) -> Int64 {
    return b == 0 ? a : gcd(b, a % b)
}

func lcm(_ a: Int64, _ b: Int64) -> Int64 {
    return (a / gcd(a, b)) * b
}

