from collections import deque

class FastIOAdapter:
    def __init__(self):
        self.reader = sys.stdin
        self.writer = sys.stdout
        self.buffer = []

    def next(self):
        while not self.buffer:
            try:
                line = self.reader.readline().strip()
                if not line:
                    break
                self.buffer.extend(line.split())
            except EOFError:
                break
        return self.buffer.pop(0) if self.buffer else None

    def next_int(self):
        return int(self.next())

    def read_array(self, n):
        return [self.next_int() for _ in range(n)]

def solve(io):
    n = io.next_int()
    m = io.next_int()
    a = [list(io.next()) for _ in range(n)]
    lengths = [[0] * m for _ in range(n)]
    indices = [[0] * m for _ in range(n)]
    x, y, max_length = 0, 0, 0

    for i in range(n):
        for j in range(m):
            if lengths[i][j] == 0:
                stack = deque()
                stack.append((i, j))
                lengths[i][j] = -1
                indices[i][j] = 0
                length = 1
                cycle = 0
                cyc_x, cyc_y = -1, -1

                while True:
                    xc, yc = stack[-1]
                    if a[xc][yc] == 'U':
                        xc -= 1
                    elif a[xc][yc] == 'D':
                        xc += 1
                    elif a[xc][yc] == 'L':
                        yc -= 1
                    else:
                        yc += 1

                    if xc < 0 or xc >= n or yc < 0 or yc >= m:
                        break
                    elif lengths[xc][yc] < 0:
                        cycle -= indices[xc][yc] - 1
                        length = cycle + 1
                        cyc_x, cyc_y = xc, yc
                        break
                    elif lengths[xc][yc] > 0:
                        length = lengths[xc][yc] + 1
                        break
                    else:
                        lengths[xc][yc] = -1
                        indices[xc][yc] = cycle + 1
                        stack.append((xc, yc))
                        cycle += 1

                is_cycle = cyc_x != -1
                length = cycle if is_cycle else length

                while stack:
                    xc, yc = stack.pop()
                    lengths[xc][yc] = length
                    if is_cycle and (xc == cyc_x and yc == cyc_y):
                        is_cycle = False
                        length = length
                    else:
                        length += 1

                if max_length < lengths[i][j]:
                    max_length = lengths[i][j]
                    x, y = i + 1, j + 1

    io.writer.write(f"{x} {y} {max_length}\n")

