class D:
    mod = 998244353

    @staticmethod
    def bin_pow(a, b):
        res = 1
        while b > 0:
            a = a % D.mod
            if b & 1 == 1:
                res = (res * a) % D.mod
            b >>= 1
            a = (a * a) % D.mod
        return res

    @staticmethod
    def mod_inverse(a):
        return D.bin_pow(a, D.mod - 2)

    @staticmethod
    def mul(a, b):
        return (a * b) % D.mod

    @staticmethod
    def nCr(n, r):
        res = D.mul(D.fact[n], D.inv_fact[r])
        res = D.mul(res, D.inv_fact[n - r])
        return res

