        self.index += 1
        return token

    def nextInt(self):
        return int(self.next())

    def nextLong(self):
        return int(self.next())  # Python's int can handle longs, so we use int here.

    def nextDouble(self):
        return float(self.next())

    def nextLine(self):
        if self.index >= len(self.buffer):
            raise EOFError("No more lines")
        line = ' '.join(self.buffer[self.index:])
        self.index = len(self.buffer)
        return line

    def readInt(self, size):
        return [self.nextInt() for _ in range(size)]

    def readLong(self, size):
        return [self.nextLong() for _ in range(size)]

    def read2dArray(self, rows, cols):
