class Main {
    private out: NodeJS.WritableStream = process.stdout;
    private in: readline.Interface = readline.createInterface({
        input: process.stdin,
        output: process.stdout
    });
    private tok: string[] = [];

    async next(): Promise<string> {
        if (this.tok.length === 0) {
            const line = await new Promise<string>((resolve) => this.in.on('line', resolve));
            this.tok = line.split(/\s+/);
        }
        return this.tok.shift()!;
    }

    async ni(): Promise<number> {
        return parseInt(await this.next(), 10);
    }

    async nl(): Promise<number> {
        return parseInt(await this.next(), 10);
    }

    async na(n: number): Promise<number[]> {
        const A: number[] = [];
        for (let i = 0; i < n; i++) {
            A[i] = await this.ni();
        }
        return A;
    }

    private mod: number = 998244353;

    async solve(): Promise<void> {
        const tc = await this.ni();
        for (let t = 0; t < tc; t++) {
            const n = await this.ni();
            const A = await this.na(n);

            const D: number[][] = Array.from({ length: n + 1 }, () => [0, 0, 0]);

            for (let i = n - 1; i >= 0; i--) {
                const u = A[i];
                let zero = 1 + D[u][0];
                if (u + 1 <= n) zero += D[u + 1][0];
                if (u + 2 <= n) zero += D[u + 2][1];
                let one = 1 + D[u][1];
                if (u > 1) one += D[u - 2][2];
                let two = 1 + D[u][2];
                if (u + 2 <= n) two += D[u + 2][1];

                D[u][0] = (D[u][0] + zero) % this.mod;
                D[u][1] = (D[u][1] + one) % this.mod;
                D[u][2] = (D[u][2] + two) % this.mod;
            }

            const ans = (D[0][0] + D[1][1]) % this.mod;
            this.out.write(`${ans}\n`);
        }
        this.in.close();
    }

    dc(a: number): number {
        let r = 0;
        while (a > 0) {
            r++;
            a = Math.floor(a / 10);
        }
        return r;
    }

    gcd(a: number, b: number): number {
        return b === 0 ? a : this.gcd(b, a % b);
    }

    mp(a: number, p: number): number {
        let r = 1;
        while (p > 0) {
            if ((p & 1) === 1) r = (r * a) % this.mod;
            p >>= 1;
            a = (a * a) % this.mod;
        }
        return r;
    }

    public static async main(): Promise<void> {
        const mainInstance = new Main();
        await mainInstance.solve();
    }
}

