class FastIOAdapter implements AutoCloseable {
    private rl: readline.Interface;
    private inputBuffer: string[] = [];
    private outputBuffer: string[] = [];

    constructor() {
        this.rl = readline.createInterface({
            input: process.stdin,
            output: process.stdout
        });
        this.rl.on('line', (line) => this.inputBuffer.push(line));
    }

    next(): string {
        if (this.inputBuffer.length === 0) throw new Error("No more input");
        return this.inputBuffer.shift()!;
    }

    nextLine(): string {
        return this.next();
    }

    nextInt(): number {
        return parseInt(this.next(), 10);
    }

    readArray(n: number): number[] {
        const arr: number[] = [];
        for (let i = 0; i < n; i++) arr.push(this.nextInt());
        return arr;
    }

    readArrayLong(n: number): bigint[] {
        const arr: bigint[] = [];
        for (let i = 0; i < n; i++) arr.push(BigInt(this.next()));
        return arr;
    }

    nextLong(): bigint {
        return BigInt(this.next());
    }

    print(...args: any[]): void {
        this.outputBuffer.push(args.join(' '));
    }

    println(...args: any[]): void {
        this.print(...args);
        this.outputBuffer.push('\n');
    }

    async close(): Promise<void> {
        await new Promise(resolve => this.rl.close(() => resolve()));
        process.stdout.write(this.outputBuffer.join(''));
    }
}

function solve(io: FastIOAdapter): void {
    const n = io.nextInt();
    const m = io.nextInt();
    const a: string[][] = [];
    for (let i = 0; i < n; i++) {
        a[i] = io.next().split('');
    }
    const lengths: number[][] = Array.from({ length: n }, () => Array(m).fill(0));
    const indices: number[][] = Array.from({ length: n }, () => Array(m).fill(0));
    let x = 0, y = 0;
    let max = 0;

    for (let i = 0; i < n; i++) {
        for (let j = 0; j < m; j++) {
            if (lengths[i][j] === 0) { // we did not check this
                const stack: [number, number][] = [];
                stack.push([i, j]);
                lengths[i][j] = -1; // we were here
                indices[i][j] = 0;
                let length = 1;
                let cycle = 0;
                let cycX = -1, cycY = -1;

                while (true) {
                    const [xc, yc] = stack[stack.length - 1];
                    if (a[xc][yc] === 'U') {
                        xc--;
                    } else if (a[xc][yc] === 'D') {
                        xc++;
                    } else if (a[xc][yc] === 'L') {
                        yc--;
                    } else yc++;

                    if (xc < 0 || xc >= n || yc < 0 || yc >= m) {
                        break;
                    } else if (lengths[xc][yc] < 0) {
                        cycle -= indices[xc][yc] - 1;
                        length = cycle + 1;
                        cycX = xc;
                        cycY = yc;
                        break;
                    } else if (lengths[xc][yc] > 0) {
                        length = lengths[xc][yc] + 1;
                        break;
                    } else {
                        lengths[xc][yc] = -1;
                        indices[xc][yc] = ++cycle;
                        stack.push([xc, yc]);
                    }
                }

                const isCycle = cycX !== -1;
                let len = isCycle ? cycle : length;

                while (stack.length > 0) {
                    const [xyx, xyY] = stack.pop()!;
                    lengths[xyx][xyY] = len;
                    if (isCycle) {
                        if (xyx === cycX && xyY === cycY) {
                            isCycle = false;
                            len = length;
                        }
                    } else len++;
                }

                if (max < lengths[i][j]) {
                    max = lengths[i][j];
                    x = i + 1;
                    y = j + 1;
                }
            }
        }
    }
    io.println(x, y, max);
}

