const MOD: number = 998244353;

class D implements Constant {
    static br: ReadableStreamDefaultReader<Uint8Array> | null = null;
    static pw: WritableStreamDefaultWriter<Uint8Array> | null = null;

    static fact: number[] = [];
    static invFact: number[] = [];

    static async binPow(a: number, b: number): Promise<number> {
        let res = 1;
        while (b > 0) {
            a = a % MOD;
            if ((b & 1) === 1) {
                res = (res * a) % MOD;
            }
            b >>= 1;
            a = (a * a) % MOD;
        }
        return res;
    }

    static async modInverse(a: number): Promise<number> {
        return await this.binPow(a, MOD - 2);
    }

    static mul(a: number, b: number): number {
        return (a * b) % MOD;
    }

    static async nCr(n: number, r: number): Promise<number> {
        let res = this.mul(this.fact[n], this.invFact[r]);
        res = this.mul(res, this.invFact[n - r]);
        return res;
    }

    public static async main(): Promise<void> {
        if (!this.br) {
            this.br = process.stdin.readable.getReader();
        }
        if (!this.pw) {
            const writableStream = new WritableStream<Uint8Array>({
                write(chunk) {
                    process.stdout.write(chunk);
                },
            });
            this.pw = writableStream.getWriter();
        }

        const n = parseInt((await this.br!.read()).value!.toString(), 10);
        const ls: string[] = [];
        let full = false;
        let black = 0, white = 0;

        for (let i = 0; i < n; ++i) {
            const line = (await this.br!.read()).value!.toString();
            ls.push(line);
            if (line.charAt(0) === 'W') white++;
            if (line.charAt(0) === 'B') black++;
            if (line.charAt(1) === 'W') white++;
            if (line.charAt(1) === 'B') black++;
            if (line.charAt(0) !== '?' && line.charAt(0) === line.charAt(1)) {
                full = true;
            }
        }

        if (black > n || white > n) {
            await this.pw!.write(new TextEncoder().encode("0\n"));
            return;
        }

        this.fact[0] = 1;
        this.invFact[0] = 1;
        for (let i = 1; i <= 2 * n; ++i) {
            this.fact[i] = this.mul(this.fact[i - 1], i);
            this.invFact[i] = await this.modInverse(this.fact[i]);
        }

        const empty = 2 * n - black - white;
        let ans = await this.nCr(empty, n - black);

        if (full) {
            await this.pw!.write(new TextEncoder().encode(`${ans}\n`));
            return;
        }

        let invalid = 1;
        let WB = true, BW = true;

        for (let i = 0; i < n; ++i) {
            if (ls[i].charAt(0) === '?' && ls[i].charAt(1) === '?') {
                invalid = this.mul(invalid, 2);
            }
            if (ls[i].charAt(0) === 'B' || ls[i].charAt(1) === 'W') {
                WB = false;
            }
            if (ls[i].charAt(0) === 'W' || ls[i].charAt(1) === 'B') {
                BW = false;
            }
        }

        if (WB) invalid--;
        if (BW) invalid--;

        ans -= invalid;

        await this.pw!.write(new TextEncoder().encode(`${ans}\n`));
    }
}

