class FastReader {
    private br: ReadableStreamDefaultReader<Uint8Array>;
    private decoder: TextDecoder;
    private buffer: string;

    constructor() {
        this.br = process.stdin.webidlConverter().getReader();
        this.decoder = new TextDecoder('utf-8');
        this.buffer = '';
    }

    async next(): Promise<string> {
        if (this.buffer === '') {
            const { done, value } = await this.br.read();
            if (done) throw new Error('End of input');
            this.buffer = this.decoder.decode(value);
        }
        const index = this.buffer.indexOf(' ');
        if (index !== -1) {
            const token = this.buffer.substring(0, index);
            this.buffer = this.buffer.substring(index + 1);
            return token;
        } else {
            const { done, value } = await this.br.read();
            if (done) throw new Error('End of input');
            this.buffer += this.decoder.decode(value);
            return this.next();
        }
    }

    async nextInt(): Promise<number> {
        return parseInt(await this.next(), 10);
    }

    async nextLong(): Promise<number> {
        return parseFloat(await this.next());
    }

    async nextDouble(): Promise<number> {
        return parseFloat(await this.next());
    }

    async nextLine(): Promise<string> {
        if (this.buffer.includes('\n')) {
            const index = this.buffer.indexOf('\n');
            const line = this.buffer.substring(0, index);
            this.buffer = this.buffer.substring(index + 1);
            return line;
        } else {
            let line = this.buffer;
            let { done, value } = await this.br.read();
            while (!done && !line.endsWith('\n')) {
                line += this.decoder.decode(value);
                ({ done, value } = await this.br.read());
            }
            if (done && !line.endsWith('\n')) throw new Error('End of input');
            this.buffer = '';
            return line.trimEnd();
        }
    }

    async readInt(size: number): Promise<number[]> {
        const arr: number[] = [];
        for (let i = 0; i < size; i++) {
            arr.push(await this.nextInt());
        }
        return arr;
    }

    async readLong(size: number): Promise<number[]> {
        const arr: number[] = [];
        for (let i = 0; i < size; i++) {
            arr.push(await this.nextLong());
        }
        return arr;
    }

    async read2dArray(rows: number, cols: number): Promise<number[][]> {
        const arr: number[][] = [];
        for (let i = 0; i < rows; i++) {
            const row: number[] = [];
            for (let j = 0; j < cols; j++) {
                row.push(await this.nextInt());
            }
            arr.push(row);
        }
        return arr;
    }
}

