class F {
    private static out: NodeJS.WritableStream = process.stdout;
    private static sc: MyScanner = new MyScanner();
    private static N: number = F.sc.nextInt();

    public static main() {
        while (F.N-- > 0) {
            F.solve();
        }
        F.out.end();
    }

    public static solve() {
        const n: number = F.sc.nextInt();
        const m: number = F.sc.nextInt();
        const k: number = F.sc.nextInt();

        const b_t: number = n % m;
        const b_p: number = Math.floor(n / m) + 1;
        let next_b: number = 1;
        let next_s: number = 1;

        if (b_t === 0) {
            for (let i = 0; i < k; i++) {
                for (let j = 0; j < m; j++) {
                    F.out.write(`${Math.floor(n / m)} `);
                    for (let play = 0; play < Math.floor(n / m); play++) {
                        F.out.write(`${next_b} `);
                        next_b = next_b === n ? 1 : next_b + 1;
                    }
                    F.out.write('\n');
                }
            }
        } else {
            for (let i = 0; i < k; i++) {
                for (let j = 0; j < b_t; j++) {
                    F.out.write(`${b_p} `);
                    for (let play = 0; play < b_p; play++) {
                        F.out.write(`${next_b} `);
                        next_b = next_b === n ? 1 : next_b + 1;
                    }
                    F.out.write('\n');
                }
                next_s = next_b;
                for (let j = 0; j < m - b_t; j++) {
                    F.out.write(`${Math.floor(n / m)} `);
                    for (let play = 0; play < b_p - 1; play++) {
                        F.out.write(`${next_s} `);
                        next_s = next_s === n ? 1 : next_s + 1;
                    }
                    F.out.write('\n');
                }
            }
        }
        F.out.write('\n');
    }
}

