            input: process.stdin,
            output: process.stdout
        });

        let t: number;
        rl.question('', (input) => {
            t = parseInt(input.trim());
            this.processCases(t, rl);
        });
    }

    private static processCases(t: number, rl: readline.Interface) {
        if (t <= 0) {
            rl.close();
            return;
        }

        rl.question('', (input) => {
            const [c, d] = input.trim().split(' ').map(Number);
            let result: number;

            if (c === d && c !== 0) {
                result = 1;
            } else if (c === d) {
                result = 0;
            } else {
                let k = c - d;
                if (k < 0) {
                    k *= -1;
                }
                if (k % 2 !== 0) {
                    result = -1;
                } else {
                    result = 2;
                }
            }

            console.log(result);
            this.processCases(t - 1, rl);
        });
    }
}

