import * as readline from 'readline';

class FastScanner {
    private rl: readline.Interface;
    private buffer: string[] = [];
    private currentIndex: number = 0;

    constructor() {
        this.rl = readline.createInterface({
            input: process.stdin,
            output: process.stdout,
            terminal: false
        });

        this.rl.on('line', (line) => {
            this.buffer.push(...line.split(/\s+/));
        });
    }

    next(): string {
        if (this.currentIndex >= this.buffer.length) {
            throw new Error("No more tokens");
        }
        return this.buffer[this.currentIndex++];
    }

    nextInt(): number {
        return parseInt(this.next(), 10);
    }

    readArray(n: number): number[] {
        const array: number[] = [];
        for (let i = 0; i < n; i++) {
            array.push(this.nextInt());
        }
        return array;
    }

    nextLong(): number {
        return parseInt(this.next(), 10);
    }
}

class Main {
    private static out: string[] = [];

    public static main() {
        const fs = new FastScanner();

        const n = fs.nextInt();
        const m = fs.nextInt();
        const a: string[][] = [];
        for (let i = 0; i < n; i++) {
            a[i] = fs.next().split('');
        }

        const c: number[] = new Array(m).fill(0);
        for (let i = 0; i < m; i++) {
            let f = 0;
            for (let j = 0; j < n; j++) {
                if (i === 0 || j === 0) continue;
                if (a[j - 1][i] === 'X' && a[j][i - 1] === 'X') {
                    f = 1;
                    break;
                }
            }
            if (f === 1) c[i] = 1;
        }

        const dp: number[] = new Array(m).fill(0);
        for (let i = 1; i < m; i++) {
            if (c[i] === 1) dp[i] = dp[i - 1] + 1;
            else dp[i] = dp[i - 1];
        }

        const q = fs.nextInt();
        for (let i = 0; i < q; i++) {
            const x1 = fs.nextInt() - 1;
            const x2 = fs.nextInt() - 1;
            if (x1 === x2) Main.out.push("YES\n");
            else if (dp[x1] < dp[x2]) Main.out.push("NO\n");
            else Main.out.push("YES\n");
        }

        process.stdout.write(Main.out.join(''));
    }
}

Main.main();

