type FastIOAdapter struct {
	scanner *bufio.Scanner
	writer  *bufio.Writer
}

func NewFastIOAdapter() *FastIOAdapter {
	return &FastIOAdapter{
		scanner: bufio.NewScanner(os.Stdin),
		writer:  bufio.NewWriter(os.Stdout),
	}
}

func (fio *FastIOAdapter) next() string {
	if !fio.scanner.Scan() {
		panic("No more tokens")
	}
	return fio.scanner.Text()
}

func (fio *FastIOAdapter) nextInt() int {
	n, err := strconv.Atoi(fio.next())
	if err != nil {
		panic(err)
	}
	return n
}

func (fio *FastIOAdapter) nextLine() string {
	if !fio.scanner.Scan() {
		panic("No more lines")
	}
	return fio.scanner.Text()
}

func (fio *FastIOAdapter) print(a ...interface{}) {
	fmt.Fprint(fio.writer, a...)
}

func (fio *FastIOAdapter) println(a ...interface{}) {
	fmt.Fprintln(fio.writer, a...)
}

func (fio *FastIOAdapter) flush() {
	fio.writer.Flush()
}

func solve(io *FastIOAdapter) {
	n := io.nextInt()
	m := io.nextInt()
	a := make([][]rune, n)
	for i := range a {
		line := io.nextLine()
		a[i] = []rune(line)
	}
	lengths := make([][]int, n)
	indices := make([][]int, n)
	for i := range lengths {
		lengths[i] = make([]int, m)
		indices[i] = make([]int, m)
	}
	var x, y, max int
	for i := 0; i < n; i++ {
		for j := 0; j < m; j++ {
			if lengths[i][j] == 0 {
				stack := [][]int{{i, j}}
				lengths[i][j] = -1
				indices[i][j] = 0
				var length, cycle int
				cycX, cycY := -1, -1
				for {
					xy := stack[len(stack)-1]
					xc, yc := xy[0], xy[1]
					switch a[xc][yc] {
					case 'U':
						xc--
					case 'D':
						xc++
					case 'L':
						yc--
					default:
						yc++
					}
					if xc < 0 || xc >= n || yc < 0 || yc >= m {
						break
					} else if lengths[xc][yc] < 0 {
						cycle -= indices[xc][yc] - 1
						length = cycle + 1
						cycX, cycY = xc, yc
						break
					} else if lengths[xc][yc] > 0 {
						length = lengths[xc][yc] + 1
						break
					} else {
						lengths[xc][yc] = -1
						indices[xc][yc] = cycle + 1
						stack = append(stack, []int{xc, yc})
						cycle++
					}
				}
				isCycle := cycX != -1
				var len int
				if isCycle {
					len = cycle
				} else {
					len = length
				}
				for len > 0 && len <= len(stack) {
					xy := stack[len-1]
					lengths[xy[0]][xy[1]] = len
					if isCycle {
						if xy[0] == cycX && xy[1] == cycY {
							isCycle = false
							len = length
						}
					} else {
						len++
					}
					stack = stack[:len-1]
				}
				if max < lengths[i][j] {
					max = lengths[i][j]
					x = i + 1
					y = j + 1
				}
			}
		}
	}
	io.println(x, y, max)
}

func main() {
	io := NewFastIOAdapter()
	defer io.flush()

	count := io.nextInt()
	for count > 0 {
		solve(io)
		count--
	}
}

