func marker1(n int) int {
	count := 1
	for i := 1; i <= n; i++ {
		if !visM[i] {
			dfs1(i, count)
			count++
		}
	}
	return count - 1
}

func marker2(n int) int {
	count := 1
	for i := 1; i <= n; i++ {
		if !visD[i] {
			dfs2(i, count)
			count++
		}
	}
	return count - 1
}

func main() {
