const mod = 998244353

var br *bufio.Reader
var pw *bufio.Writer

func init() {
	br = bufio.NewReader(os.Stdin)
	pw = bufio.NewWriter(os.Stdout)
	defer pw.Flush()
}

var fact []int64
var invFact []int64

func binPow(a, b int64) int64 {
	res := int64(1)
	for b > 0 {
		a = a % mod
		if b&1 == 1 {
			res = (res * a) % mod
		}
		b >>= 1
		a = (a * a) % mod
	}
	return res
}

func modInverse(a int64) int64 {
	return binPow(a, mod-2)
}

func mul(a, b int64) int64 {
	return (a * b) % mod
}

func nCr(n, r int) int64 {
	res := mul(fact[n], invFact[r])
	res = mul(res, invFact[n-r])
	return res
}

func main() {
	var n int
	fmt.Fscanf(br, "%d\n", &n)
	ls := make([]string, n)
	full := false
	black, white := 0, 0

	for i := 0; i < n; i++ {
		fmt.Fscanf(br, "%s\n", &ls[i])
		if ls[i][0] == 'W' {
			white++
		}
		if ls[i][0] == 'B' {
			black++
		}
		if ls[i][1] == 'W' {
			white++
		}
		if ls[i][1] == 'B' {
			black++
		}
		if ls[i][0] != '?' && ls[i][0] == ls[i][1] {
			full = true
		}
	}

	if black > n || white > n {
		fmt.Fprintln(pw, 0)
		return
	}

	fact = make([]int64, 2*n+1)
	invFact = make([]int64, 2*n+1)
	fact[0] = 1
	invFact[0] = 1

	for i := 1; i <= 2*n; i++ {
		fact[i] = mul(fact[i-1], int64(i))
		invFact[i] = modInverse(fact[i])
	}

	empty := 2*n - black - white
	ans := nCr(empty, n-black)

	if full {
		fmt.Fprintln(pw, ans)
		return
	}

	invalid := int64(1)
	WB, BW := true, true

	for i := 0; i < n; i++ {
		if ls[i][0] == '?' && ls[i][1] == '?' {
			invalid = mul(invalid, 2)
		}
		if ls[i][0] == 'B' || ls[i][1] == 'W' {
			WB = false
		}
		if ls[i][0] == 'W' || ls[i][1] == 'B' {
			BW = false
		}
	}

	if WB {
		invalid--
	}
	if BW {
		invalid--
	}

	ans -= invalid
	fmt.Fprintln(pw, ans)
}

