func gcd(a, b int) int {
	if a > b {
		a, b = b, a
	}
	if a == 0 {
		return b
	}
	return gcd(b%a, a)
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	line, _ := reader.ReadString('\n')
	N, _ := strconv.Atoi(strings.TrimSpace(line))

	arr := make([]Point, N)
	for i := 0; i < N; i++ {
		line, _ = reader.ReadString('\n')
		parts := strings.Fields(line)
		x, _ := strconv.Atoi(parts[0])
		y, _ := strconv.Atoi(parts[1])
		x /= 2
		y /= 2
		arr[i] = Point{x: x, y: y}
	}

	var res int64
	for centerr := 0; centerr < N; centerr++ {
		c := arr[centerr]
		freq := make([][][]int, 2)
		for i := range freq {
			freq[i] = make([][]int, 2)
			for j := range freq[i] {
				freq[i][j] = make([]int, 2)
			}
		}

		for i := centerr + 1; i < N; i++ {
			if i != centerr {
				p := arr[i]
				t1 := 1
				if p.x%2 != c.x%2 {
					t1 = 0
				}
				if p.y%2 != c.y%2 {
					t1 = 0
				}
				t2 := p.x & 1
				t3 := p.y & 1
				freq[t1^1][t2][t3]++
			}
		}

		var temp int64
		temp += int64(freq[0][0][0]) * (int64(freq[1][0][1]) + int64(freq[1][1][0]) + int64(freq[1][1][1]))
		temp += int64(freq[0][0][0]) * (int64(freq[0][0][0])-1) / 2
		temp += int64(freq[1][0][0]) * (int64(freq[1][0][0])-1) / 2
		temp += int64(freq[0][0][1]) * (int64(freq[1][0][0]) + int64(freq[1][0][1]) + int64(freq[1][1][1]))
		temp += int64(freq[0][0][1]) * (int64(freq[0][0][1])-1) / 2
		temp += int64(freq[1][0][1]) * (int64(freq[1][0][1])-1) / 2
		temp += int64(freq[0][1][0]) * (int64(freq[1][0][0]) + int64(freq[1][0][1]) + int64(freq[1][1][1]))
		temp += int64(freq[0][1][0]) * (int64(freq[0][1][0])-1) / 2
		temp += int64(freq[1][1][0]) * (int64(freq[1][1][0])-1) / 2
		temp += int64(freq[0][1][1]) * (int64(freq[1][0][0]) + int64(freq[1][0][1]) + int64(freq[1][1][0]))
		temp += int64(freq[0][1][1]) * (int64(freq[0][1][1])-1) / 2
		temp += int64(freq[1][1][1]) * (int64(freq[1][1][1])-1) / 2

		res += temp
	}

	fmt.Println(res)
}

