var N int
var sc *Scanner
var out = bufio.NewWriter(os.Stdout)

func main() {
	sc = NewScanner(bufio.NewReader(os.Stdin))
	N = sc.nextInt()
	for N > 0 {
		solve()
		N--
	}
	out.Flush()
}

func solve() {
	n := sc.nextInt()
	m := sc.nextInt()
	k := sc.nextInt()

	b_t := n % m
	b_p := n / m + 1
	next_b := 1
	next_s := 1

	if b_t == 0 {
		for i := 0; i < k; i++ {
			for j := 0; j < m; j++ {
				fmt.Fprintf(out, "%d ", n/m)
				for play := 0; play < n/m; play++ {
					fmt.Fprintf(out, "%d ", next_b)
					if next_b == n {
						next_b = 1
					} else {
						next_b++
					}
				}
				fmt.Fprintln(out)
			}
		}
	} else {
		for i := 0; i < k; i++ {
			for j := 0; j < b_t; j++ {
				fmt.Fprintf(out, "%d ", n/m+1)
				for play := 0; play < b_p; play++ {
					fmt.Fprintf(out, "%d ", next_b)
					if next_b == n {
						next_b = 1
					} else {
						next_b++
					}
				}
				fmt.Fprintln(out)
			}
			next_s = next_b
			for j := 0; j < m-b_t; j++ {
				fmt.Fprintf(out, "%d ", n/m)
				for play := 0; play < b_p-1; play++ {
					fmt.Fprintf(out, "%d ", next_s)
					if next_s == n {
						next_s = 1
					} else {
						next_s++
					}
				}
				fmt.Fprintln(out)
			}
		}
	}
	fmt.Fprintln(out)
}

type Scanner struct {
	scanner *bufio.Scanner
	buffer  []string
}

func NewScanner(reader *bufio.Reader) *Scanner {
	return &Scanner{
		scanner: bufio.NewScanner(reader),
		buffer:  make([]string, 0),
	}
}

func (s *Scanner) next() string {
	if len(s.buffer) == 0 {
		s.scanner.Scan()
		s.buffer = strings.Fields(s.scanner.Text())
	}
	token := s.buffer[0]
	s.buffer = s.buffer[1:]
	return token
}

func (s *Scanner) nextInt() int {
	i, _ := strconv.Atoi(s.next())
	return i
}

func (s *Scanner) nextLong() int64 {
	l, _ := strconv.ParseInt(s.next(), 10, 64)
	return l
}

func (s *Scanner) nextDouble() float64 {
	f, _ := strconv.ParseFloat(s.next(), 64)
