func (fs *FastScanner) next() string {
	for fs.st.Len() == 0 {
		line, _ := fs.br.ReadString('\n')
		fs.st.WriteString(strings.TrimSpace(line))
	}
	token, _ := fs.st.ReadRune()
	if token == ' ' || token == '\t' {
		return fs.next()
	}
	start := fs.st.Len() - 1
	for {
		token, _ = fs.st.ReadRune()
		if token == ' ' || token == '\t' || token == '\n' {
			break
		}
	}
	fs.st.Truncate(start)
	return fs.st.String()
}

