class Program
{
    const int INF = int.MaxValue / 2;

    static void Main(string[] args)
    {
        using (var reader = new StreamReader(Console.OpenStandardInput()))
        using (var writer = new StreamWriter(Console.OpenStandardOutput()))
        {
            var st = new StringTokenizer(reader.ReadLine());
            int T = int.Parse(st.NextToken());
            while (T-- > 0)
            {
                st = new StringTokenizer(reader.ReadLine());
                int N = int.Parse(st.NextToken());
                int D = int.Parse(st.NextToken());
                int[] arr = ReadArr(N, reader, st);
                int[] dist = new int[N];
                Array.Fill(dist, INF);
                var q = new Queue<int>();
                for (int i = 0; i < N; i++)
                {
                    if (arr[i] == 0)
                    {
                        dist[i] = 0;
                        q.Enqueue(i);
                    }
                }
                while (q.Count > 0)
                {
                    int curr = q.Dequeue();
                    int next = (curr + D) % N;
                    if (dist[next] == INF)
                    {
                        dist[next] = dist[curr] + 1;
                        q.Enqueue(next);
                    }
                }
                int res = 0;
                foreach (int x in dist)
                {
                    res = Math.Max(res, x);
                }
                if (res == INF)
                {
                    res = -1;
                }
                writer.WriteLine(res);
            }
        }
    }

    static int[] ReadArr(int N, StreamReader reader, StringTokenizer st)
    {
        int[] arr = new int[N];
        st = new StringTokenizer(reader.ReadLine());
        for (int i = 0; i < N; i++)
        {
            arr[i] = st.NextToken()[0] - '0';
        }
        return arr;
    }
}

class StringTokenizer
{
    private readonly string _input;
    private int _index;

    public StringTokenizer(string input)
    {
        _input = input;
        _index = 0;
    }

    public string NextToken()
    {
        while (_index < _input.Length && char.IsWhiteSpace(_input[_index]))
        {
            _index++;
        }
        if (_index >= _input.Length)
        {
            return null;
        }
        int start = _index;
        while (_index < _input.Length && !char.IsWhiteSpace(_input[_index]))
        {
            _index++;
        }
        return _input.Substring(start, _index - start);
    }
}

