    long[] aa, tmax, tmin; int n;
    void Build()
    {
        tmax = new long[n * 2];
        tmin = new long[n * 2];
        for (int i = 0; i < n; i++)
            tmax[n + i] = tmin[n + i] = aa[i];
        for (int i = n - 1; i > 0; i--)
        {
            tmax[i] = Math.Max(tmax[i << 1], tmax[i << 1 | 1]);
            tmin[i] = Math.Min(tmin[i << 1], tmin[i << 1 | 1]);
        }
    }
    long QMax(int l, int r)
    {
        long ans = -INF;
        for (l += n, r += n; l <= r; l >>= 1, r >>= 1)
        {
            if ((l & 1) == 1)
                ans = Math.Max(ans, tmax[l++]);
            if ((r & 1) == 0)
                ans = Math.Max(ans, tmax[r--]);
        }
        return ans;
    }
    long QMin(int l, int r)
    {
        long ans = INF;
        for (l += n, r += n; l <= r; l >>= 1, r >>= 1)
        {
            if ((l & 1) == 1)
                ans = Math.Min(ans, tmin[l++]);
            if ((r & 1) == 0)
                ans = Math.Min(ans, tmin[r--]);
        }
        return ans;
    }
    void Main()
    {
        n = int.Parse(sc.ReadLine());
        int q = int.Parse(sc.ReadLine());
        aa = new long[n];
        for (int i = 0; i < n; i++)
            aa[i] = -int.Parse(sc.ReadWord());
        for (int i = 0; i < n; i++)
            aa[i] += int.Parse(sc.ReadWord());
        for (int i = 1; i < n; i++)
            aa[i] += aa[i - 1];
        Build();
        while (q-- > 0)
        {
            int l = int.Parse(sc.ReadLine()) - 1;
            int r = int.Parse(sc.ReadLine()) - 1;
            long a = l == 0 ? 0 : aa[l - 1];
            long b = aa[r];
            WriteLine(a != b || QMin(l, r) != a ? -1 : QMax(l, r) - a);
        }
    }
