                            cycle -= indices[xc, yc] - 1;
                            length = cycle + 1;
                            cycX = xc;
                            cycY = yc;
                            break;
                        }
                        else if (lengths[xc, yc] > 0)
                        {
                            length = lengths[xc, yc] + 1;
                            break;
                        }
                        else
                        {
                            lengths[xc, yc] = -1;
                            indices[xc, yc] = ++cycle;
                            stack.Push(new int[] { xc, yc });
                        }
                    }
                    bool isCycle = cycX != -1;
                    int len = isCycle ? cycle : length;
                    while (stack.Count > 0)
                    {
                        int[] xy = stack.Pop();
                        lengths[xy[0], xy[1]] = len;
                        if (isCycle)
                        {
                            if (xy[0] == cycX && xy[1] == cycY)
                            {
                                isCycle = false;
                                len = length;
                            }
                        }
                        else
                        {
                            len++;
                        }
                    }
                    if (max < lengths[i, j])
                    {
                        max = lengths[i, j];
                        x = i + 1;
                        y = j + 1;
                    }
                }
            }
        }
        io.Out.WriteLine($"{x} {y} {max}");
    }

    static void Main(string[] args)
    {
        using (FastIOAdapter ioAdapter = new FastIOAdapter())
        {
            int count = 1;
            count = ioAdapter.NextInt();
            while (count-- > 0)
            {
                Solve(ioAdapter);
            }
        }
    }

    static void RuffleSort(int[] arr)
    {
        int n = arr.Length;
        Random rnd = new Random();
        for (int i = 0; i < n; ++i)
        {
            int tmp = arr[i];
            int randomPos = i + rnd.Next(n - i);
            arr[i] = arr[randomPos];
            arr[randomPos] = tmp;
        }
        Array.Sort(arr);
    }

