class Scanner
{
    private readonly System.IO.TextReader _reader;
    private string[] _currentLineTokens;
    private int _tokenIndex;

    public Scanner(System.IO.TextReader reader)
    {
        _reader = reader;
        _currentLineTokens = new string[0];
        _tokenIndex = 0;
    }

    public int NextInt()
    {
        return int.Parse(NextToken());
    }

    private string NextToken()
    {
        if (_tokenIndex >= _currentLineTokens.Length)
        {
            _currentLineTokens = _reader.ReadLine().Split(new[] { ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries);
            _tokenIndex = 0;
        }
        return _currentLineTokens[_tokenIndex++];
    }
}

