use std::io::{self, BufRead, Write};

const MOD: i64 = 998244353;

struct Main {
    out: Vec<u8>,
    in_buffer: String,
    tok_iter: std::str::SplitWhitespace<'static>,
}

impl Main {
    fn new() -> Self {
        let mut in_buffer = String::new();
        io::stdin().read_to_string(&mut in_buffer).unwrap();
        let tok_iter = in_buffer.split_whitespace();
        Main {
            out: Vec::new(),
            in_buffer,
            tok_iter,
        }
    }

    fn next(&mut self) -> &str {
        if let Some(token) = self.tok_iter.next() {
            token
        } else {
            self.in_buffer.clear();
            io::stdin().read_to_string(&mut self.in_buffer).unwrap();
            self.tok_iter = self.in_buffer.split_whitespace();
            self.tok_iter.next().unwrap()
        }
    }

    fn ni(&mut self) -> i32 {
        self.next().parse().unwrap()
    }

    fn nl(&mut self) -> i64 {
        self.next().parse().unwrap()
    }

    fn na(&mut self, n: usize) -> Vec<i32> {
        (0..n).map(|_| self.ni()).collect()
    }

    fn solve(&mut self) {
        let tc = self.ni();
        for _ in 0..tc {
            let n = self.ni() as usize;
            let a: Vec<_> = self.na(n);

            let mut d = vec![vec![0; 3]; n + 1];

            for i in (0..n).rev() {
                let u = a[i] as usize;
                let zero = 1 + d[u][0];
                if u + 1 <= n {
                    d[u][0] = (d[u][0] + zero) % MOD;
                }
                if u + 2 <= n {
                    d[u][0] = (d[u][0] + d[u + 2][1]) % MOD;
                }
                let one = 1 + d[u][1];
                if u > 1 {
                    d[u][1] = (d[u][1] + d[u - 2][2]) % MOD;
                }
                let two = 1 + d[u][2];
                if u + 2 <= n {
                    d[u][2] = (d[u][2] + d[u + 2][1]) % MOD;
                }
            }

            let ans = (d[0][0] + d[1][1]) % MOD;
            writeln!(self.out, "{}", ans).unwrap();
        }
    }

    fn dc(&mut self, mut a: i64) -> usize {
        let mut r = 0;
        while a > 0 {
            r += 1;
            a /= 10;
        }
        r
    }

    fn gcd(mut a: i32, mut b: i32) -> i32 {
        while b != 0 {
            let t = b;
            b = a % b;
            a = t;
        }
        a
    }

    fn gcd_l(mut a: i64, mut b: i64) -> i64 {
        while b != 0 {
            let t = b;
            b = a % b;
            a = t;
        }
        a
    }

    fn mp(&mut self, mut a: i64, mut p: i64) -> i64 {
        let mut r = 1;
        while p > 0 {
            if p & 1 == 1 {
                r = (r * a) % MOD;
            }
            p >>= 1;
            a = (a * a) % MOD;
        }
        r
    }
}

fn main() {
    let mut main = Main::new();
    main.solve();
    io::stdout().write_all(&main.out).unwrap();
}

