fn reverse(arr: &mut [i32], r: usize) {
    let mut l = 0;
    while l <= r / 2 {
        arr.swap(l, r - l);
        l += 1;
    }
}

fn main() {
    let mut input = FastReader::new();
    let mut output = io::stdout().lock();

    let t = input.next_int();
    for _ in 0..t {
        let n = input.next_int();
        let mut a = (0..n).map(|_| input.next_int()).collect::<Vec<i32>>();
        let mut flag = false;

        for i in 0..n {
            if (i + 1) % 2 != a[i] % 2 {
                flag = true;
                break;
            }
        }

        if flag {
            writeln!(output, "-1").unwrap();
        } else {
            let mut list = Vec::new();

            for i in (2..=n).rev().step_by(2) {
                let mut in1 = 0;
                let mut in2 = 0;

                for j in 0..n {
                    if a[j] == i {
                        in1 = j;
                    } else if a[j] == i - 1 {
                        in2 = j;
                    }
                }

                reverse(&mut a, in1);
                if in1 > in2 {
                    in2 = in1 - in2;
                }
                reverse(&mut a, in2 - 1);
                reverse(&mut a, in2 + 1);
                reverse(&mut a, 2);
                reverse(&mut a, i - 1);

                list.push(in1 + 1);
                list.push(in2);
                list.push(in2 + 2);
                list.push(3);
                list.push(i);
            }

            writeln!(output, "{}", list.len()).unwrap();
            for &item in &list {
                write!(output, "{} ", item).unwrap();
            }
            writeln!(output).unwrap();
        }
    }
}

use std::collections::VecDeque;
use std::io::{self, BufRead};

const INF: usize = std::usize::MAX / 2;

fn main() -> io::Result<()> {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    let t: usize = lines.next().unwrap()?.trim().parse()?;
    let mut output = String::new();

    for _ in 0..t {
        let line = lines.next().unwrap()?;
        let mut parts = line.split_whitespace();
        let n: usize = parts.next().unwrap().parse()?;
        let d: isize = parts.next().unwrap().parse()?;

        let arr: Vec<usize> = lines
            .next()
            .unwrap()?
            .chars()
            .map(|c| c.to_digit(10).unwrap() as usize)
            .collect();

        let mut dist = vec![INF; n];
        let mut q = VecDeque::new();

        for i in 0..n {
            if arr[i] == 0 {
                dist[i] = 0;
                q.push_back(i);
            }
        }

        while let Some(curr) = q.pop_front() {
            let next = ((curr as isize + d) % n as isize + n as isize) % n as isize;
            if dist[next as usize] == INF {
                dist[next as usize] = dist[curr] + 1;
                q.push_back(next as usize);
            }
        }

        let res = *dist.iter().max().unwrap_or(&INF);
        let result = if res == INF { "-1\n" } else { format!("{}\n", res) };
        output.push_str(&result);
    }

    print!("{}", output);
    Ok(())
}

