fn solve(n: usize, k: i32, mut x: i64, s: &str) {
    let mut res = String::new();
    x -= 1;
    let chars: Vec<char> = s.chars().collect();

    for i in (0..n).rev() {
        if chars[i] == 'a' {
            res.push('a');
        } else {
            let mut count = 1;
            while i >= count && chars[i] == chars[i - count] {
                count += 1;
            }
            let base = (count * k as usize) + 1;
            for _ in 0..x % base as i64 {
                res.push('b');
            }
            x /= base as i64;
            i -= count - 1;
        }
    }

    println!("{}", res.chars().rev().collect::<String>());
}

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    let t: usize = lines.next().unwrap().expect("Failed to read line").trim().parse().unwrap();

    for _ in 0..t {
        let line = lines.next().unwrap().expect("Failed to read line");
        let parts: Vec<&str> = line.split_whitespace().collect();
        let n: usize = parts[0].parse().unwrap();
        let k: i32 = parts[1].parse().unwrap();
        let x: i64 = parts[2].parse().unwrap();
        let s = parts[3];

        solve(n, k, x, s);
    }
}

use std::io::{self, BufRead};

const INF: i64 = 0x3f3f3f3f3f3f3f3f;

struct CF1556E {
    aa: Vec<i64>,
    tmax: Vec<i64>,
    tmin: Vec<i64>,
    n: usize,
}

impl CF1556E {
    fn new() -> Self {
        let mut sc = io::stdin().lock().lines();
        let first_line: Vec<i32> = sc.next().unwrap().unwrap().split_whitespace()
            .map(|s| s.parse().unwrap())
            .collect();
        let n = first_line[0] as usize;
        let q = first_line[1];

        let mut aa = vec![0; n];
        for i in 0..n {
            let line: Vec<i32> = sc.next().unwrap().unwrap().split_whitespace()
                .map(|s| s.parse().unwrap())
                .collect();
            aa[i] = -line[0] as i64 + line[1] as i64;
        }

        for i in 1..n {
            aa[i] += aa[i - 1];
        }

        let mut tmax = vec![INF; n * 2];
        let mut tmin = vec![INF; n * 2];
        for i in 0..n {
            tmax[n + i] = aa[i];
            tmin[n + i] = aa[i];
        }
        for i in (1..n).rev() {
            tmax[i] = tmax[i << 1].max(tmax[i << 1 | 1]);
            tmin[i] = tmin[i << 1].min(tmin[i << 1 | 1]);
        }

        CF1556E { aa, tmax, tmin, n }
    }

    fn qmax(&self, mut l: usize, mut r: usize) -> i64 {
        let mut ans = -INF;
        l += self.n;
        r += self.n;
        while l <= r {
            if (l & 1) == 1 {
                ans = ans.max(self.tmax[l]);
                l += 1;
            }
            if (r & 1) == 0 {
                ans = ans.max(self.tmax[r]);
                r -= 1;
            }
            l >>= 1;
            r >>= 1;
        }
        ans
    }

    fn qmin(&self, mut l: usize, mut r: usize) -> i64 {
        let mut ans = INF;
        l += self.n;
        r += self.n;
        while l <= r {
            if (l & 1) == 1 {
                ans = ans.min(self.tmin[l]);
                l += 1;
            }
            if (r & 1) == 0 {
                ans = ans.min(self.tmin[r]);
                r -= 1;
            }
            l >>= 1;
            r >>= 1;
        }
        ans
    }

    fn main(&mut self, q: i32) {
        let mut sc = io::stdin().lock().lines();
        for _ in 0..q {
            let line: Vec<i32> = sc.next().unwrap().unwrap().split_whitespace()
                .map(|s| s.parse().unwrap())
                .collect();
            let l = (line[0] - 1) as usize;
            let r = (line[1] - 1) as usize;
            let a = if l == 0 { 0 } else { self.aa[l - 1] };
            let b = self.aa[r];
            if a != b || self.qmin(l, r) != a {
                println!("-1");
            } else {
                println!("{}", self.qmax(l, r) - a);
            }
        }
    }
}

fn main() {
    let mut solver = CF1556E::new();
    solver.main(solver.n as i32);
}

use std::io::{self, BufRead, Write};
use std::collections::VecDeque;

struct FastIOAdapter {
    reader: io::BufReader<std::io::Stdin>,
    writer: io::BufWriter<std::io::Stdout>,
    buffer: String,
}

impl FastIOAdapter {
    fn new() -> Self {
        FastIOAdapter {
            reader: io::BufReader::new(io::stdin()),
            writer: io::BufWriter::new(io::stdout()),
            buffer: String::new(),
        }
    }

    fn next(&mut self) -> &str {
        while self.buffer.split_whitespace().count() == 0 {
            self.buffer.clear();
            let _ = self.reader.read_line(&mut self.buffer).unwrap();
        }
        self.buffer.split_whitespace().next().unwrap()
    }

    fn next_int(&mut self) -> i32 {
        self.next().parse().unwrap()
    }

    fn read_array(&mut self, n: usize) -> Vec<i32> {
        (0..n).map(|_| self.next_int()).collect()
    }

    fn println<T>(&mut self, value: T)
    where
        T: std::fmt::Display,
    {
        writeln!(self.writer, "{}", value).unwrap();
    }
}

impl Drop for FastIOAdapter {
    fn drop(&mut self) {
        let _ = self.writer.flush();
    }
}

fn solve(io: &mut FastIOAdapter) {
    let n = io.next_int() as usize;
    let m = io.next_int() as usize;
    let mut a = vec![vec![' '; m]; n];
    for i in 0..n {
        a[i] = io.next().chars().collect();
    }

    let mut lengths = vec![vec![0; m]; n];
    let mut indices = vec![vec![0; m]; n];
    let (mut x, mut y) = (0, 0);
    let mut max_length = 0;

    for i in 0..n {
        for j in 0..m {
            if lengths[i][j] == 0 {
                let mut stack: VecDeque<(usize, usize)> = VecDeque::new();
                stack.push_back((i, j));
                lengths[i][j] = -1;
                indices[i][j] = 0;
                let mut length = 1;
                let mut cycle = 0;
                let (mut cyc_x, mut cyc_y) = (usize::MAX, usize::MAX);

                while let Some((xc, yc)) = stack.back().cloned() {
                    let (mut new_xc, mut new_yc) = (xc, yc);
                    match a[xc][yc] {
                        'U' => new_xc -= 1,
                        'D' => new_xc += 1,
                        'L' => new_yc -= 1,
                        _ => new_yc += 1,
                    }

                    if new_xc >= n || new_yc >= m || new_xc == usize::MAX || new_yc == usize::MAX {
                        break;
                    } else if lengths[new_xc][new_yc] < 0 {
                        cycle -= indices[new_xc][new_yc] - 1;
                        length = cycle + 1;
                        cyc_x = new_xc;
                        cyc_y = new_yc;
                        break;
                    } else if lengths[new_xc][new_yc] > 0 {
                        length = lengths[new_xc][new_yc] + 1;
                        break;
                    } else {
                        lengths[new_xc][new_yc] = -1;
                        indices[new_xc][new_yc] = cycle + 1;
                        stack.push_back((new_xc, new_yc));
                        cycle += 1;
                    }
                }

                let is_cycle = cyc_x != usize::MAX;
                let len = if is_cycle { cycle } else { length };

                while let Some((xy_x, xy_y)) = stack.pop_back() {
                    lengths[xy_x][xy_y] = len;
                    if is_cycle && xy_x == cyc_x && xy_y == cyc_y {
                        break;
                    }
                }

                if max_length < lengths[i][j] {
                    max_length = lengths[i][j];
                    x = i + 1;
                    y = j + 1;
                }
            }
        }
    }

    io.println(format!("{} {} {}", x, y, max_length));
}

