const MOD: i64 = 998244353;

fn bin_pow(mut a: i64, mut b: i64) -> i64 {
    let mut res = 1;
    while b > 0 {
        a %= MOD;
        if b & 1 == 1 {
            res = (res * a) % MOD;
        }
        b >>= 1;
        a = (a * a) % MOD;
    }
    res
}

fn mod_inverse(a: i64) -> i64 {
    bin_pow(a, MOD - 2)
}

fn mul(a: i64, b: i64) -> i64 {
    (a * b) % MOD
}

fn n_cr(n: usize, r: usize, fact: &[i64], inv_fact: &[i64]) -> i64 {
    let mut res = mul(fact[n], inv_fact[r]);
    res = mul(res, inv_fact[n - r]);
    res
}

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();
    let n: usize = lines.next().unwrap().expect("Failed to read line").parse().unwrap();

    let mut ls = Vec::with_capacity(n);
    let mut black = 0;
    let mut white = 0;
    let mut full = false;

    for _ in 0..n {
        let line = lines.next().unwrap().expect("Failed to read line");
        ls.push(line.clone());
        if line.chars().nth(0) == Some('W') {
            white += 1;
        }
        if line.chars().nth(0) == Some('B') {
            black += 1;
        }
        if line.chars().nth(1) == Some('W') {
            white += 1;
        }
        if line.chars().nth(1) == Some('B') {
            black += 1;
        }
        if line.chars().nth(0) != Some('?') && line.chars().nth(0) == line.chars().nth(1) {
            full = true;
        }
    }

    if black > n || white > n {
        println!("0");
        return;
    }

    let mut fact = vec![0; 2 * n + 1];
    let mut inv_fact = vec![0; 2 * n + 1];
    fact[0] = 1;
    inv_fact[0] = 1;

    for i in 1..=2 * n {
        fact[i] = mul(fact[i - 1], i as i64);
        inv_fact[i] = mod_inverse(fact[i]);
    }

    let empty = 2 * n - black - white;
    let mut ans = n_cr(empty, n - black, &fact, &inv_fact);

    if full {
        println!("{}", ans);
        return;
    }

    let mut invalid = 1;
    let mut wb = true;
    let mut bw = true;

    for line in ls.iter() {
        if line.chars().nth(0) == Some('?') && line.chars().nth(1) == Some('?') {
            invalid = mul(invalid, 2);
        }
        if line.chars().nth(0) == Some('B') || line.chars().nth(1) == Some('W') {
            wb = false;
        }
        if line.chars().nth(0) == Some('W') || line.chars().nth(1) == Some('B') {
            bw = false;
        }
    }

    if wb {
        invalid -= 1;
    }
    if bw {
        invalid -= 1;
    }

    ans -= invalid;
    println!("{}", ans);
}

