class FastReader {
    istream* is;
    string line;
    stringstream ss;
public:
    FastReader(istream& in = cin) : is(&in) {}
    string next() {
        if (!ss || ss.peek() == -1) {
            getline(*is, line);
            ss.str(line);
            ss.clear();
        }
        string word;
        ss >> word;
        return word;
    }
    int nextInt() { return stoi(next()); }
    long long nextLong() { return stoll(next()); }
    double nextDouble() { return stod(next()); }
    string nextLine() {
        if (ss && ss.peek() != -1) {
            string rest;
            getline(ss, rest);
            return rest.empty() ? next() : rest;
        } else {
            getline(*is, line);
            return line;
        }
    }
};

