using namespace std;

class Main {
public:
    void solve() {
        int tc;
        cin >> tc;
        while (tc--) {
            int n;
            cin >> n;
            vector<int> A(n);
            for (int i = 0; i < n; ++i) {
                cin >> A[i];
            }

            vector<vector<long long>> D(n + 1, vector<long long>(3, 0));
            const long long mod = 998244353;

            for (int i = n - 1; i >= 0; --i) {
                int u = A[i];
                long long zero = 1LL + D[u][0];
                if (u + 1 <= n) zero += D[u + 1][0];
                if (u + 2 <= n) zero += D[u + 2][1];
                long long one = 1LL + D[u][1];
                if (u > 1) one += D[u - 2][2];
                long long two = 1LL + D[u][2];
                if (u + 2 <= n) two += D[u + 2][1];

                D[u][0] = (D[u][0] + zero) % mod;
                D[u][1] = (D[u][1] + one) % mod;
                D[u][2] = (D[u][2] + two) % mod;
            }

            long long ans = (D[0][0] + D[1][1]) % mod;
            cout << ans << endl;
        }
    }

    int dc(long long a) {
        int r = 0;
        while (a > 0) {
            ++r;
            a /= 10;
        }
        return r;
    }

    int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }
    long long gcd(long long a, long long b) { return b == 0 ? a : gcd(b, a % b); }
    long long mp(long long a, long long p) {
        long long r = 1;
        while (p > 0) {
            if (p & 1) r = (r * a) % mod;
            p >>= 1;
            a = (a * a) % mod;
        }
        return r;
    }
};

int main() {
    Main().solve();
    return 0;
}

