void reverse(int a[], int r) {
    for (int i = 0; i <= r / 2; ++i) {
        swap(a[i], a[r - i]);
    }
}

int main() {
    FastReader input;
    int T = input.nextInt();
    while (T--) {
        int n = input.nextInt();
        vector<int> a(n);
        bool flag = false;
        for (int i = 0; i < n; ++i) {
            a[i] = input.nextInt();
            if ((i + 1) % 2 != a[i] % 2) {
                flag = true;
            }
        }
        if (flag) {
            cout << -1 << endl;
        } else {
            vector<int> list;
            for (int i = n; i > 1; i -= 2) {
                int in1 = 0, in2 = 0;
                for (int j = 0; j < n; ++j) {
                    if (a[j] == i) in1 = j;
                    else if (a[j] == i - 1) in2 = j;
                }
                reverse(&a[0], in1);
                if (in1 > in2) {
                    in2 = in1 - in2;
                }
                reverse(&a[0], in2 - 1);
                reverse(&a[0], in2 + 1);
                reverse(&a[0], 1);
                reverse(&a[0], i - 1);
                list.push_back(in1 + 1);
                list.push_back(in2);
                list.push_back(in2 + 2);
                list.push_back(3);
                list.push_back(i);
            }
            cout << list.size() << endl;
            for (int i = 0; i < list.size(); ++i) {
                cout << list[i] << " ";
            }
            cout << endl;
        }
    }
    return 0;
}

