const int INF = INT_MAX / 2;

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int T;
    std::cin >> T;
    while (T--) {
        int N, D;
        std::cin >> N >> D;
        std::vector<int> arr(N);
        for (int i = 0; i < N; ++i) {
            char c;
            std::cin >> c;
            arr[i] = c - '0';
        }

        std::vector<int> dist(N, INF);
        std::queue<int> q;

        for (int i = 0; i < N; ++i) {
            if (arr[i] == 0) {
                dist[i] = 0;
                q.push(i);
            }
        }

        while (!q.empty()) {
            int curr = q.front();
            q.pop();
            int next = (curr + D) % N;
            if (dist[next] == INF) {
                dist[next] = dist[curr] + 1;
                q.push(next);
            }
        }

        int res = 0;
        for (int x : dist) {
            res = std::max(res, x);
        }
        if (res == INF) {
            res = -1;
        }
        std::cout << res << "\n";
    }
    return 0;
}

