class CF1556E {
public:
    static const long INF = 0x3f3f3f3f3f3f3f3fL;
    std::vector<long> aa, tmax, tmin;
    int n;

    void build() {
        tmax.resize(n * 2);
        tmin.resize(n * 2);
        for (int i = 0; i < n; ++i)
            tmax[n + i] = tmin[n + i] = aa[i];
        for (int i = n - 1; i > 0; --i) {
            tmax[i] = std::max(tmax[i << 1], tmax[i << 1 | 1]);
            tmin[i] = std::min(tmin[i << 1], tmin[i << 1 | 1]);
        }
    }

    long qmax(int l, int r) {
        long ans = -INF;
        for (l += n, r += n; l <= r; l >>= 1, r >>= 1) {
            if ((l & 1) == 1)
                ans = std::max(ans, tmax[l++]);
            if ((r & 1) == 0)
                ans = std::max(ans, tmax[r--]);
        }
        return ans;
    }

    long qmin(int l, int r) {
        long ans = INF;
        for (l += n, r += n; l <= r; l >>= 1, r >>= 1) {
            if ((l & 1) == 1)
                ans = std::min(ans, tmin[l++]);
            if ((r & 1) == 0)
                ans = std::min(ans, tmin[r--]);
        }
        return ans;
    }

    void main() {
        std::cin >> n;
        int q;
        std::cin >> q;
        aa.resize(n);
        for (int i = 0; i < n; ++i)
            aa[i] = -std::cin.nextInt();
        for (int i = 0; i < n; ++i)
            aa[i] += std::cin.nextInt();
        for (int i = 1; i < n; ++i)
            aa[i] += aa[i - 1];
        build();
        while (q-- > 0) {
            int l, r;
            std::cin >> l >> r;
            --l; --r;
            long a = l == 0 ? 0 : aa[l - 1];
            long b = aa[r];
            if (a != b || qmin(l, r) != a)
                std::cout << "-1\n";
            else
                std::cout << qmax(l, r) - a << "\n";
        }
    }
};

int main() {
    CF1556E o;
    o.main();
    return 0;
}

