using namespace std;

class FastIOAdapter {
public:
    istream& in;
    ostream& out;
    istringstream st;

    FastIOAdapter() : in(cin), out(cout) {}

    string next() {
        if (st.eof()) {
            string line;
            getline(in, line);
            st = istringstream(line);
        }
        string token;
        st >> token;
        return token;
    }

    int nextInt() {
        return stoi(next());
    }

    char nextChar() {
        return next()[0];
    }

    void close() {}
};

void solve(FastIOAdapter& io) {
    int n = io.nextInt();
    int m = io.nextInt();
    vector<vector<char>> a(n, vector<char>(m));
    for (int i = 0; i < n; ++i) {
        string line;
        getline(io.in, line);
        for (int j = 0; j < m; ++j) {
            a[i][j] = line[j];
        }
    }

    vector<vector<int>> lengths(n, vector<int>(m, 0));
    vector<vector<int>> indices(n, vector<int>(m, 0));
    int x = 0, y = 0;
    int max_length = 0;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (lengths[i][j] == 0) {
                stack<pair<int, int>> stack;
                stack.push({i, j});
                lengths[i][j] = -1;
                indices[i][j] = 0;
                int length = 1;
                int cycle = 0;
                int cycX = -1, cycY = -1;

                while (true) {
                    auto [xc, yc] = stack.top();
                    if (a[xc][yc] == 'U') {
                        --xc;
                    } else if (a[xc][yc] == 'D') {
                        ++xc;
                    } else if (a[xc][yc] == 'L') {
                        --yc;
                    } else {
                        ++yc;
                    }

                    if (xc < 0 || xc >= n || yc < 0 || yc >= m) {
                        break;
                    } else if (lengths[xc][yc] < 0) {
                        cycle -= indices[xc][yc] - 1;
                        length = cycle + 1;
                        cycX = xc;
                        cycY = yc;
                        break;
                    } else if (lengths[xc][yc] > 0) {
                        length = lengths[xc][yc] + 1;
                        break;
                    } else {
                        lengths[xc][yc] = -1;
                        indices[xc][yc] = ++cycle;
                        stack.push({xc, yc});
                    }
                }

                bool isCycle = cycX != -1;
                int len = isCycle ? cycle : length;

                while (!stack.empty()) {
                    auto [xy_x, xy_y] = stack.top();
                    lengths[xy_x][xy_y] = len;
                    if (isCycle) {
                        if (xy_x == cycX && xy_y == cycY) {
                            isCycle = false;
                            len = length;
                        }
                    } else {
                        ++len;
                    }
                    stack.pop();
                }

                if (max_length < lengths[i][j]) {
                    max_length = lengths[i][j];
                    x = i + 1;
                    y = j + 1;
                }
            }
        }
    }

    io.out << x << " " << y << " " << max_length << endl;
}

int main() {
    FastIOAdapter io;
    int count = io.nextInt();
    while (count-- > 0) {
        solve(io);
    }
    return 0;
}

