        int ans = INT_MAX;
        for (int j = 0; j < 3; ++j) {
            for (int k = 0; k < 3; ++k) {
                // j = # of 1; k = # of 2
                vector<vector<int>> mod3(10, vector<int>(2, INT_MAX));
                mod3[0][0] = 1;
                mod3[0][1] = 0;
                for (int l = 0; l <= j; ++l) {
                    for (int m = 0; m <= k; ++m) {
                        mod3[l + m * 2][0] = 1;
                        mod3[l + m * 2][1] = min(l + m, mod3[l + m * 2][1]);
                    }
                }
