void dfs1(int i, int marker) {
    visM[i] = true;
    cMocha[i] = marker;

    for(int e : mocha[i]) {
        if(!visM[e]) {
            dfs1(e, marker);
        }
    }
}

void dfs2(int i, int marker) {
    visD[i] = true;
    cDiana[i] = marker;

    for(int e : diana[i]) {
        if(!visD[e]) {
            dfs2(e, marker);
        }
    }
}

int marker1(int n) {
    int count = 1;
    for(int i = 1; i <= n ; ++i) {
        if(!visM[i]) {
            dfs1(i, count);
            ++count;
        }
    }
    return count-1;
}

int marker2(int n) {
    int count = 1;
    for(int i = 1; i <= n ; ++i) {
        if(!visD[i]) {
            dfs2(i, count);
            ++count;
        }
    }
    return count-1;
}

