        diana[u].push_back(v);
        diana[v].push_back(u);
    }

    int compsM = marker1(n);
    int compsD = marker2(n);

    int minComps = min(compsD, compsM);

    int ans = 0;
    vector<bool> connD(n + 1, false);
    vector<bool> connM(n + 1, false);

    for(int i = 1; i <= n ; ++i) {
        for (int j = i + 1; j <= n && ans < minComps; ++j) {
            if (cDiana[i] != cDiana[j] && cMocha[i] != cMocha[j]) {
