const long mod = 998244353;

long binPow(long a, long b) {
    long res = 1;
    while (b > 0) {
        a = a % mod;
        if (b & 1) {
            res = (res * a) % mod;
        }
        b >>= 1;
        a = (a * a) % mod;
    }
    return res;
}

long modInverse(long a) {
    return binPow(a, mod - 2);
}

long mul(long a, long b) {
    return (a * b) % mod;
}

long nCr(int n, int r) {
    static std::vector<long> fact(200001), invFact(200001);
    if (fact[0] == 0) {
        fact[0] = 1;
        invFact[0] = 1;
        for (int i = 1; i <= 200000; ++i) {
            fact[i] = mul(fact[i - 1], i);
            invFact[i] = modInverse(fact[i]);
        }
    }
    long res = mul(fact[n], invFact[r]);
    res = mul(res, invFact[n - r]);
    return res;
}

