        if (ls[i][1] == 'B')
            black++;
        if (ls[i][0] != '?' && ls[i][0] == ls[i][1]) {
            full = true;
        }
    }
    if (black > n || white > n) {
        std::cout << 0 << std::endl;
        return 0;
    }

    int empty = 2 * n - black - white;
    long ans = nCr(empty, n - black);
    if (full) {
        std::cout << ans << std::endl;
        return 0;
    }
    long invalid = 1;
    bool WB = true, BW = true;
    for (int i = 0; i < n; ++i) {
        if (ls[i][0] == '?' && ls[i][1] == '?') {
            invalid = mul(invalid, 2);
        }
        if (ls[i][0] == 'B' || ls[i][1] == 'W') {
            WB = false;
        }
        if (ls[i][0] == 'W' || ls[i][1] == 'B') {
            BW = false;
        }
    }
    if (WB)
        invalid--;
    if (BW)
        invalid--;
    ans = ans - invalid;
    std::cout << ans << std::endl;
    return 0;
}

