                                }
                            }
                            reverse(&a, r: in1)
                            if in1 > in2 {
                                in2 = in1 - in2
                            }
                            reverse(&a, r: in2 - 1)
                            reverse(&a, r: in2 + 1)
                            reverse(&a, r: 2)
