let INF = Int.max / 2

func main() {
    let input = FileHandle.standardInput.readDataToEndOfFile()
    guard let inputString = String(data: input, encoding: .utf8) else { return }

    let lines = inputString.split(separator: "\n")
    var index = 0

    if let T = Int(String(lines[index])) {
        var result = ""

        for _ in 0..<T {
            index += 1
            let line = String(lines[index])
            let parts = line.split(separator: " ")

            guard let N = Int(parts[0]), let D = Int(parts[1]) else { continue }
            index += 1

            let arrLine = String(lines[index])
            let arr = arrLine.map { $0.wholeNumberValue! }

            var dist = Array(repeating: INF, count: N)
            var q: [Int] = []

            for i in 0..<N {
                if arr[i] == 0 {
                    dist[i] = 0
                    q.append(i)
                }
            }

            while !q.isEmpty {
                let curr = q.removeFirst()
                var next = curr + D

                if next >= N {
                    next -= N
                }

                if dist[next] == INF {
                    dist[next] = dist[curr] + 1
                    q.append(next)
                }
            }

            let res = dist.max() ?? -1
            result += "\(res)\n"
        }

        print(result, terminator: "")
    }
}

