class C_BA_String {
    static func solve(_ n: Int, _ k: Int, _ x: Int64, _ s: String) {
        var res = ""
        var x = x - 1
        for i in stride(from: n - 1, through: 0, by: -1) {
            if s[s.index(s.startIndex, offsetBy: i)] == "a" {
                res.append("a")
            } else {
                var count = 1
                while i - count >= 0 && s[s.index(s.startIndex, offsetBy: i)] == s[s.index(s.startIndex, offsetBy: i - count)] {
                    count += 1
                }
                let base = Int64(count * k) + 1
                for _ in 0..<x % base {
                    res.append("b")
                }
                x /= base
                i -= count - 1
            }
        }
        print(String(res.reversed()))
    }

    static func main() {
        let input = readLine()!
        let t = Int(input)!
        for _ in 0..<t {
            let line = readLine()!.split(separator: " ")
            let n = Int(line[0])!
            let k = Int(line[1])!
            let x = Int64(line[2])!
