class CF1556E {
    private let INF: Int64 = 0x3f3f3f3f3f3f3f3f
    private var aa: [Int64]!
    private var tmax: [Int64]!
    private var tmin: [Int64]!
    private var n: Int!

    init() {}

    func main() {
        let input = readLine()!.split(separator: " ").compactMap { Int($0) }
        n = input[0]
        let q = input[1]

        aa = Array(repeating: 0, count: n)
        for i in 0..<n {
            aa[i] -= Int64(input[i + 2])
        }
        for i in 0..<n {
            aa[i] += Int64(input[n + 2 + i])
        }
        for i in 1..<n {
            aa[i] += aa[i - 1]
        }

        build()

        for _ in 0..<q {
            let query = readLine()!.split(separator: " ").compactMap { Int($0) }
            let l = query[0] - 1
            let r = query[1] - 1
            let a = (l == 0) ? 0 : aa[l - 1]
            let b = aa[r]
            if a != b || qmin(l, r) != a {
                print(-1)
            } else {
                print(qmax(l, r) - a)
            }
        }
    }

    private func build() {
        tmax = Array(repeating: 0, count: n * 2)
        tmin = Array(repeating: 0, count: n * 2)
        for i in 0..<n {
            tmax[n + i] = aa[i]
            tmin[n + i] = aa[i]
        }
        for i in stride(from: n - 1, through: 1, by: -1) {
            tmax[i] = max(tmax[i << 1], tmax[(i << 1) | 1])
            tmin[i] = min(tmin[i << 1], tmin[(i << 1) | 1])
        }
    }

    private func qmax(_ l: Int, _ r: Int) -> Int64 {
        var ans = -INF
        var left = l + n
        var right = r + n
        while left <= right {
            if (left & 1) == 1 {
                ans = max(ans, tmax[left])
                left += 1
            }
            if (right & 1) == 0 {
                ans = max(ans, tmax[right])
                right -= 1
            }
            left >>= 1
            right >>= 1
        }
        return ans
    }

    private func qmin(_ l: Int, _ r: Int) -> Int64 {
        var ans = INF
        var left = l + n
        var right = r + n
        while left <= right {
            if (left & 1) == 1 {
                ans = min(ans, tmin[left])
                left += 1
            }
            if (right & 1) == 0 {
                ans = min(ans, tmin[right])
                right -= 1
            }
            left >>= 1
            right >>= 1
        }
        return ans
    }
}

