class FastIOAdapter: TextOutputStream, TextInputStream {
    private let input = FileHandle.standardInput
    private let output = FileHandle.standardOutput
    private var buffer: String = ""

    func write(_ string: String) {
        if let data = string.data(using: .utf8) {
            output.write(data)
        }
    }

    func next() -> String? {
        while buffer.isEmpty {
            guard let lineData = input.availableData else { return nil }
            if let line = String(data: lineData, encoding: .utf8)?.trimmingCharacters(in: .whitespacesAndNewlines) {
                buffer += line
            }
        }
        let endIndex = buffer.firstIndex(of: " ") ?? buffer.endIndex
        let result = String(buffer[buffer.startIndex..<endIndex])
        buffer.removeSubrange(buffer.startIndex...endIndex)
        return result.isEmpty ? next() : result
    }

    func nextLine() -> String? {
        while buffer.isEmpty {
            guard let lineData = input.availableData else { return nil }
            if let line = String(data: lineData, encoding: .utf8)?.trimmingCharacters(in: .whitespacesAndNewlines) {
                buffer += line
            }
        }
        let endIndex = buffer.firstIndex(of: "\n") ?? buffer.endIndex
        let result = String(buffer[buffer.startIndex..<endIndex])
        buffer.removeSubrange(buffer.startIndex...endIndex)
        return result.isEmpty ? nextLine() : result
    }

    func nextInt() -> Int? {
        return Int(next() ?? "")
    }

    func readArray(_ n: Int) -> [Int] {
