func solve(_ io: FastIOAdapter) {
    guard let n = io.nextInt(), let m = io.nextInt() else { return }
    var a = [[Character]]()
    for _ in 0..<n {
        if let line = io.nextLine() {
            a.append(Array(line))
        }
    }

    var lengths = Array(repeating: Array(repeating: 0, count: m), count: n)
    var indices = Array(repeating: Array(repeating: 0, count: m), count: n)
    var x = 0, y = 0
    var max = 0

    for i in 0..<n {
        for j in 0..<m {
            if lengths[i][j] == 0 {
                var stack: [(Int, Int)] = []
                stack.append((i, j))
                lengths[i][j] = -1
                indices[i][j] = 0
                var length = 1
                var cycle = 0
                var cycX = -1, cycY = -1

                while true {
                    let (xc, yc) = stack.last!
                    var newX = xc, newY = yc

                    switch a[xc][yc] {
                    case "U": newX -= 1
                    case "D": newX += 1
                    case "L": newY -= 1
                    default: newY += 1
                    }

                    if newX < 0 || newX >= n || newY < 0 || newY >= m {
                        break
                    } else if lengths[newX][newY] < 0 {
                        cycle -= indices[newX][newY] - 1
                        length = cycle + 1
                        cycX = newX
                        cycY = newY
                        break
                    } else if lengths[newX][newY] > 0 {
                        length = lengths[newX][newY] + 1
                        break
                    } else {
                        lengths[newX][newY] = -1
                        indices[newX][newY] = cycle + 1
                        stack.append((newX, newY))
                        cycle += 1
                    }
                }

                let isCycle = cycX != -1
                let len = isCycle ? cycle : length

                while !stack.isEmpty {
                    let (xc, yc) = stack.removeLast()
                    lengths[xc][yc] = len
                    if isCycle && xc == cycX && yc == cycY {
                        break
                    }
                }

                if max < lengths[i][j] {
                    max = lengths[i][j]
                    x = i + 1
                    y = j + 1
                }
            }
        }
    }

    io.write("\(x) \(y) \(max)\n")
}

func main() {
    let ioAdapter = FastIOAdapter()
    guard let count = ioAdapter.nextInt() else { return }
    for _ in 0..<count {
        solve(ioAdapter)
    }
}

