class D: Constant {
    static let br = FileHandle.standardInput
    static let pw = FileHandle.standardOutput

    static var fact: [Int64] = []
    static var invFact: [Int64] = []

    static func binPow(_ a: Int64, _ b: Int64) -> Int64 {
        var res: Int64 = 1
        var base = a % mod
        var exp = b

        while exp > 0 {
            if exp & 1 == 1 {
                res = (res * base) % mod
            }
            exp >>= 1
            base = (base * base) % mod
        }

        return res
    }

    static func modInverse(_ a: Int64) -> Int64 {
        return binPow(a, mod - 2)
    }

    static func mul(_ a: Int64, _ b: Int64) -> Int64 {
        return (a * b) % mod
    }

    static func nCr(_ n: Int, _ r: Int) -> Int64 {
        var res = mul(fact[n], invFact[r])
        res = mul(res, invFact[n - r])
        return res
    }

    static func main() {
        guard let nStr = String(data: br.availableData, encoding: .utf8),
              let n = Int(nStr.trimmingCharacters(in: .whitespacesAndNewlines)) else { return }

        var ls: [String] = []
        var full = false
        var black = 0, white = 0

        for _ in 0..<n {
            guard let line = String(data: br.availableData, encoding: .utf8) else { continue }
            ls.append(line.trimmingCharacters(in: .whitespacesAndNewlines))

            if line.hasPrefix("W") {
                white += 1
            }
            if line.hasPrefix("B") {
                black += 1
            }
            if line.dropFirst().hasPrefix("W") {
                white += 1
            }
            if line.dropFirst().hasPrefix("B") {
                black += 1
            }
            if !line.hasPrefix("?") && line.first == line.dropFirst().first {
                full = true
            }
        }

        if black > n || white > n {
            pw.write("0\n".data(using: .utf8)!)
            return
        }

        fact = [Int64](repeating: 0, count: 2 * n + 1)
        invFact = [Int64](repeating: 0, count: 2 * n + 1)
        fact[0] = 1
        invFact[0] = 1

        for i in 1...2 * n {
            fact[i] = mul(fact[i - 1], Int64(i))
            invFact[i] = modInverse(fact[i])
        }

        let empty = 2 * n - black - white
        var ans = nCr(n, n - black)

        if full {
            pw.write("\(ans)\n".data(using: .utf8)!)
            return
        }

        var invalid: Int64 = 1
        var WB = true, BW = true

        for line in ls {
            if line == "??" {
                invalid = mul(invalid, 2)
            }
            if line.hasPrefix("B") || line.dropFirst().hasPrefix("W") {
                WB = false
            }
            if line.hasPrefix("W") || line.dropFirst().hasPrefix("B") {
                BW = false
            }
        }

        if WB {
            invalid -= 1
        }
        if BW {
            invalid -= 1
        }

        ans -= invalid
        pw.write("\(ans)\n".data(using: .utf8)!)
    }
}

