    guard let data = input.readDataToEndOfFile(), let string = String(data: data, encoding: .utf8) else {
        return
    }

    let lines = string.split(separator: "\n")
    var index = 0

    func readInt() -> Int {
        while index < lines.count {
            if let number = Int(lines[index]) {
                index += 1
                return number
            }
            index += 1
        }
        return 0
    }

    let t = readInt()
    for _ in 0..<t {
        let c = readInt()
        let d = readInt()

        if c == d && c != 0 {
            output.write("1\n".data(using: .utf8)!)
        } else if c == d {
            output.write("0\n".data(using: .utf8)!)
        } else {
            var k = c - d
            if k < 0 {
                k *= -1
            }
            if k % 2 != 0 {
                output.write("-1\n".data(using: .utf8)!)
            } else {
                output.write("2\n".data(using: .utf8)!)
            }
        }
    }
}

main()

import Foundation

//----------- FastScanner class for faster input---------------------------
class FastScanner {
    private let reader: String
    private var tokens: [String]

    init() {
        reader = readLine() ?? ""
        tokens = reader.split(separator: " ").map { String($0) }
    }

    func next() -> String {
        if tokens.isEmpty {
            reader = readLine() ?? ""
            tokens = reader.split(separator: " ").map { String($0) }
        }
        return tokens.removeFirst()
    }

    func nextInt() -> Int {
        return Int(next())!
    }
}

//----------- Main class with the main logic------------------------------
class Main {
    static var out = ""

    static func main() {
        let fs = FastScanner()

        /******  CODE STARTS HERE  *****/

        let n = fs.nextInt(), m = fs.nextInt()
        var a: [[Character]] = []
        for _ in 0..<n {
            a.append(Array(fs.next()))
        }

        var c = [Int](repeating: 0, count: m)
        for i in 1..<m {
            var f = false
            for j in 1..<n {
                if a[j-1][i] == "X" && a[j][i-1] == "X" {
                    f = true
                    break
                }
            }
            if f { c[i] = 1 }
        }

        var dp = [Int](repeating: 0, count: m)
        for i in 1..<m {
            if c[i] == 1 { dp[i] = dp[i-1] + 1 } else { dp[i] = dp[i-1] }
        }

        let q = fs.nextInt()
        for _ in 0..<q {
            let x1 = fs.nextInt() - 1
            let x2 = fs.nextInt() - 1
            if x1 == x2 { out.append("YES\n") } else if dp[x1] < dp[x2] { out.append("NO\n") } else { out.append("YES\n") }
        }

        print(out, terminator: "")
    }
}

// Entry point of the program
Main.main()
